// AUTO-GENERATED by `npm run build` from src/melon_drive/ — do not edit directly.
import { Instance, CustomCameraMode, PointTemplate, CSMoveType, CSInputs } from 'cs_script/point_script';

// Toggle to false once driving works to quiet the console back down.
const DEBUG = false;
// (The jump/contact debug view is separate — toggled per player from the
// user menu, see dev/collision-debug.js.)

/** @param {string} text */
function Debug(text) {
    if (DEBUG) {
        Instance.Msg(`[melon_drive] ${text}`);
    }
}

// Every kart's prediction-line dot entities (see fx/prediction/prediction.js). They sit
// right on the melon's line of travel, so a trace along it — the prediction
// line's own, or the wall bounce's — would otherwise hit the first dot
// instead of the actual wall if the dot template's entity is solid for
// traces (e.g. a func_brush left at its default solidity). Entity variables
// are reference-stable, so a Set lookup on trace.hitEntity works.
/** @type {Set<any>} */
const predictionDotSet = new Set();

const MAX_DOT_SKIPS = 4;

/**
 * Runs a trace, and if it hit a prediction dot, re-runs it with that dot
 * added to ignoreEntity — up to MAX_DOT_SKIPS times, after which it's
 * reported as a miss rather than as a (bogus) hit on a dot.
 * @template {{ ignoreEntity?: any }} C
 * @param {(config: C) => any} traceFn @param {C} config
 */
function SkipDots(traceFn, config) {
    let current = config;
    for (let i = 0; i <= MAX_DOT_SKIPS; i++) {
        const result = traceFn(current);
        if (!result.didHit || !result.hitEntity || !predictionDotSet.has(result.hitEntity)) {
            return result;
        }
        const ignored = current.ignoreEntity === undefined ? [] : [].concat(current.ignoreEntity);
        current = { ...current, ignoreEntity: [...ignored, result.hitEntity] };
    }
    return { ...traceFn(current), didHit: false };
}

/** Instance.TraceLine, but never stops on a prediction dot. @param {Parameters<typeof Instance.TraceLine>[0]} config */
function TraceLine(config) {
    return SkipDots((c) => Instance.TraceLine(c), config);
}

/** Instance.TraceSphere, but never stops on a prediction dot. @param {Parameters<typeof Instance.TraceSphere>[0]} config */
function TraceSphere(config) {
    return SkipDots((c) => Instance.TraceSphere(c), config);
}

/**
 * @typedef {{
 *   pawn: any, melon: any,
 *   wallJumpCharge: number, // wall jumps charged, 0..WALL_JUMP_CHARGES (fractional while one refills) — the HUD jump icons
 *   lastJumpTime?: number, // last ground jump — the next needs a newer ground contact, see CanGroundJump
 *   health: number, lastVelocity: { x: number, y: number, z: number } | undefined,
 *   trackId: number | undefined, checkpointIndex: number, checkpointPosition: any, checkpointAngles: any,
 *   lapsCompleted: number, inHub: boolean, racing: boolean, finished: boolean, locked: boolean,
 *   runStartTime?: number, // game time this kart's timed run started (unset: no run) — see race/time-trial/time-trial.js
 *   lastRun?: { trackId: number, time: number, newBest: boolean, at: number }, // last finished run, for the HUD
 *   finishRestartAt?: number, // game time a free-roaming finish sent the melon back to the start — see FINISH_RESTART_START_GUARD
 *   breaking: boolean, breakTime?: number, // game time BreakMelon ran, for the break camera zoom
 *   paintColor: { r: number, g: number, b: number, a: number }, userMenuOpen: boolean, hubModalOpen: boolean,
 *   settled: boolean,
 *   pawnAnchor: any, // where the frozen pawn is held — see HoldPawn
 *   teleportGen: number, // bumped by every race-flow teleport (BeginHeat/ReturnAllToHub) — see ScheduleRespawnAfterBreak
 *   speedCap?: number, // current horizontal speed limit; above the momentum top speed only while a wall-bounce/attack boost decays — unset means that top speed
 *   momentum?: import("../movement/momentum/logic.js").MomentumState, // top-speed steps earned by repeatedly reaching it (unset: none) — see MOMENTUM_*
 *   boostTrail?: { melon: any, entities: any[] }, // the boost trail running on this melon (unset: none) — see fx/boost-trail/boost-trail.js
 *   nextBounceTime?: number, lastBounceTime?: number, // wall-bounce timing, see UpdateKart
 *   lastBounceInfo?: { angle: number, angleFactor: number, jumpFactor: number }, // last bounce's result, for the HUD
 *   hudHealthSegments?: number, hudJumpReady?: boolean[], // what the health bar / jump dots last sent to the HUD — see UpdateHealthHud/UpdateJumpHud
 *   hudResendAt?: { health?: number, jump?: number }, // when they send their whole state again — see HUD_RESEND_SECONDS
 *   lastJumpPressTime?: number, lastIdleJumpPressTime?: number, wallTimingPressTime?: number, wallTimingLockedUntil?: number, // jump presses (the last one that did nothing: no ground/wall jump) and wall-bounce timing, see RegisterWallTimingPress
 *   floorNormalZ?: number, // this tick's floor trace normal z (undefined: nothing below) — flat landings cost more, see ImpactDamage
 *   lastGroundedTime?: number, // last tick the melon had ground contact — gates jumping, see UpdateGrounded
 *   lastWallContact?: { time: number, normal: { x: number, y: number }, approach?: { x: number, y: number }, approachTime?: number }, // last wall touched in the air (probe or bounce), with how the melon came at it — see UpdateWallContact
 *   lastWallJump?: { time: number, normal: { x: number, y: number } }, // see CanWallJump
 *   bufferedWallJumpTime?: number, // a lift-zone jump press not yet used, fired on the next wall touch — see LIFT_ZONE_JUMP_BUFFER
 *   perfectBounceBoost?: boolean, // its speed above MAX_SPEED is from a PERFECT bounce — no boost trail for that, see fx/boost-trail/boost-trail.js
 *   attackBoosting?: boolean, // the attack boost is on this tick — shows the boost trail, see fx/boost-trail/boost-trail.js
 *   attackGuardUntil?: number, // until when engine pushes from attack are cancelled — see ATTACK_PUSH_GUARD_SECONDS
 *   nextAttackDebugTime?: number, // when dev/attack-debug.js may log this kart's attack state again
 *   collisionDebug?: boolean, // this player's collision debug view is on (user menu toggle) — see dev/collision-debug.js
 *   freeLook?: boolean, // this player flies their pawn through the map, melon frozen (user menu toggle, off by default) — see dev/free-look.js
 *   contactDebug?: import("../dev/collision-debug.js").ContactDebug, // what this tick's probes saw, for that view
 *   prevLastVelocity?: { x: number, y: number, z: number }, prevOrigin?: any, // one tick further back than lastVelocity, for wall-bounce angle measurement
 *   painted?: boolean, // paintColor was chosen (trigger or user menu), not the unpainted default — see kart/look.js
 *   melonGlow?: boolean, // this player's melon has its outline glow (user menu toggle, on by default) — see kart/look.js
 *   predictionLine?: boolean, // this player's prediction line is on (user menu toggle, off by default) — see fx/prediction/prediction.js
 *   predictionDots?: any[], // this kart's prediction-line dot entities, see fx/prediction/prediction.js
 *   pendingBounce?: { time: number, impactSpeed: number, impactDir: { x: number, y: number, z: number }, angle: number, angleFactor: number, jumpFactor: number, speedGain: number }, // damage not yet charged — waits out the jump window, see SettleWallBounceDamage
 *   healZones?: Map<any, number>, // heal triggers the melon is inside -> their rate (health/s), see health/heal/zone.js
 *   liftCameraBlend?: number, // 0..1, how far the camera is zoomed out for a lift zone — see UpdateLiftCamera
 *   cameraWallScale?: number, // 0..1, how much of the camera offset is left after a wall pulled it in — see camera/wall-clip/
 *   appliedFollowKey?: string, // the follow offset last written to the engine — see ApplyZonedFollowOffset
 *   liftZones?: Map<any, number>, // lift triggers the melon is inside -> their wall-bounce kick (u/s up), see zones/registry.js
 *   jumpPads?: Map<any, import("../zones/jump-pad/logic.js").JumpPad>, // jump pad triggers the melon is on -> their launch, see zones/registry.js
 *   lastPadLaunchTime?: number, // last jump pad launch — see ShouldPadLaunch
 *   waterZones?: Map<any, number>, // water triggers the melon is inside (value unused), see zones/water/
 *   jumpRecharges?: Map<any, number>, // jump recharge triggers the melon is inside (value unused), see zones/jump-recharge/
 *   padFlight?: import("../zones/jump-pad/logic.js").PadFlight, // a jump pad launch's damage protection, still on — see zones/jump-pad/jump-pad.js
 *   cameraZones?: Map<any, import("../zones/camera-zone/logic.js").CameraZone>, // camera triggers the melon is inside -> their zoom, see zones/registry.js
 *   zoneCamera?: import("../zones/camera-zone/logic.js").ZoneCameraState, // the camera-zone zoom being eased in/out — see UpdateZoneCamera
 *   sideViews?: Map<any, import("../zones/side-view/logic.js").SideView>, // side-view triggers the melon is inside -> their view, see zones/registry.js
 *   sideViewDrive?: { zone: import("../zones/side-view/logic.js").SideView, plane: number, facing: 1 | -1 }, // the side view being driven in: its plane and which way the melon faces on screen — see UpdateKart
 *   sideViewBlend?: number, // 0..1, how far the camera has swung to the side — see UpdateSideViewCamera
 *   sideViewZone?: import("../zones/side-view/logic.js").SideView, sideViewLast?: import("../zones/side-view/logic.js").SideView, // the side view the camera is in / swinging out of — see UpdateSideViewCamera
 *   lastKnownPosition: any, lastKnownAngles: any, // set once the melon's first seen valid; unset only for a session's very first tick
 * }} Kart
 */
/** @type {Map<number, Kart>} */
const karts = new Map();

// The first player to get a kart becomes the moderator, who can abort a
// heat that's already running (see "Moderator" in GAMEPLAY.md). If they
// disconnect, the next-oldest remaining player is promoted so there's
// always a moderator whenever anyone is on the map.
/** @type {number | undefined} */
let moderatorSlot = undefined;

/** @param {number | undefined} slot */
function SetModeratorSlot(slot) {
    moderatorSlot = slot;
}

// Safety net: moderatorSlot can otherwise go stale without a clean
// OnPlayerDisconnect firing for the old holder — a tools-mode script/map
// reload, or a kart getting pruned by Think's invalid-melon/pawn check (see
// core/think.js) — leaving it pointing at a slot nobody occupies. Left unchecked,
// that permanently hides the abort button from every remaining player
// (IsModerator never matches), which is exactly what strands a solo
// player unable to abort a heat nobody's actually racing. Called every
// Think tick (after invalid karts are pruned) and on disconnect.
function EnsureModerator() {
    if (moderatorSlot !== undefined && karts.has(moderatorSlot)) {
        return;
    }
    const next = karts.keys().next();
    const reassigned = next.done ? undefined : next.value;
    if (reassigned !== moderatorSlot) {
        Debug(`EnsureModerator: moderatorSlot ${moderatorSlot} has no live kart, reassigning to ${reassigned}`);
        moderatorSlot = reassigned;
    }
}

/** @param {number | undefined} slot */
function IsModerator(slot) {
    return slot !== undefined && slot === moderatorSlot;
}

/**
 * Stops tracking a kart and removes its melon from the world with it —
 * otherwise the melon would stay behind as an orphaned physics prop that the
 * player's next melon spawns on top of.
 * @param {number} slot @param {Kart} kart
 */
function DropKart(slot, kart) {
    if (kart.melon.IsValid()) {
        kart.melon.Remove();
    }
    for (const entity of kart.boostTrail?.entities ?? []) {
        if (entity.IsValid()) {
            entity.Remove();
        }
    }
    for (const dot of kart.predictionDots ?? []) {
        predictionDotSet.delete(dot);
        if (dot.IsValid()) {
            dot.Remove();
        }
    }
    karts.delete(slot);
}

/** @param {any} melon */
function FindKartByMelon(melon) {
    for (const kart of karts.values()) {
        if (kart.melon === melon) {
            return kart;
        }
    }
    return undefined;
}

// Driving: acceleration, speed cap, friction, and how a melon settles at rest.

// Force ratios ported from the original melonracer GMod gamemode
// (sent_melon_base/init.lua ENT:Think + gamemode/shared.lua DefXSpeed):
// forward is the strongest push, reverse is half that, strafe is weaker
// still — keeping FORWARD_ACCEL as our existing tuned baseline.
const FORWARD_ACCEL = 325; // units/sec^2 while holding forward (was 900, then 500, then 400, then 450 — a heavier, slower build-up: ~2s to MAX_SPEED)
const REVERSE_ACCEL = FORWARD_ACCEL * 0.5; // 0.5x forward, matches original's Reverse/Forward ratio
const STRAFE_ACCEL = FORWARD_ACCEL * 0.4; // 0.4x forward, matches original's Strafe/Forward ratio
const MAX_SPEED = 650; // units/sec, horizontal speed cap
const COAST_FRICTION = 120; // units/sec^2 horizontal slowdown with no input — low, so the melon keeps rolling on its own momentum instead of grinding to a stop

// Below this horizontal AND vertical speed, with no steering/jump input,
// the melon counts as fully settled — UpdateKart stops re-pinning its
// velocity/spin to zero every tick and lets vphysics run it completely
// freely, so its own weight and (irregular) resting shape can tip or slide
// it exactly as real physics dictates instead of gluing it to whatever spot
// it stopped at.
const MELON_REST_SPEED = 2; // units/sec

// The instant a melon crosses into "fully settled" (see MELON_REST_SPEED
// above), vphysics owns its orientation completely — but a perfectly
// balanced landing (e.g. resting dead upright on end) is a knife-edge
// equilibrium that a deterministic physics sim has no numerical noise to
// break on its own, so it would otherwise freeze there forever instead of
// tipping onto a stable side. UpdateKart gives it one small, random-direction
// spin nudge the moment it settles to break that tie; real vphysics then
// decides — from the melon's actual collision shape and whatever surface
// it's resting on — whether that nudge grows into a proper topple or just
// gets damped straight back to rest.
const SETTLE_NUDGE_ANGULAR_SPEED = 40; // deg/sec, one-off pitch/roll kick on settling

// Steering grip: while holding forward on the ground, the melon's horizontal
// velocity is turned towards the look direction by up to STEER_GRIP_RATE
// degrees per second, keeping its speed — so it goes where the camera points
// instead of only being pushed that way by FORWARD_ACCEL (which at MAX_SPEED
// turned it slowly, like a hovercraft). Only for velocity that is at most
// STEER_GRIP_MAX_ANGLE off the look direction: looking back or far to the
// side is braking/turning around via plain acceleration, not a snap U-turn.
// Higher STEER_GRIP_RATE: more direct, less drift. 0 = off (old behavior).
const STEER_GRIP_RATE = 180; // degrees/sec
const STEER_GRIP_MAX_ANGLE = 100; // degrees
// The same grip in the air (jumps, falls, after a wall bounce), at its own
// rate — without it, FORWARD_ACCEL alone barely turned a melon at speed.
// The bounce tick itself is never steered, so the reflected angle is applied
// as computed; lower this if bounces should keep their angle longer. 0 = no
// air steering beyond plain acceleration.
const STEER_AIR_GRIP_RATE = 180; // degrees/sec

// Jumping: ground jump, wall jump, and the ground contact they rely on (see movement/contact/logic.js).

const JUMP_SPEED = 370; // units/sec upward impulse
// The ground jump needs real ground contact (see movement/contact/logic.js), and a
// new one since the last jump — no cooldown: touching down is what resets
// it. (The "new contact" part stops a second press within
// GROUND_COYOTE_TIME of taking off from jumping again.)
//
// Ground contact is measured, not guessed from distance: each tick the
// vertical velocity we commanded is compared with what physics made of it.
// In the air gravity pulls it down by the full GRAVITY; anything holding
// the melon up (the floor, a slope) cancels part of that. So "supported" =
// the vertical acceleration was clearly less than free fall — independent
// of the melon's (non-round) shape, and a melon hovering just above the
// floor is correctly "in the air". A short line trace down then confirms
// what's holding it up is floor-like (GROUND_NORMAL_MIN_Z), not a wall or
// an edge. GROUND_COYOTE_TIME only bridges the tiny hops a rolling,
// egg-shaped melon makes — keep it short.
const GRAVITY = 800; // units/sec^2 — CS2's sv_gravity, what vphysics pulls the melon down with
const FREE_FALL_FRACTION = 0.8; // vertical accel at or below -FREE_FALL_FRACTION * GRAVITY counts as falling freely (not supported); lower = stricter
// Units down from the melon's center the floor-confirming trace reaches.
// A resting melon's center sits only ~7 units above the floor (see the
// floor distance in the DEBUG overlay / jump log), so this is its half
// height, rolled onto its long side or on a slope, plus a small margin. It
// used to be 48, which found the floor while the melon was still ~40 units
// up in a jump — together with a moment of measured "support" that allowed
// a jump in mid-air.
const GROUND_CHECK_DISTANCE = 20;
const GROUND_NORMAL_MIN_Z = 0.5; // surface must be at least this floor-like (not a wall) to count as ground
const GROUND_COYOTE_TIME = 0.08; // seconds a ground contact stays valid after losing it — only bridges rolling hops
// Right after a jump (ground or wall) the floor can still be pushing the
// melon up for a tick, which reads exactly like support — so ground contact
// doesn't count for this long after any jump. Otherwise a second press just
// after taking off jumped again in mid-air.
const GROUND_LIFTOFF_TIME = 0.15; // seconds

// Wall jump: in the air, at a wall (a line trace in any of
// WALL_PROBE_DIRECTIONS horizontal directions finds a steep surface within
// WALL_JUMP_CONTACT_RADIUS of the melon's center, plus one tick's travel
// towards it — see WallContactReach — or a wall bounce just happened) and
// pressing jump pushes the melon off that wall and up. The timing is that
// distance: press while the wall is right at the melon, not some time after.
// Charges (the HUD's jump icons): the melon holds WALL_JUMP_CHARGES wall
// jumps, each one full strength (WALL_JUMP_UP_SPEED / WALL_JUMP_PUSH_SPEED)
// and using up one; with none left there's no wall jump. They refill one
// after the other, WALL_JUMP_RECHARGE_SECONDS each. A plain wall jump never
// raises the melon's speed cap, so chaining them can't build up speed (only
// an angle rating's bonus does, see WALL_JUMP_RATING_SPEED_MULTIPLIER).
// Can't climb one wall forever: after a wall jump, the next one
// needs ground contact first or a different wall (normal differing by more
// than WALL_JUMP_SAME_WALL_DOT) — bouncing between two facing walls chains.
// Enough directions that the tight contact ring has no gaps: a wall between
// two probes is hit at up to 1/cos(180°/N) times its real distance (16:
// +2%, 8 was +8%).
const WALL_PROBE_DIRECTIONS = 16;
// Units from the melon's center to the wall's plane at which the wall is at
// the melon. Measured from the center: traces onto the melon's own surface
// find nothing in-engine. Measured in-game with the collision debug view: a
// melon lying right against a wall has its center 6.7 from it (6.9 above
// the floor), and it's only ~10% longer than wide, so ~8 at most with its
// tip at the wall. 7 (tuned in-game) is just past lying flat against it: a
// melon resting tip-first at a wall doesn't count, but one moving into the
// wall does, since one tick's travel towards it is added (WallContactReach).
// Much more (16) lets a wall ~9 units off the melon's surface count.
// Higher: more forgiving; lower: the press has to be closer to the touch —
// below 6.7 not even a melon lying flat against the wall counts.
const WALL_JUMP_CONTACT_RADIUS = 7; // units
// Seconds a wall contact stays jumpable after the melon was last at the wall
// — only a tick or two: a melon that hits a wall is pushed off it at once,
// so the press on the touch can land a tick late. (Lift zones: longer, see
// LIFT_ZONE_WALL_JUMP_WINDOW.)
const WALL_JUMP_WINDOW = 0.035; // seconds
const WALL_JUMP_COOLDOWN = 0.45; // seconds between two wall jumps (was 0.3)
const WALL_JUMP_CHARGES = 3; // wall jumps in a row, each full strength (was a 0..1 charge, half used per jump, weaker each time)
const WALL_JUMP_RECHARGE_SECONDS = 2; // seconds to refill one wall jump — they refill one after the other, empty -> full = WALL_JUMP_CHARGES × this
const WALL_JUMP_UP_SPEED = 240; // units/sec upward — well below the ground jump's JUMP_SPEED (was 380)
const WALL_JUMP_PUSH_SPEED = 160; // units/sec at least away from the wall (more if already moving away faster) (was 250)
const WALL_JUMP_SAME_WALL_DOT = 0.7; // normals closer than this (dot product, ~45°) count as the same wall
// Wall jump angle rating — the wall bounce's PERFECT hit, for wall jumps:
// the angle the melon came at the wall (from the wall normal, 0 = head-on,
// 90 = along it) gets the same rating as a bounce (BOUNCE_RATINGS, 45° =
// PERFECT, see WallJumpAngle in ./logic.js), shown on the bounce panel, a
// PERFECT with the spark. A rating with a multiplier above 1 boosts it like
// a bounce: it leaves with the full speed it came in with (not what's left
// after the wall stopped it) times this, in the wall jump's direction (see
// WallJumpBoostedVelocity). Keyed by BOUNCE_RATINGS[].label — no penalty
// below GOOD, a plain wall jump stays as it was. Any gain lifts the speed cap like
// a bounce (decays at BOOST_DECAY); charge and the same-wall rule still
// limit chaining. A PERFECT also kicks WALL_JUMP_PERFECT_UP_MULTIPLIER
// harder upward.
const WALL_JUMP_RATING_SPEED_MULTIPLIER = { PERFECT: 1.35, GOOD: 1.1, BAD: 1, MISS: 1 };
const WALL_JUMP_PERFECT_UP_MULTIPLIER = 1.2;
// The angle is the melon's approach, remembered when the wall contact starts
// (kart.lastWallContact.approach, see WallApproach): once it touches the
// wall, physics stops it there and it only slides along — a press a tick or
// two late used to read that slide as 90° (MISS). The remembered approach
// counts for this long after the contact started — longer and a melon that
// slid along a wall for a while could still cash in its old approach.
const WALL_JUMP_APPROACH_MEMORY = 0.15; // seconds

// Jump pads: a trigger_multiple (filtered to prop_physics) with
// OnStartTouch -> RunScriptInput "jump_pad_enter" and OnEndTouch ->
// "jump_pad_leave". Pressing jump while the melon is on it (or just before it
// gets there, JUMP_PAD_BUFFER) launches it much higher and further than a
// normal jump — no press, no launch: the timing is the skill. From the pad
// until shortly after landing the melon takes no damage (landing, crashes,
// wall hits). Rule: ../logic/jump-pad.js, applied by ../physics/jump-pad.js.

// Per pad, the name can set both values: "jump_pad_<up>_<forward>" (e.g.
// "jump_pad_1000_400"), "jump_pad_<up>" (forward boost default); any other
// name uses the defaults below.
const JUMP_PAD_NAME_PATTERN = /^jump_pad_(\d+(?:\.\d+)?)(?:_(\d+(?:\.\d+)?))?$/;
// Upward speed of the launch (units/sec). Height ≈ speed² / 1600 (gravity
// 800): 850 -> ~450 units, 1000 -> ~625; a normal jump (JUMP_SPEED 370) is ~85.
const JUMP_PAD_UP_SPEED = 850;
// Horizontal speed added along the direction the melon is going (units/sec).
// Lifts the speed cap like a wall-bounce boost, then decays at BOOST_DECAY.
// Higher: much further. 0: only higher, not further.
const JUMP_PAD_FORWARD_BOOST = 250;
// Slower than this, the melon has no clear direction of its own — the boost
// then goes along the look direction.
const JUMP_PAD_MIN_DIRECTION_SPEED = 50; // units/sec
// A jump pressed up to this long before touching the pad still launches on
// the touch (e.g. jumping onto it).
// Higher: more forgiving timing. 0: only a press while on the pad counts.
const JUMP_PAD_BUFFER = 0.2; // seconds
// No second launch from the same press/pad within this long.
const JUMP_PAD_COOLDOWN = 0.5; // seconds
// No damage from the launch until this long after touching ground again
// (the landing often spreads over a few ticks and rolls)...
const JUMP_PAD_LANDING_GRACE = 0.3; // seconds
// ...and at most this long after the launch, even without landing.
const JUMP_PAD_MAX_PROTECTED_SECONDS = 6;

// Water zones: a trigger_multiple (filtered to prop_physics like the other
// triggers) around a func_water, with OnStartTouch -> RunScriptInput
// "water_enter" and OnEndTouch -> "water_leave". The script can't see
// func_water itself, so the trigger is what tells it the melon is in water.
// Landing in it, the melon loses its momentum at once (speed, spin, boosted
// speed cap, momentum steps); while inside, the water's drag and buoyancy
// aren't read as impacts — no wall bounces, no impact damage there.
// Rule: zones/water/logic.js, applied by zones/water/water.js.

// How much of its speed (and spin) the melon keeps on entering the water.
// 0: stops dead. 0.2: keeps a fifth of it.
const WATER_ENTRY_SPEED_KEEP = 0;

// Melon health and impact damage from landings/crashes (wall hits have their own rules in wall-bounce.js).

// Impact damage: every tick we compare the velocity we commanded last tick
// against the melon's actual velocity now. A big gap means physics forcibly
// overrode our command — a wall crash or a hard landing — since gravity and
// our own steering only ever change velocity gradually. That gap's
// magnitude is the "impact speed" damage is based on:
//   damage = (impactSpeed - IMPACT_DAMAGE_THRESHOLD) * IMPACT_DAMAGE_SCALE
// e.g. a 700 u/s impact = (700 - 450) * 0.2 = 50 of MELON_MAX_HEALTH's 70.
// Landing flat on level ground: times FLAT_LANDING_DAMAGE_MULTIPLIER (below).

// The melon's health pool (kart.health), refilled on every respawn at a
// checkpoint (after a break or via the user menu). Shared by landing/crash damage here and wall-hit damage
// (WALL_IMPACT_DAMAGE_* / WALL_BOUNCE_DAMAGE_PER_SPEED in wall-bounce.js).
// The HUD bar shows it as a fraction, so changing it doesn't change the bar.
// Higher: more or harder hits before the melon breaks — more forgiving,
//   crashes matter less, wall bounces that cost health can be chained longer.
// Lower: fewer hits until it breaks — punishing; at or below one typical
//   hard landing's damage (~50 above), a single bad jump breaks it.
const MELON_MAX_HEALTH = 70; // was 80 — every hit now takes ~14% more of the pool
// The melon entity's *engine* health (not kart.health above) — set this high
// on every spawn so the engine's own physics damage never destroys the prop,
// regardless of its Hammer health/damage settings. See MakeUnbreakableByEngine.
// Not a gameplay knob: only has to stay far above anything the engine's
// physics damage could deal.
// Higher: no effect.
// Lower: the engine may destroy the melon prop itself on a hard hit, outside
//   our break/respawn logic — the kart loses its melon instead of breaking
//   and respawning properly.
const MELON_ENGINE_HEALTH = 1000000;
// units/sec of sudden velocity change before it starts to hurt — also the
// gate for whether a landing/crash deals damage at all.
// Higher: more impacts are free — normal jumps and small bumps never hurt,
//   only really hard falls/crashes do; every damaging hit also deals less
//   (the threshold is subtracted first).
// Lower: even ordinary landings and light bumps cost health; set too low,
//   physics noise from rolling over uneven ground chips health away.
const IMPACT_DAMAGE_THRESHOLD = 450;
// health lost per unit/sec beyond the threshold — how steeply damage grows
// once an impact is over it.
// Higher: impacts just above the threshold already hurt a lot; hard crashes
//   break the melon in one hit.
// Lower: damage grows slowly — even big crashes only nibble at health,
//   breaking needs many hard hits.
const IMPACT_DAMAGE_SCALE = 0.2;
// Landing flat on level ground hurts more than the same impact anywhere else
// (a slope lets the melon roll the fall off; a wall crash has its own
// rules): the damage above is multiplied by FLAT_LANDING_DAMAGE_MULTIPLIER
// when the floor under the melon is at least FLAT_LANDING_MIN_NORMAL_Z level
// and the impact came mostly from above (upward share of the impact at least
// FLAT_LANDING_MIN_VERTICAL_SHARE). The threshold itself is unchanged, so
// landings that were free stay free.
// Higher multiplier: big drops onto flat floors break the melon much sooner.
// Lower (1 = off): flat landings hurt the same as any other impact.
const FLAT_LANDING_DAMAGE_MULTIPLIER = 2; // was 1.5
// Floor normal z from which ground counts as flat (1 = perfectly level;
// 0.97 ≈ up to 14° of slope).
// Higher: only really level floors count, gentle ramps don't.
// Lower: moderate slopes count as flat too.
const FLAT_LANDING_MIN_NORMAL_Z = 0.97;
// How much of the impact must point straight up (the floor stopping a fall)
// for it to be a landing rather than a crash that happens to be on flat ground.
// Higher: only near-vertical drops count; fast landings with a lot of forward
// speed lost in the same tick don't.
// Lower: more mixed impacts count as flat landings.
const FLAT_LANDING_MIN_VERTICAL_SHARE = 0.7;

// Heal zones (HEAL_ZONE_*): health/heal/constants.js, re-exported by index.js.

// Heal zones: a trigger_multiple (filtered to prop_physics like the other
// triggers) with OnStartTouch -> RunScriptInput "heal_enter" and OnEndTouch
// -> RunScriptInput "heal_leave" heals the melon over time while it's
// inside. Health per second, used for a zone whose name doesn't set its own
// rate (see HEAL_ZONE_NAME_PATTERN / HEAL_ZONE_FULL_NAME).
// Higher: a quick stop in the zone refills the melon — heal zones become
//   pit stops you barely slow down for.
// Lower: healing takes a long stay; driving through only helps a little.
const HEAL_ZONE_RATE = 10;
// Optional per-zone rate: a heal trigger named "heal_zone_<rate>" (e.g.
// "heal_zone_25") heals <rate> health per second instead of HEAL_ZONE_RATE.
// Any other name uses HEAL_ZONE_RATE. Overlapping zones don't stack — the
// fastest one counts.
const HEAL_ZONE_NAME_PATTERN = /^heal_zone_(\d+(?:\.\d+)?)$/;
// Full-heal zone: a heal trigger with exactly this name (same heal_enter /
// heal_leave wiring) refills the melon to MELON_MAX_HEALTH on the first tick
// inside and keeps it full while it stays there. Its rate is
// HEAL_ZONE_FULL_RATE, so it always beats any other zone it overlaps.
const HEAL_ZONE_FULL_NAME = "heal_zone_full";
// Not a tuning knob: "infinitely fast" — HealedHealth jumps straight to full.
const HEAL_ZONE_FULL_RATE = Infinity;
// point_template placed in Hammer holding the heal effect's
// info_particle_system: a fresh copy is played at the melon, riding along
// on it, every time it enters a heal zone (any kind). Must match the name
// in Hammer; test/map/map-templates.test.mjs checks it's there.
const HEAL_PARTICLE_TEMPLATE_NAME = "particle_health_template";
// Seconds a spawned heal effect is kept before it's removed. Removing the
// info_particle_system ends its particles, so this is an upper bound.
// Higher: the effect is never cut short, but copies pile up while melons
//   keep driving in and out of heal zones.
// Lower: cleaned up sooner; below the .vpcf's own duration it's cut off
//   mid-play.
const HEAL_PARTICLE_LIFETIME = 2;

// Wall bounce: contact rules, speed-for-health trade, ratings, bounce HUD and the PERFECT spark.

// Wall bounce: an impact against a wall (any world/brush surface whose
// normal is mostly horizontal — see WALL_NORMAL_MAX_Z) reflects the melon's
// pre-impact velocity off that wall instead of letting vphysics just stop
// it, and can come out *faster* than it went in — trading health for speed.
// How much faster is skill-based: the speed multiplier is fixed per rating
// (BOUNCE_RATINGS[].speedMultiplier), and the rating comes from how close
// the hit was to WALL_BOUNCE_OPTIMAL_ANGLE (measured from the wall's normal,
// 0 = head-on, 90 = grazing) — closeness falls off linearly to 0 at
// WALL_BOUNCE_ANGLE_FALLOFF degrees away from it. A jump timed within
// WALL_BOUNCE_PERFECT_JUMP_WINDOW of the hit (before or after) multiplies the
// result once more — fully for the exact same tick, fading out towards the
// window's edges. Floors/landings never bounce — they keep using the
// plain IMPACT_DAMAGE_* rules (health.js).
// Map-wide switch for testing without it: off, no wall ever bounces — a
// wall hit is a plain crash (IMPACT_DAMAGE_* rules, physics stops the melon).
const WALL_BOUNCE_ENABLED = false;
const WALL_BOUNCE_MIN_IMPACT = 200; // units/sec of sudden velocity change before a wall hit counts as a bounce at all
const WALL_NORMAL_MAX_Z = 0.5; // |normal.z| above this is a floor/ceiling/steep ramp, not a wall
const WALL_BOUNCE_TRACE_DISTANCE = 160; // ray length from last tick's position along the incoming direction — must reach the wall even at grazing angles (grows with 1/cos(angle))
// A wall the traces find only counts if the melon is actually touching it
// (see IsWallContact in movement/wall-bounce/logic.js) — the trace reaches far ahead,
// so in a small room it finds *some* wall on almost every hard landing or
// bump, which used to bounce the melon off a wall it never touched.
const WALL_CONTACT_DISTANCE = 56; // max units from the melon's center to the wall plane — melon radius plus margin for the tick physics already pushed it back
const WALL_CONTACT_MIN_STOP = 0.5; // fraction of the into-the-wall speed the impact must have taken away — a landing or friction leaves it almost untouched, a real wall stops it
const WALL_BOUNCE_TRACE_RADIUS = 8; // backup sphere sweep from the current position, for posts/edges the ray slips past
const WALL_BOUNCE_SPHERE_TRACE_DISTANCE = 48;
const WALL_BOUNCE_OPTIMAL_ANGLE = 45; // degrees from the wall normal where the bounce is strongest
const WALL_BOUNCE_ANGLE_FALLOFF = 45; // degrees away from optimal at which the bonus has faded out completely
const WALL_BOUNCE_PERFECT_JUMP_WINDOW = 0.12; // seconds, before or after the hit
const WALL_BOUNCE_PERFECT_JUMP_MULTIPLIER = 1.3; // extra multiplier on top for a perfectly timed jump (scaled down the further off it is)
// The timing press is the jump button, but separate from the normal jump:
// it counts even in the air or while the jump is on cooldown (it gives no
// upward push, only timing credit). Pressing again within this many seconds
// of the previous press that did nothing (no ground or wall jump) is treated
// as mashing and locks timing credit for that long — see WallTimingPress.
const WALL_TIMING_SPAM_LOCKOUT = 0.4; // seconds
// Every bounce also lifts the melon: its vertical speed is set to at least
// this much upward (a falling melon's fall is cancelled, one already rising
// faster keeps its own speed — not added on top, so chained bounces don't
// stack upward speed). Same for every rating except PERFECT (see below).
// Higher: bounces send it up in an arc; 0 = vertical left to physics (old).
// Stronger inside lift zones — see zones/lift/constants.js.
const WALL_BOUNCE_UP_SPEED = 220; // units/sec upward
// A bounce rated PERFECT (BOUNCE_RATINGS[0]) kicks this much harder upward —
// applies to WALL_BOUNCE_UP_SPEED and to a lift zone's kick alike.
const PERFECT_BOUNCE_UP_MULTIPLIER = 1.2; // ×1.2 = 20 % more upward kick
const WALL_BOUNCE_COOLDOWN = 0.2; // seconds — stops one wall contact from bouncing (and damaging) on consecutive ticks
// Wall hits get their own damage rules, separate from landings: a base part
// from the impact itself (same shape as IMPACT_DAMAGE_*), plus a cost for
// every unit/sec of speed the bounce *gained* — that second part is the
// actual "speed for health" trade. That total is then reduced by how close
// to the optimal angle it hit (the angle factor, 0..1) — jump timing only
// affects speed, not damage. Anything rated PERFECT (BOUNCE_RATINGS[0]) costs
// no health at all; one with no angle bonus pays full price. Charged once the jump window has
// closed (a late jump can still add speed), not on impact itself.
const WALL_IMPACT_DAMAGE_THRESHOLD = 200; // units/sec — same as WALL_BOUNCE_MIN_IMPACT, so any bounce that isn't PERFECT costs health from its first unit/sec
const WALL_IMPACT_DAMAGE_SCALE = 0.3; // health lost per unit/sec beyond the threshold (before the angle reduction)
const WALL_BOUNCE_DAMAGE_PER_SPEED = 0.05; // health lost per unit/sec gained by a bounce
// A bounce may lift the melon above MAX_SPEED — deliberately with no upper
// limit, chained bounces stack. The raised cap then decays back towards
// MAX_SPEED at this rate (and never sits above the melon's actual speed, so
// braking and re-accelerating can't reclaim a boost already lost).
const BOOST_DECAY = 150; // units/sec^2
// The speedometer flashes (PerfectBounce class) for this long after a bounce
// with at least this angle factor — i.e. one that cost little or no health.
const PERFECT_BOUNCE_FLASH_SECONDS = 0.4;
const PERFECT_BOUNCE_ANGLE_FACTOR = 0.8;
// point_template placed in Hammer holding the spark's info_particle_system:
// spawned at the melon on every wall bounce the HUD rates PERFECT
// (BOUNCE_RATINGS[0]) — two fresh copies per hit, one left at the wall and
// one parented to the melon so its player sees it too, and perfect hits by
// several karts at once each get their own. Must match the name in Hammer.
const PERFECT_SPARK_TEMPLATE_NAME = "perfect_hit_particle_template";
// Seconds a spawned spark is kept before it's removed. Removing the
// info_particle_system ends its particles, so this is an upper bound.
// Higher: the effect is never cut short, but more entities pile up when
//   perfect hits come in fast succession.
// Lower: cleaned up sooner; below the .vpcf's own duration the spark is
//   cut off mid-play.
const PERFECT_SPARK_LIFETIME = 2;
// Bounce feedback panel (bounce_panel in speedometer.xml, see
// UpdateBounceHud): shown for this long after each wall bounce.
const BOUNCE_HUD_SECONDS = 1.5;
// Angle scale: 0°..90° split into this many equal segments
// ("bounce_angle_seg_0".."_{N-1}"), 10° each — the one containing 45° is
// styled as the target in speedometer.css, the one actually hit gets "Hit".
const BOUNCE_ANGLE_SEGMENTS = 9;
// Jump-timing bar ("bounce_jump_seg_0".."_{N-1}"), filled by how well the
// jump was timed (1 = same tick as the hit).
const BOUNCE_JUMP_SEGMENTS = 5;
// Rating word by how close to WALL_BOUNCE_OPTIMAL_ANGLE the hit was
// (angleFactor, 1 = exact). First match wins — keep sorted high to low,
// last entry is the catch-all. speedMultiplier is what a bounce with that
// rating does to the melon's speed (before jump timing). cssClass colors the panel; color is the same
// accent for the in-world prediction line (see fx/prediction/prediction.js) — keep the two
// in sync with speedometer.css's .Rating* rules.
// PERFECT counts within this many degrees either side of
// WALL_BOUNCE_OPTIMAL_ANGLE (was 4.5°, then 6.5°).
const PERFECT_BOUNCE_TOLERANCE = 8.5; // degrees
const BOUNCE_RATINGS = [
    { minAngleFactor: 1 - PERFECT_BOUNCE_TOLERANCE / WALL_BOUNCE_ANGLE_FALLOFF, label: "PERFECT", speedMultiplier: 1.35, cssClass: "RatingPerfect", color: { r: 255, g: 224, b: 102, a: 255 } },
    { minAngleFactor: 0.7, label: "GOOD", speedMultiplier: 1.1, cssClass: "RatingGood", color: { r: 102, g: 221, b: 102, a: 255 } },
    { minAngleFactor: 0.4, label: "BAD", speedMultiplier: 0.5, cssClass: "RatingBad", color: { r: 102, g: 170, b: 255, a: 255 } },
    { minAngleFactor: 0, label: "MISS", speedMultiplier: 0.3, cssClass: "RatingMiss", color: { r: 255, g: 102, b: 102, a: 255 } },
];

// Boost trail: a glowing band (particles/melon_racer/boost_trail.vpcf, with
// juice droplets as a second particle system in the same template) behind a melon while a wall-bounce boost has
// it faster than MAX_SPEED. Started and stopped by boost-trail.js.

// point_template placed in Hammer holding the trail's info_particle_system
// (effect particles/melon_racer/boost_trail.vpcf). A fresh copy is spawned
// on the melon, parented so it rides along, when the boost starts, and
// stopped when it's over. Must match the name in Hammer. Without it there's
// simply no trail.
const BOOST_TRAIL_TEMPLATE_NAME = "particle_boost_trail_template";
// The trail starts once the melon is this many units/sec above MAX_SPEED...
// Higher: only big boosts (PERFECT, chained bounces) leave a trail.
// Lower: even a small GOOD bounce shows it; at ~0 it flickers on every
//   tiny overshoot of MAX_SPEED.
const BOOST_TRAIL_START_MARGIN = 30;
// ...and stops once it's back below MAX_SPEED + this. Lower than the start
// margin so a speed hovering around the threshold doesn't toggle it every
// tick.
const BOOST_TRAIL_STOP_MARGIN = 5;
// Seconds a stopped trail's entities are kept, so the particles already out
// fade out instead of vanishing. Must cover the .vpcf's longest particle
// lifetime (0.75 s for the juice droplets).
const BOOST_TRAIL_FADE_SECONDS = 1;

// Attack boost: holding the attack button (mouse1) pushes the melon faster
// than MAX_SPEED along the look direction — paid for with health, drained
// every tick while the boost is on. High risk, high reward: there's no
// floor — hold it too long and the health runs out and the melon breaks. Rule: ../logic/attack-boost.js, applied
// in ../physics/drive.js.

// Extra acceleration along the look direction while attack is held, on top
// of whatever W/S/A/D do (units/sec^2).
// Higher: the boost kicks in almost instantly.
// Lower: it takes a while to build up the extra speed.
const ATTACK_BOOST_ACCEL = 450;
// Speed cap while boosting (units/sec). Letting go, the cap decays back to
// MAX_SPEED at BOOST_DECAY like a wall-bounce boost (so the boost trail shows
// too while above MAX_SPEED + BOOST_TRAIL_START_MARGIN).
// Higher: boosting gets much faster than normal driving.
// Lower (= MAX_SPEED): the boost only accelerates quicker, no higher top speed.
const ATTACK_BOOST_MAX_SPEED = 850;
// Health lost per second while boosting (MELON_MAX_HEALTH = 70, so 20 = a
// full melon breaks after ~3.5 s of boosting).
// Higher: the boost is expensive, short bursts only.
// Lower: nearly free, can be held for long stretches.
const ATTACK_BOOST_HEALTH_PER_SECOND = 20; // was 10
// The engine itself reacts to attack too — a knife swing shoves the melon
// ~140 u/s, even with the pawn's weapons taken away every tick. While attack
// is held and for this long after letting go, physics may not add
// horizontal speed on top of what the script commanded last tick, so speed
// only ever comes from driving and the paid boost.
// Higher: covers pushes that arrive later after the press; also blocks a
//   downhill roll's speed-up for longer after letting go.
// Lower (0): only while held — a push landing just after release gets through.
const ATTACK_PUSH_GUARD_SECONDS = 0.3;

// HUD entity and the speed panel (km/h, health bar, jump dots) in speedometer.xml.

// Name of the custom_hud_layout entity (place one in Hammer pointing at
// panorama/layout/custom_game/speedometer.vxml) that shows the speedometer.
const SPEED_HUD_ENTITY_NAME = "speed_hud";
// Hammer units/sec -> km/h (1 unit = 1 inch: units/sec * 0.0254 * 3.6).
const UNITS_TO_KMH = 0.0254 * 3.6;

// Wall-jump charges as dots right of the speed panel, one per
// WALL_JUMP_CHARGES (stacked bottom up, "jump_dot_<i>" in speedometer.xml):
// an outline, filled white only once that charge is ready. JumpDotFills
// measures a refilling one in JUMP_DOT_FILL_STEPS steps; only the full step shows.
const JUMP_DOT_FILL_STEPS = 8;

// Melon health bar, in the speed panel under the km/h: filled left to right
// in HEALTH_BAR_SEGMENTS steps up to kart.health / MELON_MAX_HEALTH — pieces
// "health_seg_0" .. "health_seg_{N-1}" in speedometer.xml (add/remove
// them there when changing the count). HEALTH_LOW/CRITICAL_FRACTION only feed HealthBarState's low/critical
// flags — the bar itself stays white (no tint).
const HEALTH_BAR_SEGMENTS = 30;
const HEALTH_LOW_FRACTION = 0.6;
const HEALTH_CRITICAL_FRACTION = 0.3;
// The health bar and jump dots send a class only when it changes — plus
// their whole state again this often (seconds): a class sent before the
// player's HUD had loaded (e.g. full jump charges right at spawn) was lost
// and, never changing, never sent again.
const HUD_RESEND_SECONDS = 1;

// Checkpoint strip at the top of the screen (start flag -> numbered
// checkpoints -> finish flag) — see CHECKPOINT_HUD_SLOTS panel ids
// ("cp_slot_0" .. "cp_slot_{N-1}", each with a "cp_link_<i>" line before
// it) in speedometer.xml. A track with more checkpoints shows a window of
// this many that moves along with the kart (see hud/checkpoint-strip-logic.js).
const CHECKPOINT_HUD_SLOTS = 12;

// Momentum: reaching the top speed again and again in quick succession
// raises that melon's own top speed, step by step — as long as it never
// drops below MOMENTUM_MIN_SPEED in between (that ends the "run" and resets
// it to MAX_SPEED). The attack boost (and any other speed-cap boost, e.g. a
// wall bounce's) neither counts as reaching the top speed nor breaks a run.
// Rule: ../logic/momentum.js, applied in ../physics/drive.js.

// Top speed gained per step, as a fraction of MAX_SPEED (0.02 = +2 %).
// Higher: a few quick hits make the melon much faster.
// Lower: momentum is barely noticeable.
const MOMENTUM_STEP = 0.02;
// Most steps a run can stack (10 × 2 % = up to MAX_SPEED × 1.2).
// Higher / Infinity: long clean runs keep getting faster without limit.
const MOMENTUM_MAX_STEPS = 10;
// Reaching the top speed counts as a step only if the previous time it was
// reached is at most this many seconds ago — the first time (or after a
// longer gap) only starts the chain.
// Higher: easier, even slow re-accelerations count.
// Lower: only quick dip-and-recover driving builds momentum.
const MOMENTUM_HIT_WINDOW = 2.5; // seconds
// Having reached the top speed, the melon has to fall this fraction below it
// before reaching it again counts as a new time (just holding top speed
// doesn't stack).
// Higher: a real slowdown (curve, bump) is needed between two hits.
// Lower: tiny wobbles already count — easy to farm by tapping W.
const MOMENTUM_REARM_DIP = 0.05;
// Below this horizontal speed the run is over: back to plain MAX_SPEED.
const MOMENTUM_MIN_SPEED_KMH = 30;
const MOMENTUM_MIN_SPEED = MOMENTUM_MIN_SPEED_KMH / UNITS_TO_KMH; // units/sec (~328)

// Lift zones: triggers where wall bounces and wall jumps are tuned for
// climbing a shaft or a high wall by bouncing between its walls. What
// changes inside one is gathered in WallRules (zones/lift/logic.js); the camera
// zoom there is LIFT_CAMERA_* in camera/.

// A trigger_multiple (filtered to prop_physics like the other triggers) with
// OnStartTouch -> RunScriptInput "lift_enter" and OnEndTouch -> RunScriptInput
// "lift_leave". While the melon is inside, a wall bounce kicks it up by this
// much instead of WALL_BOUNCE_UP_SPEED. Per zone, the name can set it (see
// LIFT_ZONE_NAME_PATTERN). Overlapping zones: the strongest counts.
// Gravity is 800 u/s², so a kick of v climbs about v² / 1600 units:
// 220 -> ~30, 450 -> ~125, 600 -> ~225 per bounce.
const LIFT_ZONE_UP_SPEED = 450; // units/sec upward
// Optional per-zone kick: a lift trigger named "lift_zone_<speed>" (e.g.
// "lift_zone_600") kicks <speed> units/sec up instead of LIFT_ZONE_UP_SPEED.
const LIFT_ZONE_NAME_PATTERN = /^lift_zone_(\d+(?:\.\d+)?)$/;
// In a lift zone a bounce always leaves the wall with at least this much
// horizontal speed, whatever its rating. Shafts are climbed by bouncing
// almost head-on — a MISS (x0.3) — so the melon used to arrive at the
// opposite wall below WALL_BOUNCE_MIN_IMPACT and the chain died there. The
// speed added this way is free (not counted as speed gained for damage).
// Higher: easier to reach the far wall of wide shafts; lower: more skill.
const LIFT_ZONE_MIN_BOUNCE_SPEED = 450; // units/sec
// Wall jumps in a lift zone cost no charge, are always full strength and
// may follow a wall bounce at once (outside one, a press in the bounce's
// jump-timing window is only timing). A narrow shaft has the melon at the
// opposite wall sooner than WALL_JUMP_COOLDOWN, so there the cooldown is only
// this (the next wall jump still needs the *other* wall, so one wall can't be
// climbed alone) ...
const LIFT_ZONE_WALL_JUMP_COOLDOWN = 0.1; // seconds
// ... and a jump pressed up to this long *before* touching the next wall is
// remembered and fires the wall jump the moment the melon touches it —
// pressing a little early used to be lost (only presses after the contact
// counted, within WALL_JUMP_WINDOW) ...
const LIFT_ZONE_JUMP_BUFFER = 0.2; // seconds
// ... and a wall contact stays jumpable this long, instead of the tick or
// two of WALL_JUMP_WINDOW outside: shafts stay easy to climb.
const LIFT_ZONE_WALL_JUMP_WINDOW = 0.2; // seconds

// Wall-bounce prediction line (see fx/prediction/prediction.js).

// Wall-bounce prediction line, drawn in front of the melon (see
// fx/prediction/prediction.js): a dotted line along its current direction of travel up to
// the next wall, then on along the direction it would bounce off in —
// colored by the rating (BOUNCE_RATINGS) that wall hit would get at the
// current angle, so the player can steer until it turns PERFECT before
// reaching the wall. Dots are entities spawned from a point_template named
// PREDICTION_DOT_TEMPLATE_NAME (one small, non-solid prop_dynamic inside it)
// — Instance.DebugLine only works in dev environments, so real players
// would never see a debug-drawn line. Without that template in the map it
// falls back to DebugLine anyway, for testing in tools mode.
// Note: the dots are ordinary networked entities, so every player sees every
// kart's prediction line, not just their own.
// Master switch for the whole map. Each player also turns their own line
// on in the user menu ("GUIDE LINE") — off by default.
const PREDICTION_ENABLED = true;
// "debug": Instance.DebugLine — a clean continuous line, but only visible in
//          dev environments (tools mode), never to real players.
// "dots":  entities from PREDICTION_DOT_TEMPLATE_NAME — visible to everyone.
const PREDICTION_RENDER_MODE = "debug";
const PREDICTION_DOT_TEMPLATE_NAME = "prediction_dot_template";
const PREDICTION_LENGTH = 700; // units ahead to look for the next wall
const PREDICTION_REFLECT_LENGTH = 250; // units the bounced-off part of the line continues
const PREDICTION_DOTS_IN = 12; // dots from the melon to the wall
const PREDICTION_DOTS_OUT = 5; // dots along the bounce direction
const PREDICTION_START_OFFSET = 36; // first dot this far ahead of the melon's center, so it isn't hidden inside the melon
const PREDICTION_MIN_SPEED = 80; // units/sec — below this there's no meaningful direction, line hidden
const PREDICTION_NEUTRAL_COLOR = { r: 255, g: 255, b: 255, a: 160 }; // no wall in range

// Breaking: what happens at the crash site and the respawn delay.

// When a melon breaks it doesn't respawn instantly — it shreds apart at the
// crash site (hidden immediately, with the break particle standing in for
// the melon itself) for BREAK_RESPAWN_DELAY seconds before reappearing at the
// last checkpoint. Gives the player a beat to register that it broke instead
// of it just snapping to the checkpoint. Seconds.
// Higher: a break costs more race time and the player watches the burst
//   longer — harsher penalty, can feel like waiting.
// Lower: quicker back on track, a milder penalty; too low and the burst and
//   camera pull-back (BREAK_CAMERA_ZOOM_SECONDS) are cut off before they're
//   seen — it just snaps to the checkpoint.
const BREAK_RESPAWN_DELAY = 3;
// While broken, the chase camera pulls back from the crash site so the
// player actually sees the melon burst (see BreakCameraOffset in
// health/breaking/logic.js): it eases out by this much extra distance/height
// over BREAK_CAMERA_ZOOM_SECONDS, holds there, and snaps back to the
// player's normal offset when the melon respawns BREAK_RESPAWN_DELAY later.
// Seconds the pull-back takes.
// Higher: slower, smoother zoom-out; at or above BREAK_RESPAWN_DELAY it never
//   reaches its full distance before the respawn.
// Lower: a faster, more abrupt jerk back; 0 = jumps straight out.
const BREAK_CAMERA_ZOOM_SECONDS = 0.8;
// Units the camera ends up further back than the player's normal distance.
// Higher: wider view of the burst and the flying pieces, the melon looks small.
// Lower: stays close — the burst fills the screen, pieces fly out of view;
//   0 = no pull-back (only BREAK_CAMERA_EXTRA_HEIGHT).
const BREAK_CAMERA_EXTRA_DISTANCE = 130;
// Units the camera ends up higher than the player's normal height.
// Higher: looks down onto the crash site from above, pieces on the ground
//   are easier to see; in low rooms the camera may end up in the ceiling.
// Lower: flatter view from the side; 0 = no rise (only
//   BREAK_CAMERA_EXTRA_DISTANCE).
const BREAK_CAMERA_EXTRA_HEIGHT = 50;
// How long a break's spawned effect entities (both templates below) are
// kept before being removed — long, so the chunks stay lying at the crash
// site. Removing the info_particle_system ends its particles, so this is an
// upper bound: the .vpcf's own particle lifetime can still end them sooner.
// Seconds.
// Higher: pieces stay lying around longer as traces of past crashes — more
//   entities alive at once (still capped by BREAK_EFFECT_MAX_ACTIVE).
// Lower: the crash site is cleaned up sooner; below the particle's own
//   lifetime it also cuts the burst itself short.
const BREAK_EFFECT_LIFETIME = 180;
// Cap on how many breaks' effects exist at once, so a long session doesn't
// pile up entities — the oldest break's effects go first.
// Higher: more crash sites stay visible with many players/breaks — more
//   entities and physics pieces, costs performance and entity slots.
// Lower: fewer entities; with many breaks old pieces vanish long before
//   BREAK_EFFECT_LIFETIME, possibly while someone's still looking at them.
const BREAK_EFFECT_MAX_ACTIVE = 24;
// Fallback look while broken when no break particle actually spawned (see
// SpawnBreakParticles/BreakMelon) — a dark, dead-looking husk visibly marking
// the crash site instead of the melon just vanishing for BREAK_RESPAWN_DELAY
// seconds with nothing to look at. Only used when the break templates are
// missing or spawn nothing.
// Brighter (r/g/b up): the husk looks less "dead", closer to a normal melon.
// Darker (r/g/b down): more clearly broken; a < 255 makes it see-through,
//   0 hides it completely (the melon just vanishes).
const BREAK_TINT_FALLBACK = { r: 40, g: 40, b: 40, a: 255 };
// Name of a point_template placed in Hammer holding the break effect (e.g. an
// info_particle_system with "Start Active" set so it plays as soon as it's
// spawned, no input needed) — same ForceSpawn-from-a-template convention as
// MELON_TEMPLATE_NAME. Not a tuning value: must match the entity's name in
// Hammer (renaming means renaming it there too, and in docs/mapping-api/).
const BREAK_PARTICLE_TEMPLATE_NAME = "melon_break_template";
// Second, separate break effect layered on top of the one above — e.g. flying
// melon chunks, as opposed to the main burst. Same point_template convention,
// same "must match Hammer" rule.
const BREAK_CHUNKS_PARTICLE_TEMPLATE_NAME = "melon_break_chunks_template";
// Any prop_physics the two break templates above spawn (e.g. the melon
// model's own break pieces, models/cs_italy/italy_food_melon/
// italy_food_melon/piece.vmdl .. piece8.vmdl, added to the chunks template)
// is treated as a break piece: flung outward from the crash site, tinted in
// the melon's color, and left lying there for BREAK_EFFECT_LIFETIME. The
// chunks particle alone is only sprite flecks that fade within moments.
// Units/sec each piece flies outward (along the ground) from the crash site.
// Higher: a more violent burst, pieces scatter wide — they can end up far
//   off, across the track (in karts' way) or out of view.
// Lower: pieces drop in a tight heap where the melon broke; 0 = straight up
//   only (BREAK_PIECE_UP_SPEED).
const BREAK_PIECE_SPEED = 220;
// Units/sec extra upward pop per piece.
// Higher: pieces fly high and stay in the air longer before landing; too
//   high and they hit ceilings indoors.
// Lower: pieces skid along the ground instead of flying; 0 = no pop.
const BREAK_PIECE_UP_SPEED = 180;
// Max degrees/sec of random tumble per axis.
// Higher: pieces spin wildly through the air, a more chaotic burst.
// Lower: pieces fly calmer, keeping their orientation; 0 = no spin at all.
const BREAK_PIECE_SPIN = 600;

// Tracks, checkpoints and the hub -> race -> next-track flow.

// The map has multiple separate tracks, so a checkpoint trigger's name
// says both which track it belongs to and its position along that track:
// "checkpoint_<trackId>_<index>", e.g. "checkpoint_2_5" is track 2's 5th
// checkpoint. The start_<trackId>/finish_<trackId> inputs are registered up
// front for every track (see race/checkpoints/checkpoints.js) — raise these
// if a track ends up needing more checkpoints, or the map more tracks, than
// currently allowed for.
const MAX_TRACKS = 8;
const MAX_CHECKPOINTS_PER_TRACK = 32;

// Race flow: HUB (default/gather) -> COUNTDOWN (locked, pre-race) -> RACING
// -> BREAK (finished, waiting for the next heat) -> back to COUNTDOWN on the
// next track, or back to HUB after the last one. See GAMEPLAY.md's "Hub ->
// race -> next-track flow" for the full design.
const RacePhase = /** @type {const} */ ({
    HUB: "HUB",
    COUNTDOWN: "COUNTDOWN",
    RACING: "RACING",
    BREAK: "BREAK",
});

const HUB_TRIGGER_NAME = "hub_start_trigger";

const COUNTDOWN_SECONDS = 3;
const GO_DISPLAY_SECONDS = 1; // how long "GO!" stays on screen once the countdown ends
const BREAK_SECONDS = 10; // fixed by the original request
// Spacing between racers teleported onto the same start line side-by-side,
// so they don't spawn stacked on top of each other.
const RACE_SPAWN_LATERAL_SPACING = 120;

// Start trigger of a track: a trigger_multiple named "start_<trackId>",
// optionally "start_<trackId>_laps<lapsToWin>" (e.g. "start_1_laps3";
// without _laps it's DEFAULT_LAPS_TO_WIN). Its OnStartTouch fires
// RunScriptInput "start_<trackId>" (always without the _laps part), which
// puts a free-roaming melon on that track; its transform is where racers
// line up when a heat starts. The finish is the separate "finish_<trackId>"
// input — on the same trigger for a loop track, at the end of the track
// for a point-to-point one. See GetTrackConfig() in race/track-config.js.
// Instead of "start_<trackId>" the output may fire the generic "start_line",
// which reads the track from the firing trigger's own name — so a start
// gate prefab only needs its trigger's name set per track (a prefab
// variable), not its output too.
const START_TRIGGER_NAME_PATTERN = /^start_(\d+)(?:_laps(\d+))?$/;
const DEFAULT_LAPS_TO_WIN = 1;

// A point-to-point track's finish trigger may be named "finish_<trackId>"
// (e.g. "finish_2") and fire the generic "finish_line", which reads the
// track from that name — like start_line, for a finish gate prefab. A
// finish_line from a start_<trackId>[_laps<M>] trigger (a loop track's
// shared start/finish line) works too.
const FINISH_TRIGGER_NAME_PATTERN = /^finish_(\d+)$/;

// Spawn point of a track's start: an info_target named
// "start_spawn_<trackId>" (e.g. "start_spawn_1"). Racers line up there when
// a heat starts (on the floor under it, facing its yaw), and a melon that
// breaks before checkpoint 1 respawns there. Without one, the nearest
// info_target named just "start_spawn" within START_SPAWN_SHARED_MAX_DISTANCE
// of the start trigger is used (every copy of a start gate prefab carries
// one), and without that the start trigger's own transform.
const START_SPAWN_NAME_PATTERN = /^start_spawn_(\d+)$/;
/** @param {number} trackId */
function StartSpawnName(trackId) {
    return `start_spawn_${trackId}`;
}
const START_SPAWN_SHARED_NAME = "start_spawn";
const START_SPAWN_SHARED_MAX_DISTANCE = 1024;

// Checkpoint triggers are named "checkpoint_<trackId>_<index>" and all fire
// the one script input "checkpoint", which reads track and index from the
// firing trigger's name — GetTrackConfig() counts a track's checkpoints from
// these names too. (Not a parameter per checkpoint, named like its trigger:
// Hammer warns about a RunScriptInput parameter that matches an entity name.)
const CHECKPOINT_TRIGGER_NAME_PATTERN = /^checkpoint_(\d+)_(\d+)$/;

// Respawn point of a checkpoint: an info_target named
// "checkpoint_spawn_<trackId>_<index>" (e.g. "checkpoint_spawn_1_3"). A
// broken melon respawns there, facing the entity's yaw. Without one, the
// nearest info_target named just "checkpoint_spawn" within
// CHECKPOINT_SPAWN_SHARED_MAX_DISTANCE of the checkpoint trigger is used
// (every copy of a checkpoint gate prefab carries one, like start_spawn),
// and without that the checkpoint trigger's own transform.
const CHECKPOINT_SPAWN_NAME_PATTERN = /^checkpoint_spawn_(\d+)_(\d+)$/;
const CHECKPOINT_SPAWN_SHARED_NAME = "checkpoint_spawn";
const CHECKPOINT_SPAWN_SHARED_MAX_DISTANCE = 1024;
/** @param {number} trackId @param {number} index */
function CheckpointSpawnName(trackId, index) {
    return `checkpoint_spawn_${trackId}_${index}`;
}

// Time trial: every run over a track is timed (start line -> finish of the
// last lap), and each player's best time per track is saved to disk. See
// "Time trial" in GAMEPLAY.md.

// How long the finish time ("NEW BEST!" or not) stays on the HUD after a run.
const RUN_RESULT_SECONDS = 5;

// A free-roaming finish sends the melon straight back to the track's start
// spawn. On a loop the finish line is the start trigger, whose start_ input
// may fire right after finish_ for the same touch — by then the melon is
// already at the start spawn, and that stale touch must not start the next
// attempt's clock there. Start-line touches this soon after such a finish
// are ignored.
const FINISH_RESTART_START_GUARD = 0.25;

// Key of the best times inside the addon's save data (Instance.SetSaveData
// holds one string for the whole addon — a JSON object, so other systems can
// keep their own keys next to this one).
const SAVE_DATA_BEST_TIMES_KEY = "bestTimes";

// Teleporters and the lift applied to every trigger/destination teleport target.

// Generic teleporters, same name-carries-the-config convention: a
// trigger_multiple named "teleport_to_<destination>" (filtered to
// prop_physics) with OnStartTouch -> RunScriptInput "melon_teleport" sends
// the touching melon to the entity named <destination> (e.g. an
// info_target), facing that entity's yaw. One shared handler for every
// teleporter — adding one is a pure Hammer edit. A teleport only moves the
// melon; it never changes its checkpoint progress, and its respawn point
// only with "checkpoint_" (below).
// Optional mode between "teleport_" and "to_", per teleporter:
//   teleport_stop_to_<destination> — arrives standing still
//   teleport_keep_to_<destination> — keeps its speed
//   teleport_to_<destination>      — TELEPORT_KEEP_SPEED decides
// and, after the mode, an optional "checkpoint_": the destination also
// becomes the melon's respawn point (e.g. tutorial sections, so a break
// doesn't send it back to the start of the tutorial):
//   teleport_stop_checkpoint_to_<destination>, teleport_checkpoint_to_<destination>, …
const TELEPORT_TRIGGER_NAME_PATTERN = /^teleport_(?:(stop|keep)_)?(checkpoint_)?to_(.+)$/;
// Default for teleport_to_<destination> without a mode. true: keep the
// melon's horizontal speed, redirected along the destination's facing;
// false: arrive standing still.
const TELEPORT_KEEP_SPEED = true;

// Race-flow teleports (heat start, checkpoint respawns) target a trigger_multiple's
// raw GetAbsOrigin() — Hammer mappers commonly sink a trigger's brush a bit
// into the floor so a fast-moving physics prop reliably touches it instead
// of tunneling past a paper-thin volume. Teleporting the melon to that exact
// height would embed it in solid ground; VPhysics can't resolve that
// overlap upward and the melon tunnels down through the floor instead. Lift
// the target up by this much so the melon always drops onto the floor from
// just above it, same trick as SPAWN_UP_OFFSET (spawn.js).
const TELEPORT_UP_OFFSET = 40;

// The kart: spawning (melon template, spawn entities, intro logo, frozen pawn) and painting.

const MELON_TEMPLATE_NAME = "melon_template";

// How long the Melon Racer logo (intro_logo in speedometer.xml) shows after
// a player picks a team, before their melon spawns at the intro.
const INTRO_LOGO_SECONDS = 5;

// How far above the floor under a spawn entity (hub_spawn, intro_spawn) the
// melon's origin appears — straight above it, no sideways offset (see
// PositionAboveFloor in kart/spawn-points.js). Just enough to clear the floor:
// a long drop lands hard enough for the engine's own physics to destroy the
// melon on impact (it used to be 128 plus the template's offset, ~180 units,
// and the melon broke on every landing and respawned in a loop).
const SPAWN_UP_OFFSET = 40;
// The floor trace for that starts FLOOR_TRACE_UP above the spawn entity (in
// case it's sunk into the floor) and looks FLOOR_TRACE_DOWN below it (in case
// it's floating above the floor).
const FLOOR_TRACE_UP = 32;
const FLOOR_TRACE_DOWN = 512;

// Spawn entities — resolved in kart/spawn-points.js.
// hub_spawn (info_player_start, required): where melons go in the hub.
// hub_spawn_facing (info_target, optional): only its angle counts — which
// way a melon at hub_spawn faces; without it, hub_spawn's own angle.
// intro_spawn (info_player_start, optional): a player's very first melon
// (the tutorial), facing its own angle; without it, hub_spawn.
const HUB_SPAWN_NAME = "hub_spawn";
const HUB_SPAWN_FACING_NAME = "hub_spawn_facing";
const INTRO_SPAWN_NAME = "intro_spawn";

// The frozen pawn (CSMoveType.NOCLIP: non-solid, but WASD still flies it)
// stays where it spawned — see HoldPawn in kart/spawn.js. It's only put back
// once it has drifted further than this, not every tick.
const PAWN_DRIFT_TOLERANCE = 16;

// --- Painting: paint triggers and the user menu's color swatches. ---

// Paint triggers: place a trigger_multiple anywhere (hub is the intended
// use, but nothing restricts it there) named "paint_trigger_<r>_<g>_<b>"
// (e.g. "paint_trigger_255_0_0" for red), filtered to prop_physics like the
// other triggers. Its OnStartTouch calls RunScriptInput "melon_paint" on
// this point_script — the color itself is read back off the trigger's own
// name (regex below), not the script input parameter, so adding/changing a
// paint trigger's color is a pure Hammer edit, same convention as
// start_<trackId> in GetTrackConfig().
const PAINT_TRIGGER_NAME_PATTERN = /^paint_trigger_(\d+)_(\d+)_(\d+)$/;

// Outline glow (the engine's Glow(), like CS2's teammate outline) around
// every whole melon, in its paint color — and in this green while it hasn't
// been painted yet — see kart/look.js.
const MELON_GLOW_ENABLED = true;
const MELON_GLOW_UNPAINTED_COLOR = { r: 60, g: 255, b: 60, a: 255 };

// Color swatches offered by the user menu's color picker (see the
// "usermenu_color_<key>" buttonId handling in hud/inputs.js's OnCustomHudClicked)
// — a fixed palette rather than a full picker since panorama's
// CustomHudLayout only supports basic panels/buttons, not input widgets
// like a color wheel.
/** @type {Record<string, { r: number, g: number, b: number, a: number }>} */
const COLOR_PRESETS = {
    red: { r: 220, g: 60, b: 60, a: 255 },
    orange: { r: 230, g: 140, b: 50, a: 255 },
    yellow: { r: 255, g: 224, b: 102, a: 255 },
    green: { r: 90, g: 200, b: 90, a: 255 },
    blue: { r: 90, g: 140, b: 230, a: 255 },
    purple: { r: 170, g: 100, b: 220, a: 255 },
    white: { r: 255, g: 255, b: 255, a: 255 },
    black: { r: 40, g: 40, b: 40, a: 255 },
};

// The normal chase camera's position.

// Offsets for CameraFollowConfig — behind and above the melon. cameraOffset
// is rotated by the player's eye angles: x is forward (negative = behind),
// z is up. The same for every player (see GetCameraOffsetFor in
// camera/follow/follow.js); lift and camera zones zoom out/in from there.
const FOLLOW_OFFSET = { x: 0, y: 0, z: 20 };
const CAMERA_LATERAL = 0;
// How far behind the melon the chase camera sits.
// Higher: more overview, the melon gets smaller on screen.
// Lower: closer, more speed feel; walls and slopes block the view sooner.
const CAMERA_DISTANCE = 50;
// How high above FOLLOW_OFFSET it sits.
// Higher: looks down on the melon — a better view ahead over hills.
// Lower: flat, close-to-the-ground view.
const CAMERA_HEIGHT = 0;

// Walls between the melon and the chase camera pull the camera in — done by
// the script (camera/wall-clip/wall-clip.js), not the engine, so it eases
// both ways: the engine's own clipping is instant and jerks the view at every
// pillar. A line trace from the melon to where the camera wants to be finds
// the wall; the camera's distance then eases towards it.
// The price: while it eases in, the camera is briefly behind or inside the
// wall — keep the pull-in rate high.
// Rates are per second (exponential: about 1 − e^(−rate·t) of the way after
// t seconds — at 15, 90 % in 0.15 s; at 4, 90 % in 0.6 s).
// Higher pull-in: hides walls sooner, but jerks again towards instant.
const CAMERA_WALL_PULL_IN_RATE = 15;
// Higher return: back to full distance sooner after the wall; lower: calmer.
const CAMERA_WALL_RETURN_RATE = 4;
// Units the camera stays in front of the wall it was pulled in by, so the
// view doesn't graze the wall's surface.
const CAMERA_WALL_MARGIN = 8;

// Lift zones (see zones/lift/constants.js): while the melon is inside one, the
// chase camera eases back and up by this much on top of the normal
// CAMERA_DISTANCE/CAMERA_HEIGHT, so the climb and the opposite wall stay in view;
// it eases back in after leaving. While zoomed out, the camera is NOT pulled
// in at walls — in a shaft the wall right behind the melon would undo the
// zoom — so it looks through the shaft walls instead.
// Higher: more overview, the melon gets smaller on screen.
const LIFT_CAMERA_EXTRA_DISTANCE = 220; // units further back
const LIFT_CAMERA_EXTRA_HEIGHT = 30; // units higher up
const LIFT_CAMERA_EASE_SECONDS = 0.6; // seconds to zoom fully out (or back in)

// The break camera (camera/break-zoom/break-zoom.js) uses the engine's own
// wall clipping, unlike the normal chase camera (camera/wall-clip/) — this is
// how fast it returns after a wall pulled it in
// (CameraFollowConfig.cameraOffsetReturnStrength; 1 = instantly, the
// engine's default; pulling in is always instant). How far it pulls back is
// BREAK_CAMERA_* in health/breaking/constants.js.
const CAMERA_OFFSET_RETURN_STRENGTH = 0.2;

// Camera zones (docs/mapping-api/11-camera-zones.md): a trigger_multiple (filtered to
// prop_physics) with OnStartTouch -> RunScriptInput "camera_enter" and
// OnEndTouch -> "camera_leave". While the melon is inside, the chase camera
// eases to the normal offset plus the zone's: further back (negative =
// closer) and higher up (negative = lower). The values come from the name:
//   camera_zone_<distance>_<height>          e.g. camera_zone_250_40 (out), camera_zone_-30_0 (in)
//   camera_zone_<distance>                   height 0
//   camera_zone_noclip_<distance>_<height>   same, but the camera isn't pulled in at walls
//   camera_zone_front_<ahead>_<height>       camera IN FRONT of the melon: <ahead> units ahead,
//                                            <height> units above the melon's center (default
//                                            CAMERA_ZONE_FRONT_HEIGHT) — e.g. camera_zone_front_40_0,
//                                            a low view just above the ground. Looks the way the
//                                            player looks (forward), so the melon itself is behind it.
//                                            Combines with noclip: camera_zone_noclip_front_40_0.
//   camera_zone_close[_<behind>[_<height>]]  CLOSE-UP for dramatic passages: camera right behind the
//                                            melon, <behind> units behind and <height> units above its
//                                            center (defaults CAMERA_CLOSEUP_DISTANCE/_HEIGHT), eased
//                                            in and out slowly (CAMERA_CLOSEUP_EASE_SECONDS) — e.g.
//                                            camera_zone_close, camera_zone_close_12_2.
//                                            Combines with noclip: camera_zone_noclip_close_15_3.
// Any other name uses CAMERA_ZONE_EXTRA_DISTANCE/_HEIGHT. Overlapping zones:
// the one entered last counts. Adds up with the lift zoom (camera/lift-zoom/).
const CAMERA_ZONE_NAME_PATTERN = /^camera_zone_(noclip_)?(front_)?(-?\d+(?:\.\d+)?)(?:_(-?\d+(?:\.\d+)?))?$/;
const CAMERA_CLOSEUP_NAME_PATTERN = /^camera_zone_(noclip_)?close(?:_(\d+(?:\.\d+)?)(?:_(-?\d+(?:\.\d+)?))?)?$/;
const CAMERA_ZONE_EXTRA_DISTANCE = 150; // units further back, for a zone without values in its name
const CAMERA_ZONE_EXTRA_HEIGHT = 0; // units higher up, same
const CAMERA_ZONE_EASE_SECONDS = 0.6; // seconds for a whole zoom in or out (also between two zones)
// Zooming in never brings the camera closer than this behind the melon
// (a negative distance past CAMERA_DISTANCE would put it in front) — only
// camera_zone_front_… zones may go past it.
const CAMERA_ZONE_MIN_DISTANCE = 0;
// A front zone without a height in its name: units above the melon's center
// (which sits ~7 units above the floor), so 0 = just above the ground.
// Negative: lower still — below about -5 the camera ends up in the floor.
const CAMERA_ZONE_FRONT_HEIGHT = 0;
// Close-up zones (camera_zone_close…) without values in their name: the
// camera's spot behind / above the melon's center (the normal chase camera is
// CAMERA_DISTANCE behind and FOLLOW_OFFSET.z + CAMERA_HEIGHT above it).
// Lower CAMERA_CLOSEUP_DISTANCE: closer still — below the melon's own size
//   (~10 units) the camera ends up inside it.
const CAMERA_CLOSEUP_DISTANCE = 16;
const CAMERA_CLOSEUP_HEIGHT = 4;
// Seconds a close-up zone takes to zoom in (and back out after leaving) —
// slower than CAMERA_ZONE_EASE_SECONDS, so it reads as a deliberate shot.
// Higher: a slow, dramatic push-in. Lower: snaps in.
const CAMERA_CLOSEUP_EASE_SECONDS = 1.2;

// Side-view zones (docs/mapping-api/11-camera-zones.md#side-view-zones): a
// trigger_multiple (filtered to prop_physics) with OnStartTouch ->
// RunScriptInput "side_view_enter" and OnEndTouch -> "side_view_leave". While
// the melon is inside, it's played like a 2D jump & run: the camera stops
// following the mouse and looks at the melon from one side, A/D drive
// left/right on screen, and the melon stays on the plane it entered on (no
// movement towards or away from the camera). The camera part is in
// camera/side-view/. The values come from the name:
//   side_view_<yaw>                       camera looks along <yaw> (Hammer yaw: 0 = +x/east,
//                                         90 = +y/north) — screen right is then <yaw> - 90,
//                                         e.g. side_view_90: looks north, D drives east
//   side_view_<yaw>_<distance>            ... from <distance> units away
//   side_view_<yaw>_<distance>_<height>   ... and <height> units above the melon's center,
//                                         looking down at it (negative: from below)
// Any other name: SIDE_VIEW_DEFAULT_YAW, SIDE_VIEW_DISTANCE, SIDE_VIEW_HEIGHT.
// Overlapping zones: the one entered last counts.
const SIDE_VIEW_NAME_PATTERN = /^side_view_(-?\d+(?:\.\d+)?)(?:_(\d+(?:\.\d+)?)(?:_(-?\d+(?:\.\d+)?))?)?$/;
const SIDE_VIEW_DEFAULT_YAW = 90; // degrees, for a zone without values in its name
// How far from the melon the camera sits, without a distance in the name.
// Higher: more of the level in view, the melon gets smaller on screen.
const SIDE_VIEW_DISTANCE = 300; // units
// How high above the melon's center it sits, without a height in the name —
// it always looks at the melon, so higher = looking down at it more.
const SIDE_VIEW_HEIGHT = 40; // units
// Keeping the melon on its plane: whatever pushes it towards or away from the
// camera (a slanted wall, a bump) is cancelled every tick, and a melon that
// has drifted off the plane anyway is pulled back at this rate (1/s: the
// drift is gone to ~1/e after 1/SIDE_VIEW_PLANE_PULL seconds) ...
const SIDE_VIEW_PLANE_PULL = 6;
// ... but never faster than this.
const SIDE_VIEW_PLANE_MAX_SPEED = 200; // units/sec
// Wall jumps in a side-view zone aren't rated (no angle bonus, see
// zones/lift/logic.js WallRules) but go a bit higher and further than
// outside one (WALL_JUMP_UP_SPEED / WALL_JUMP_PUSH_SPEED), for jump & run
// sections. Same rules otherwise (charges, cooldown, never slower upward).
const SIDE_VIEW_WALL_JUMP_UP_SPEED = 300; // units/sec upward
const SIDE_VIEW_WALL_JUMP_PUSH_SPEED = 220; // units/sec at least away from the wall

// Side-view camera (zones/side-view/constants.js): how it takes over from the
// chase camera and hands back.
// Seconds the camera takes to swing from behind the melon to the side (and
// back after leaving). Higher: a slower, smoother swing. 0: cuts.
const SIDE_VIEW_EASE_SECONDS = 0.8;

// Debug output timing.

// Think's debug heartbeat log interval — see core/think.js.
const HEARTBEAT_INTERVAL = 1; // seconds

// Developer aids (dev/).

// Free look (dev/free-look.js): the player's own pawn flies through the map
// (it's already NOCLIP, see FreezePawn) and the view switches to its eyes.
// Switching it on puts those eyes where the chase camera was: the pawn's
// origin goes FREE_LOOK_EYE_HEIGHT below that spot (CS2's standing eye height).
const FREE_LOOK_EYE_HEIGHT = 64;

// Movers: a func_movelinear whose name starts with "mover" goes back and
// forth on its own — the script starts it (Open) when the map loads and
// after every round restart, and turns it round at each end (OnFullyOpen ->
// Close, OnFullyClosed -> Open). No logic_auto or outputs in Hammer needed:
// direction, distance and speed are the func_movelinear's own keyvalues.
// Rule: world/mover/logic.js, applied by world/mover/mover.js.

// The class the script looks for movers in.
const MOVER_CLASS = "func_movelinear";
// "mover", "mover_<anything>" or "mover_wait<seconds>[_<anything>]"
// (e.g. "mover_wait1.5_left"): the wait is how long it stands still at each
// end before turning round; without one, MOVER_DEFAULT_WAIT.
const MOVER_NAME_PATTERN = /^mover(?:_wait(\d+(?:\.\d+)?))?(?:_.*)?$/;
// Seconds a mover without "_wait<seconds>" in its name stands at each end.
const MOVER_DEFAULT_WAIT = 0;

// All tunable numbers and static/Hammer-naming-convention data for
// melon_drive, one file per system they configure. Import from here, not
// from the single files. Actual mutable runtime state (kart registry, race
// phase, caches) lives with the module that owns it instead — see
// core/kart-registry.js, race/heat/race-flow.js, race/track-config.js.

// Pure rules for the lift-zone camera zoom — no cs_script import, so it's
// unit-testable in Node (see test/camera/lift-zoom.test.mjs). lift-zoom.js
// next to it and ../follow/follow.js apply it.

/**
 * How far the lift camera is zoomed out after `dt` more seconds, 0 (normal)
 * to 1 (fully out): moves linearly towards 1 inside a lift zone and towards
 * 0 outside, taking LIFT_CAMERA_EASE_SECONDS for the whole way.
 * @param {number} blend current value @param {boolean} inLiftZone @param {number} dt
 */
function LiftCameraBlend(blend, inLiftZone, dt) {
    const step = LIFT_CAMERA_EASE_SECONDS > 0 ? Math.max(0, dt) / LIFT_CAMERA_EASE_SECONDS : 1;
    return inLiftZone ? Math.min(1, blend + step) : Math.max(0, blend - step);
}

/**
 * The chase camera offset with the lift zoom applied: further back (x is
 * forward, negative = behind) and higher up, eased in and out (smoothstep)
 * so it doesn't start or stop with a jolt.
 * @param {{ x: number, y: number, z: number }} base the player's normal offset @param {number} blend see LiftCameraBlend
 */
function LiftCameraOffset(base, blend) {
    const t = Math.max(0, Math.min(1, blend));
    const eased = t * t * (3 - 2 * t);
    return {
        x: base.x - LIFT_CAMERA_EXTRA_DISTANCE * eased,
        y: base.y,
        z: base.z + LIFT_CAMERA_EXTRA_HEIGHT * eased,
    };
}

// Pure rules for the script's own camera wall clipping — no cs_script import,
// so it's unit-testable in Node (see test/camera/wall-clip.test.mjs).
// wall-clip.js next to it does the trace and applies the result.

/**
 * A camera offset (x forward, y left, z up — like
 * CameraFollowConfig.cameraOffset) turned into a world-space vector by the
 * player's eye angles (pitch positive = looking down, as in Source).
 * @param {{ x: number, y: number, z: number }} offset @param {{ pitch: number, yaw: number }} angles
 */
function RotateCameraOffset(offset, angles) {
    const p = (angles.pitch * Math.PI) / 180;
    const y = (angles.yaw * Math.PI) / 180;
    const forward = { x: Math.cos(p) * Math.cos(y), y: Math.cos(p) * Math.sin(y), z: -Math.sin(p) };
    const left = { x: -Math.sin(y), y: Math.cos(y), z: 0 };
    const up = { x: Math.sin(p) * Math.cos(y), y: Math.sin(p) * Math.sin(y), z: Math.cos(p) };
    return {
        x: forward.x * offset.x + left.x * offset.y + up.x * offset.z,
        y: forward.y * offset.x + left.y * offset.y + up.y * offset.z,
        z: forward.z * offset.x + left.z * offset.y + up.z * offset.z,
    };
}

/**
 * How much of the camera offset fits before a wall: 1 = the whole way (no
 * wall), down to 0 = right at the melon. The camera stops
 * CAMERA_WALL_MARGIN short of the wall.
 * @param {boolean} didHit @param {number} fraction the trace's hit fraction @param {number} length the offset's length
 */
function WallClipScale(didHit, fraction, length) {
    if (!didHit || length <= 0) {
        return 1;
    }
    return Math.max(0, Math.min(1, (fraction * length - CAMERA_WALL_MARGIN) / length));
}

/**
 * Eases the current scale towards `target` over `dt` seconds — fast when
 * pulling in (CAMERA_WALL_PULL_IN_RATE), slower when going back out
 * (CAMERA_WALL_RETURN_RATE). No current value yet (fresh spawn/respawn):
 * straight to the target, so the camera doesn't glide in from somewhere.
 * @param {number | undefined} current @param {number} target @param {number} dt
 */
function StepWallClipScale(current, target, dt) {
    if (current === undefined) {
        return target;
    }
    const rate = target < current ? CAMERA_WALL_PULL_IN_RATE : CAMERA_WALL_RETURN_RATE;
    const next = target + (current - target) * Math.exp(-rate * Math.max(0, dt));
    return Math.abs(next - target) < 0.001 ? target : next;
}

// The chase camera's wall pull-in, done by the script instead of the engine
// (CAMERA_WALL_* in constants.js): the engine's clipCameraOffset pulls in
// instantly, this eases both ways. The math is in logic.js.

/**
 * `offset` pulled in towards the melon as far as a wall in between needs it,
 * eased over `dt` (kart.cameraWallScale keeps the current pull-in). The
 * trace runs from the camera's pivot (the melon + FOLLOW_OFFSET) to where
 * the camera would be, skipping the melon itself and players.
 * @param {import("../../core/kart-registry.js").Kart} kart
 * @param {{ x: number, y: number, z: number }} offset @param {number} dt
 */
function WallClippedOffset(kart, offset, dt) {
    const origin = kart.melon.GetAbsOrigin();
    const pivot = { x: origin.x + FOLLOW_OFFSET.x, y: origin.y + FOLLOW_OFFSET.y, z: origin.z + FOLLOW_OFFSET.z };
    const toCamera = RotateCameraOffset(offset, kart.pawn.GetEyeAngles());
    const length = Math.hypot(toCamera.x, toCamera.y, toCamera.z);
    let target = 1;
    if (length > 0) {
        const trace = TraceLine({
            start: pivot,
            end: { x: pivot.x + toCamera.x, y: pivot.y + toCamera.y, z: pivot.z + toCamera.z },
            ignoreEntity: kart.melon,
            ignorePlayers: true,
        });
        target = trace.startedInSolid ? 1 : WallClipScale(trace.didHit, trace.fraction, length);
    }
    kart.cameraWallScale = StepWallClipScale(kart.cameraWallScale, target, dt);
    const scale = kart.cameraWallScale;
    return { x: offset.x * scale, y: offset.y * scale, z: offset.z * scale };
}

// Pure rules for camera zones — no cs_script import, so it's unit-testable in
// Node (see test/zones/camera-zone.test.mjs). camera/zone-zoom/ applies the
// resulting offset.

/**
 * @typedef {{ distance: number, height: number, clip: boolean, front: boolean, ease?: number }} CameraZone
 * what a zone adds to the chase camera; `front` = no CAMERA_ZONE_MIN_DISTANCE
 * stop (front and close-up zones); `ease` = its own seconds to zoom in and
 * back out (close-up zones), else CAMERA_ZONE_EASE_SECONDS
 */

/**
 * @typedef {{
 *   from: CameraZone, to: CameraZone, // easing from -> to
 *   t: number, // 0..1, how far along
 *   ease?: number, // seconds for this ease, see EaseSeconds
 * }} ZoneCameraState
 */

/** Outside every camera zone: nothing added, walls pull the camera in as usual. @type {CameraZone} */
const NO_CAMERA_ZONE = { distance: 0, height: 0, clip: true, front: false };

/**
 * What a camera trigger adds, from its name (see CAMERA_ZONE_NAME_PATTERN),
 * else CAMERA_ZONE_EXTRA_DISTANCE/_HEIGHT.
 * @param {string} triggerName @returns {CameraZone}
 */
function CameraZoneFromName(triggerName) {
    const closeup = CAMERA_CLOSEUP_NAME_PATTERN.exec(triggerName.trim());
    if (closeup) {
        // Close-up: like a front zone, the name gives the camera's spot
        // (behind / above the melon's center), stored as what it adds to the
        // normal offset — and no min-distance stop, so it can get this close.
        const behind = closeup[2] === undefined ? CAMERA_CLOSEUP_DISTANCE : Number(closeup[2]);
        const above = closeup[3] === undefined ? CAMERA_CLOSEUP_HEIGHT : Number(closeup[3]);
        return {
            distance: behind - CAMERA_DISTANCE,
            height: above - FOLLOW_OFFSET.z - CAMERA_HEIGHT,
            clip: !closeup[1],
            front: true,
            ease: CAMERA_CLOSEUP_EASE_SECONDS,
        };
    }
    const match = CAMERA_ZONE_NAME_PATTERN.exec(triggerName.trim());
    if (!match) {
        return { distance: CAMERA_ZONE_EXTRA_DISTANCE, height: CAMERA_ZONE_EXTRA_HEIGHT, clip: true, front: false };
    }
    const clip = !match[1];
    const value = Number(match[3]);
    if (match[2]) {
        // Front zone: the name gives the camera's spot (ahead of / above the
        // melon's center), stored like any zone as what it adds to the normal
        // offset, so easing in and out works the same.
        const above = match[4] === undefined ? CAMERA_ZONE_FRONT_HEIGHT : Number(match[4]);
        return {
            distance: -(CAMERA_DISTANCE + value),
            height: above - FOLLOW_OFFSET.z - CAMERA_HEIGHT,
            clip,
            front: true,
        };
    }
    return { distance: value, height: match[4] === undefined ? 0 : Number(match[4]), clip, front: false };
}

/** How much the zone zoom adds right now (smoothstep-eased). @param {ZoneCameraState | undefined} state */
function ZoneCameraExtra(state) {
    if (!state) {
        return { distance: 0, height: 0 };
    }
    const t = Math.max(0, Math.min(1, state.t));
    const eased = t * t * (3 - 2 * t);
    return {
        distance: state.from.distance + (state.to.distance - state.from.distance) * eased,
        height: state.from.height + (state.to.height - state.from.height) * eased,
    };
}

/**
 * Whether walls may pull the camera in: not while a noclip zone's zoom is on,
 * including while easing away from one (it would snap in mid-ease).
 * @param {ZoneCameraState | undefined} state
 */
function ZoneCameraClips(state) {
    return !state || (state.to.clip && (state.from.clip || state.t >= 1));
}

/**
 * Whether the camera may go in front of the melon: while a front zone is on,
 * including while easing away from one (the stop would make it jump).
 * @param {ZoneCameraState | undefined} state
 */
function ZoneCameraFront(state) {
    return !!state && (state.to.front || (state.from.front && state.t < 1));
}

/**
 * The zone zoom after `dt` more seconds, easing towards `target` (the zone
 * the melon is in, or NO_CAMERA_ZONE). A new target starts a fresh ease from
 * wherever the camera is now, so switching zones mid-ease doesn't jump.
 * Returns the same object when nothing changes, so callers can skip the camera update.
 * @param {ZoneCameraState | undefined} state @param {CameraZone} target @param {number} dt
 * @returns {ZoneCameraState | undefined}
 */
function StepZoneCamera(state, target, dt) {
    const current = state ?? { from: NO_CAMERA_ZONE, to: NO_CAMERA_ZONE, t: 1 };
    let next = current;
    const to = current.to;
    if (
        to.distance !== target.distance ||
        to.height !== target.height ||
        to.clip !== target.clip ||
        to.front !== target.front ||
        to.ease !== target.ease
    ) {
        const extra = ZoneCameraExtra(current);
        next = {
            from: { ...extra, clip: ZoneCameraClips(current), front: ZoneCameraFront(current) },
            to: target,
            t: 0,
            ease: EaseSeconds(to, target),
        };
    }
    if (next.t < 1) {
        const seconds = next.ease ?? CAMERA_ZONE_EASE_SECONDS;
        const step = seconds > 0 ? Math.max(0, dt) / seconds : 1;
        next = { ...next, t: Math.min(1, next.t + step) };
    }
    if (next === current) {
        return state;
    }
    // Fully back to normal: forget the state, same as never having been in a zone.
    return next.t >= 1 && next.to === NO_CAMERA_ZONE ? undefined : next;
}

/**
 * How long an ease from zone `from` to zone `to` takes: the zone being
 * entered sets it, or — leaving one for no zone — the zone being left, so a
 * close-up pulls back out as slowly as it went in.
 * @param {CameraZone} from @param {CameraZone} to
 */
function EaseSeconds(from, to) {
    return to.ease ?? (to === NO_CAMERA_ZONE ? from.ease : undefined) ?? CAMERA_ZONE_EASE_SECONDS;
}

/**
 * The chase camera offset with the zone zoom applied: x is forward (negative
 * = behind), z up. Zooming in stops CAMERA_ZONE_MIN_DISTANCE behind the melon,
 * except in a front zone (ZoneCameraFront).
 * @param {{ x: number, y: number, z: number }} base @param {ZoneCameraState | undefined} state
 */
function ZoneCameraOffset(base, state) {
    const extra = ZoneCameraExtra(state);
    if (ZoneCameraFront(state)) {
        return { x: base.x - extra.distance, y: base.y, z: base.z + extra.height };
    }
    return {
        x: Math.min(base.x - extra.distance, Math.max(base.x, -CAMERA_ZONE_MIN_DISTANCE)),
        y: base.y,
        z: base.z + extra.height,
    };
}

// The third-person chase camera: attaching it to the melon, its normal
// offset (CAMERA_DISTANCE/CAMERA_HEIGHT), and the one place that writes
// the follow config (SetFollowOffset) — the break, lift and camera-zone
// zooms (the other folders in camera/) all go through it. Walls pull the
// camera in through ../wall-clip/ (eased), not the engine.

/** The normal chase offset, before any zoom. @param {import("../../core/kart-registry.js").Kart} kart */
function GetCameraOffsetFor(kart) {
    return { x: -CAMERA_DISTANCE, y: CAMERA_LATERAL, z: CAMERA_HEIGHT };
}

/**
 * (Re-)applies the third-person follow camera from a kart's current
 * pawn/melon. Called whenever the camera needs attaching
 * (CustomPlayerCamera lives on the pawn instance, so this must be
 * re-called every time the player gets a fresh pawn, i.e. each respawn).
 * Keeps a lift zone's or camera zone's zoom if one is on (see ApplyZonedFollowOffset);
 * the wall pull-in starts over, right at the distance that fits.
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function ApplyCameraFollow(kart) {
    const camera = kart.pawn.GetCustomCamera();
    camera.SetMode(CustomCameraMode.FOLLOW_POSITION);
    kart.cameraWallScale = undefined;
    kart.appliedFollowKey = undefined;
    ApplyZonedFollowOffset(kart, 0);
    // In a side-view zone the side camera (../side-view/) keeps the camera —
    // the follow config above is only ready for when it hands back.
    if ((kart.sideViewBlend ?? 0) > 0) {
        camera.SetMode(CustomCameraMode.CONTROLLED);
    }
    Debug(`ApplyCameraFollow: mode=${camera.GetMode()} for slot=${kart.pawn.GetPlayerController()?.GetPlayerSlot()}`);
}

/**
 * Per tick: the chase camera with every zoom and the wall pull-in eased on.
 * Left alone while the melon is breaking — the break camera owns it then,
 * and the respawn re-applies it — in free look (dev/free-look.js) and while
 * the side-view camera has it (../side-view/).
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} dt
 */
function UpdateFollowCamera(kart, dt) {
    if (kart.breaking || kart.freeLook || (kart.sideViewBlend ?? 0) > 0) {
        return;
    }
    ApplyZonedFollowOffset(kart, dt);
}

/**
 * The normal offset with both zone zooms on top — the lift zoom
 * (kart.liftCameraBlend, lift-zoom.js) and the camera-zone zoom
 * (kart.zoneCamera, zone-zoom.js); they add up. Walls pull the camera in
 * (wall-clip.js, eased over `dt`) only while neither turns that off.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} dt
 */
function ApplyZonedFollowOffset(kart, dt) {
    const liftBlend = kart.liftCameraBlend ?? 0;
    const offset = ZonedFollowOffset(kart);
    const clips = liftBlend === 0 && ZoneCameraClips(kart.zoneCamera);
    if (!clips) {
        kart.cameraWallScale = undefined; // no wall pull-in out here; starts over once it's back on
    }
    const placed = clips ? WallClippedOffset(kart, offset, dt) : offset;
    const key = `${placed.x.toFixed(2)},${placed.y.toFixed(2)},${placed.z.toFixed(2)}`;
    if (key === kart.appliedFollowKey) {
        return; // unchanged since the last tick — don't rewrite the engine's config
    }
    SetFollowOffset(kart, placed, false);
    kart.appliedFollowKey = key;
}

/**
 * The normal offset with both zone zooms on top, before the wall pull-in.
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function ZonedFollowOffset(kart) {
    return ZoneCameraOffset(LiftCameraOffset(GetCameraOffsetFor(kart), kart.liftCameraBlend ?? 0), kart.zoneCamera);
}

/**
 * Points the chase camera at the melon from `cameraOffset` (x forward,
 * negative = behind; z up — rotated by the player's eye angles).
 * @param {import("../../core/kart-registry.js").Kart} kart @param {{ x: number, y: number, z: number }} cameraOffset
 * @param {boolean} engineClipsToWalls let the engine pull the camera in at walls (instantly) — only the
 *   break camera does; everything else goes through ApplyZonedFollowOffset's own, eased pull-in
 */
function SetFollowOffset(kart, cameraOffset, engineClipsToWalls) {
    kart.pawn.GetCustomCamera().SetFollowConfig({
        followEntity: kart.melon,
        followOffset: FOLLOW_OFFSET,
        cameraOffset,
        clipCameraOffset: engineClipsToWalls,
        cameraOffsetReturnStrength: CAMERA_OFFSET_RETURN_STRENGTH,
    });
    kart.appliedFollowKey = undefined;
}

// Pure rules for the melon-break sequence — no cs_script import, so it's
// unit-testable in Node (see test/health/break-sequence.test.mjs). health/breaking/effects.js
// and camera/ apply the results (camera config, entity removal).

/**
 * Moves a group of points so their centroid lands on `target`, keeping
 * their layout relative to each other. ForceSpawn keeps each templated
 * entity's Hammer offset from its point_template — break pieces placed
 * next to (not on) the template would otherwise appear that far away from
 * the crash site, possibly inside a wall.
 * @param {Array<{ x: number, y: number, z: number }>} points @param {{ x: number, y: number, z: number }} target
 */
function RecenterOnto(points, target) {
    if (points.length === 0) {
        return [];
    }
    const c = { x: 0, y: 0, z: 0 };
    for (const p of points) {
        c.x += p.x / points.length;
        c.y += p.y / points.length;
        c.z += p.z / points.length;
    }
    return points.map((p) => ({ x: p.x - c.x + target.x, y: p.y - c.y + target.y, z: p.z - c.z + target.z }));
}

/**
 * Launch velocity for one break piece: away from the crash site (the
 * direction from `center` to where the piece spawned, flattened so the
 * pieces spread along the ground), plus an upward pop. A piece that spawned
 * right at the center has no direction of its own, so it uses `fallbackAngle`
 * (radians; the caller passes a random one).
 * @param {{ x: number, y: number, z: number }} center @param {{ x: number, y: number, z: number }} piecePosition @param {number} fallbackAngle
 */
function BreakPieceVelocity(center, piecePosition, fallbackAngle) {
    let dx = piecePosition.x - center.x;
    let dy = piecePosition.y - center.y;
    const length = Math.hypot(dx, dy);
    if (length < 1e-3) {
        dx = Math.cos(fallbackAngle);
        dy = Math.sin(fallbackAngle);
    } else {
        dx /= length;
        dy /= length;
    }
    return { x: dx * BREAK_PIECE_SPEED, y: dy * BREAK_PIECE_SPEED, z: BREAK_PIECE_UP_SPEED };
}

/**
 * How far the break camera has zoomed out, 0 (normal chase offset) to 1
 * (fully pulled back), `elapsed` seconds after the break. Eases out, so the
 * pull-back starts fast and settles gently.
 * @param {number} elapsed
 */
function BreakCameraZoomFraction(elapsed) {
    if (!(elapsed > 0)) {
        return 0;
    }
    const t = Math.min(1, elapsed / BREAK_CAMERA_ZOOM_SECONDS);
    return 1 - (1 - t) * (1 - t);
}

/**
 * The chase camera's cameraOffset `elapsed` seconds after a break, starting
 * from the player's normal offset (x is forward, so "further back" is more
 * negative x; z is up).
 * @param {{ x: number, y: number, z: number }} baseOffset @param {number} elapsed
 */
function BreakCameraOffset(baseOffset, elapsed) {
    const f = BreakCameraZoomFraction(elapsed);
    return {
        x: baseOffset.x - f * BREAK_CAMERA_EXTRA_DISTANCE,
        y: baseOffset.y,
        z: baseOffset.z + f * BREAK_CAMERA_EXTRA_HEIGHT,
    };
}

/**
 * Splits the live break effects into ones to remove now and ones to keep:
 * anything older than BREAK_EFFECT_LIFETIME goes, and beyond that the oldest
 * ones go until at most BREAK_EFFECT_MAX_ACTIVE remain. Order of `effects`
 * doesn't matter; `kept` comes back oldest first.
 * @template {{ spawnTime: number }} T
 * @param {T[]} effects @param {number} now
 * @returns {{ expired: T[], kept: T[] }}
 */
function PruneBreakEffects(effects, now) {
    const sorted = [...effects].sort((a, b) => a.spawnTime - b.spawnTime);
    const expired = [];
    const kept = [];
    for (const effect of sorted) {
        (now - effect.spawnTime >= BREAK_EFFECT_LIFETIME ? expired : kept).push(effect);
    }
    const overflow = Math.max(0, kept.length - BREAK_EFFECT_MAX_ACTIVE);
    expired.push(...kept.splice(0, overflow));
    return { expired, kept };
}

// Break camera: pulls back from a broken melon so the burst is visible
// (BREAK_CAMERA_* and the math, BreakCameraOffset, are in health/breaking/).

/**
 * Pulls the chase camera back from a broken melon (still frozen, hidden, at
 * the crash site) so the burst is visible — called every tick while
 * kart.breaking; ApplyCameraFollow restores the normal offset on respawn.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} elapsed seconds since the break
 */
function ApplyBreakCameraZoom(kart, elapsed) {
    SetFollowOffset(kart, BreakCameraOffset(GetCameraOffsetFor(kart), elapsed), true);
}

// Pure lift-zone rules — no cs_script import, so it's unit-testable in Node
// (see test/zones/lift-zone.test.mjs). Everything a lift zone changes about wall
// bounces and wall jumps is decided here, in one place: drive.js and jump.js
// just read the WallRules they're handed.

/**
 * @typedef {{
 *   inLift: boolean,
 *   bounceUpSpeed: number, // upward kick of a wall bounce (u/s)
 *   minBounceSpeed: number, // a bounce leaves the wall at least this fast (u/s), 0 = no minimum
 *   wallJumpCooldown: number, // seconds between two wall jumps
 *   wallJumpWindow: number, // seconds a wall contact stays jumpable
 *   freeWallJumps: boolean, // wall jumps cost no charge, are full strength, may follow a bounce at once
 *   jumpBuffer: number, // seconds a jump press before touching a wall still counts, 0 = none
 *   ratedWallJumps: boolean, // wall jumps are rated by angle (boost, PERFECT kick, feedback) — not in lift or side-view zones
 *   wallJumpUpSpeed: number, // a wall jump's upward speed (u/s)
 *   wallJumpPushSpeed: number, // a wall jump's push away from the wall, at least (u/s)
 * }} WallRules
 */

/**
 * The wall bounce / wall jump rules for a melon, given the kick of the
 * strongest lift zone it's in (undefined = not in one) and whether it's in a
 * side-view zone — there wall jumps aren't rated either (a 2D jump & run's
 * walls are jumped at whatever angle the plane allows) but go higher and
 * further (SIDE_VIEW_WALL_JUMP_*), with a lift zone's timing (short cooldown,
 * longer contact window, jump buffer) so wall-to-wall jumps chain, and like
 * there they cost no charge (freeWallJumps).
 * @param {number | undefined} liftUpSpeed @param {boolean} [inSideView]
 * @returns {WallRules}
 */
function WallRules(liftUpSpeed, inSideView = false) {
    if (liftUpSpeed === undefined) {
        return {
            inLift: false,
            bounceUpSpeed: WALL_BOUNCE_UP_SPEED,
            minBounceSpeed: 0,
            wallJumpCooldown: inSideView ? LIFT_ZONE_WALL_JUMP_COOLDOWN : WALL_JUMP_COOLDOWN,
            wallJumpWindow: inSideView ? LIFT_ZONE_WALL_JUMP_WINDOW : WALL_JUMP_WINDOW,
            freeWallJumps: inSideView,
            jumpBuffer: inSideView ? LIFT_ZONE_JUMP_BUFFER : 0,
            ratedWallJumps: !inSideView,
            wallJumpUpSpeed: inSideView ? SIDE_VIEW_WALL_JUMP_UP_SPEED : WALL_JUMP_UP_SPEED,
            wallJumpPushSpeed: inSideView ? SIDE_VIEW_WALL_JUMP_PUSH_SPEED : WALL_JUMP_PUSH_SPEED,
        };
    }
    return {
        inLift: true,
        // A lift zone never kicks weaker than outside one.
        bounceUpSpeed: Math.max(WALL_BOUNCE_UP_SPEED, liftUpSpeed),
        minBounceSpeed: LIFT_ZONE_MIN_BOUNCE_SPEED,
        wallJumpCooldown: LIFT_ZONE_WALL_JUMP_COOLDOWN,
        wallJumpWindow: LIFT_ZONE_WALL_JUMP_WINDOW,
        freeWallJumps: true,
        jumpBuffer: LIFT_ZONE_JUMP_BUFFER,
        ratedWallJumps: false,
        wallJumpUpSpeed: WALL_JUMP_UP_SPEED,
        wallJumpPushSpeed: WALL_JUMP_PUSH_SPEED,
    };
}

/**
 * Upward kick of a lift trigger: parsed from a "lift_zone_<speed>" name,
 * else LIFT_ZONE_UP_SPEED.
 * @param {string} triggerName
 */
function LiftZoneUpSpeed(triggerName) {
    const match = LIFT_ZONE_NAME_PATTERN.exec(triggerName.trim());
    return match ? Number(match[1]) : LIFT_ZONE_UP_SPEED;
}

// Trigger zones the melon can be inside — heal zones (heal_enter/heal_leave,
// read by ../heal/), lift zones (lift_enter/lift_leave, zones/lift/constants.js) and
// camera zones (camera_enter/camera_leave, CAMERA_ZONE_* in camera-zone/constants.js)
// jump pads (jump_pad_enter/jump_pad_leave, zones/jump-pad/constants.js)
// water zones (water_enter/water_leave, zones/water/constants.js)
// side-view zones (side_view_enter/side_view_leave, zones/side-view/constants.js)
// and jump recharge zones (jump_recharge_enter/jump_recharge_leave, zones/jump-recharge/logic.js):
// entering/leaving them (registered in inputs.js), what they add up
// to right now, and leaving them all at once when a new melon replaces the old.
// Each kind is a Map on the kart: trigger entity -> its value (heal rate in
// health/s, lift kick in u/s, camera zoom), so overlapping zones and their leaves are
// tracked separately.

/** @typedef {"healZones" | "liftZones" | "cameraZones" | "jumpPads" | "waterZones" | "sideViews" | "jumpRecharges"} ZoneKind */

/**
 * The melon entered a zone trigger of this kind, worth `value`.
 * @param {import("../core/kart-registry.js").Kart} kart @param {ZoneKind} kind @param {any} trigger @param {any} value
 */
function EnterZone(kart, kind, trigger, value) {
    (kart[kind] ??= new Map()).set(trigger, value);
}

/** @param {import("../core/kart-registry.js").Kart} kart @param {ZoneKind} kind @param {any} trigger */
function LeaveZone(kart, kind, trigger) {
    kart[kind]?.delete(trigger);
}

/**
 * Forgets every zone the melon was in — only for a brand new melon entity,
 * whose predecessor's zones never send OnEndTouch (the new one gets its own
 * OnStartTouch). Not for teleports of the same melon: landing back inside the
 * same trigger (e.g. respawning in the zone it broke in) sends no new
 * OnStartTouch, so clearing would lose the zone; leaving it by teleport
 * sends OnEndTouch like any other exit.
 * @param {import("../core/kart-registry.js").Kart} kart
 */
function LeaveZones(kart) {
    kart.healZones?.clear();
    kart.liftZones?.clear();
    kart.cameraZones?.clear();
    kart.jumpPads?.clear();
    kart.waterZones?.clear();
    kart.sideViews?.clear();
    kart.jumpRecharges?.clear();
}

/**
 * The strongest value of the zones of this kind the melon is inside, or
 * undefined if none — overlapping zones don't stack. Zone entities that no
 * longer exist are dropped.
 * @param {import("../core/kart-registry.js").Kart} kart @param {ZoneKind} kind
 */
function StrongestZone(kart, kind) {
    const zones = kart[kind];
    let strongest = undefined;
    for (const [zone, value] of zones ?? []) {
        if (!zone.IsValid()) {
            zones?.delete(zone);
            continue;
        }
        strongest = strongest === undefined ? value : Math.max(strongest, value);
    }
    return strongest;
}

/** Whether the melon is inside a lift zone. @param {import("../core/kart-registry.js").Kart} kart */
function InLiftZone(kart) {
    return StrongestZone(kart, "liftZones") !== undefined;
}

/**
 * Whether the melon is inside a water zone — its drag and buoyancy aren't
 * impacts, see zones/water/constants.js.
 * @param {import("../core/kart-registry.js").Kart} kart
 */
function InWater(kart) {
    return StrongestZone(kart, "waterZones") !== undefined;
}

/**
 * Whether the melon is inside a jump recharge zone — its wall-jump charges
 * are kept full there.
 * @param {import("../core/kart-registry.js").Kart} kart
 */
function InJumpRechargeZone(kart) {
    return StrongestZone(kart, "jumpRecharges") !== undefined;
}

/** The wall bounce / wall jump rules for where the melon is now (see WallRules). @param {import("../core/kart-registry.js").Kart} kart */
function CurrentWallRules(kart) {
    return WallRules(StrongestZone(kart, "liftZones"), CurrentSideView(kart) !== undefined);
}

/**
 * The launch of the jump pad the melon entered last (of those it's still
 * on), or undefined if it's on none.
 * @param {import("../core/kart-registry.js").Kart} kart
 * @returns {import("./jump-pad/logic.js").JumpPad | undefined}
 */
function CurrentJumpPad(kart) {
    return LatestZone(kart, "jumpPads");
}

/**
 * The zoom of the camera zone the melon entered last (of those it's still
 * inside), or undefined if none — overlapping camera zones don't add up.
 * @param {import("../core/kart-registry.js").Kart} kart
 * @returns {import("./camera-zone/logic.js").CameraZone | undefined}
 */
function CurrentCameraZone(kart) {
    return LatestZone(kart, "cameraZones");
}

/**
 * The side view of the side-view zone the melon entered last (of those it's
 * still inside), or undefined if none.
 * @param {import("../core/kart-registry.js").Kart} kart
 * @returns {import("./side-view/logic.js").SideView | undefined}
 */
function CurrentSideView(kart) {
    return LatestZone(kart, "sideViews");
}

/**
 * The value of the zone of this kind the melon entered last (of those it's
 * still inside), or undefined if none. Zone entities that no longer exist
 * are dropped.
 * @param {import("../core/kart-registry.js").Kart} kart @param {ZoneKind} kind
 */
function LatestZone(kart, kind) {
    const zones = kart[kind];
    let latest = undefined;
    for (const [zone, value] of zones ?? []) {
        if (!zone.IsValid()) {
            zones?.delete(zone);
            continue;
        }
        latest = value; // Map order = entry order
    }
    return latest;
}

// Lift camera: zooms out while the melon is in a lift zone (LIFT_CAMERA_* in
// constants.js, the math in logic.js).

/**
 * Per tick: eases the chase camera out while the melon is in a lift zone and
 * back in after it leaves (UpdateFollowCamera in follow.js applies the
 * zoom right after). Wall clipping is off for as long as it's zoomed out at
 * all (it looks through the shaft walls instead). Left alone while the melon
 * is breaking — the break camera owns it then, and the respawn re-applies it.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} dt
 */
function UpdateLiftCamera(kart, dt) {
    if (kart.breaking) {
        return;
    }
    kart.liftCameraBlend = LiftCameraBlend(kart.liftCameraBlend ?? 0, InLiftZone(kart), dt);
}

// Camera zones: zoom in or out while the melon is in a camera_enter/_leave
// trigger (CAMERA_ZONE_* and the math are in zones/camera-zone/).

/**
 * Per tick: eases the chase camera towards the zoom of the camera zone the
 * melon is in, and back to normal after it leaves (UpdateFollowCamera in
 * follow.js applies the zoom right after). Left alone while the melon is
 * breaking — the break camera owns it then, and the respawn re-applies it.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} dt
 */
function UpdateZoneCamera(kart, dt) {
    if (kart.breaking) {
        return;
    }
    kart.zoneCamera = StepZoneCamera(kart.zoneCamera, CurrentCameraZone(kart) ?? NO_CAMERA_ZONE, dt);
}

// Pure rules for side-view zones — no cs_script import, so it's unit-testable
// in Node (see test/zones/side-view.test.mjs). movement/driving/drive.js
// applies the driving part, camera/side-view/ the camera.

/** @typedef {{ yaw: number, distance: number, height: number }} SideView where the camera looks from */
/** @typedef {{ x: number, y: number }} Dir2 a horizontal unit direction */

/**
 * The side view a trigger sets up, from its name (see SIDE_VIEW_NAME_PATTERN),
 * else the SIDE_VIEW_* defaults.
 * @param {string} triggerName @returns {SideView}
 */
function SideViewFromName(triggerName) {
    const match = SIDE_VIEW_NAME_PATTERN.exec(triggerName.trim());
    if (!match) {
        return { yaw: SIDE_VIEW_DEFAULT_YAW, distance: SIDE_VIEW_DISTANCE, height: SIDE_VIEW_HEIGHT };
    }
    return {
        yaw: Number(match[1]),
        distance: match[2] === undefined ? SIDE_VIEW_DISTANCE : Number(match[2]),
        height: match[3] === undefined ? SIDE_VIEW_HEIGHT : Number(match[3]),
    };
}

/**
 * The side view's two horizontal axes: `view` = the way the camera looks
 * (into the screen), `right` = screen right, the way D drives.
 * @param {number} yaw @returns {{ view: Dir2, right: Dir2 }}
 */
function SideViewAxes(yaw) {
    const rad = (yaw * Math.PI) / 180;
    return {
        view: { x: Math.cos(rad), y: Math.sin(rad) },
        right: { x: Math.sin(rad), y: -Math.cos(rad) },
    };
}

/**
 * Which way the melon faces on screen when it enters a side view: the way
 * it's moving along the screen axis, right if it isn't.
 * @param {{ x: number, y: number }} velocity @param {Dir2} right @returns {1 | -1}
 */
function InitialFacing(velocity, right) {
    return velocity.x * right.x + velocity.y * right.y < 0 ? -1 : 1;
}

/**
 * Driving input in a side view. A/D drive left/right on screen and turn the
 * melon that way; W drives the way it faces, S the other way (without
 * turning it). The mouse does nothing.
 * @param {number} forwardInput W/S, -1..1 @param {number} strafeInput D/A, -1..1 @param {1 | -1} facing
 * @returns {{ axis: number, facing: 1 | -1 }} axis: -1..1 along screen right (0 = no input)
 */
function SideViewInput(forwardInput, strafeInput, facing) {
    if (strafeInput !== 0) {
        return { axis: strafeInput, facing: strafeInput < 0 ? -1 : 1 };
    }
    return { axis: forwardInput * facing, facing };
}

/** How far along `view` (towards the camera's far side) a point is. @param {{ x: number, y: number }} origin @param {Dir2} view */
function PlaneDepth(origin, view) {
    return origin.x * view.x + origin.y * view.y;
}

/**
 * Horizontal velocity `v` kept on the side view's plane: its part towards or
 * away from the camera is dropped, replaced by a pull back onto the plane
 * (SIDE_VIEW_PLANE_PULL, at most SIDE_VIEW_PLANE_MAX_SPEED).
 * @param {{ x: number, y: number }} v @param {Dir2} view
 * @param {number} depthError plane depth minus the melon's depth (see PlaneDepth)
 * @returns {{ x: number, y: number }}
 */
function KeepOnPlane(v, view, depthError) {
    const depth = v.x * view.x + v.y * view.y;
    const pull = Math.max(-SIDE_VIEW_PLANE_MAX_SPEED, Math.min(SIDE_VIEW_PLANE_MAX_SPEED, depthError * SIDE_VIEW_PLANE_PULL));
    return { x: v.x + view.x * (pull - depth), y: v.y + view.y * (pull - depth) };
}

// Pure rules for the side-view camera — no cs_script import, so it's
// unit-testable in Node (see test/camera/side-view.test.mjs). side-view.js
// next to it places the camera.

/**
 * @typedef {{ position: { x: number, y: number, z: number }, angles: { pitch: number, yaw: number, roll: number } }} CameraPose
 */

/**
 * How far the camera has swung to the side after `dt` more seconds, 0 (chase
 * camera) to 1 (side view): linearly towards 1 inside a side-view zone and
 * towards 0 outside, SIDE_VIEW_EASE_SECONDS for the whole way.
 * @param {number} blend @param {boolean} inSideView @param {number} dt
 */
function StepSideViewBlend(blend, inSideView, dt) {
    const step = SIDE_VIEW_EASE_SECONDS > 0 ? Math.max(0, dt) / SIDE_VIEW_EASE_SECONDS : 1;
    return inSideView ? Math.min(1, blend + step) : Math.max(0, blend - step);
}

/**
 * The side camera: `distance` back from `target` against the view direction
 * and `height` above it, looking at it.
 * @param {{ x: number, y: number, z: number }} target the melon's center
 * @param {import("../../zones/side-view/logic.js").SideView} sideView @returns {CameraPose}
 */
function SideViewPose(target, sideView) {
    const { view } = SideViewAxes(sideView.yaw);
    return {
        position: {
            x: target.x - view.x * sideView.distance,
            y: target.y - view.y * sideView.distance,
            z: target.z + sideView.height,
        },
        // Pitch positive = looking down, as in Source.
        angles: { pitch: (Math.atan2(sideView.height, sideView.distance) * 180) / Math.PI, yaw: sideView.yaw, roll: 0 },
    };
}

/**
 * Where the chase camera (FOLLOW_POSITION) is: `offset` from `pivot`, turned
 * by the eye angles, looking along them.
 * @param {{ x: number, y: number, z: number }} pivot the melon + FOLLOW_OFFSET
 * @param {{ x: number, y: number, z: number }} offset @param {{ pitch: number, yaw: number }} eyeAngles
 * @returns {CameraPose}
 */
function ChaseCameraPose(pivot, offset, eyeAngles) {
    const d = RotateCameraOffset(offset, eyeAngles);
    return {
        position: { x: pivot.x + d.x, y: pivot.y + d.y, z: pivot.z + d.z },
        angles: { pitch: eyeAngles.pitch, yaw: eyeAngles.yaw, roll: 0 },
    };
}

/**
 * `from` -> `to` at `t` (0..1, smoothstep-eased); the yaw turns the short way round.
 * @param {CameraPose} from @param {CameraPose} to @param {number} t @returns {CameraPose}
 */
function BlendPose(from, to, t) {
    const c = Math.max(0, Math.min(1, t));
    const e = c * c * (3 - 2 * c);
    const lerp = (/** @type {number} */ a, /** @type {number} */ b) => a + (b - a) * e;
    const yawDiff = ((((to.angles.yaw - from.angles.yaw) % 360) + 540) % 360) - 180;
    return {
        position: {
            x: lerp(from.position.x, to.position.x),
            y: lerp(from.position.y, to.position.y),
            z: lerp(from.position.z, to.position.z),
        },
        angles: { pitch: lerp(from.angles.pitch, to.angles.pitch), yaw: from.angles.yaw + yawDiff * e, roll: 0 },
    };
}

// Pure rules for generic teleporters — no cs_script import, so it's
// unit-testable in Node (see test/zones/teleport.test.mjs). zones/teleport/inputs.js's
// melon_teleport handler does the entity lookups and the actual teleport.

/**
 * What a teleport trigger's own name encodes
 * (teleport_[stop_|keep_][checkpoint_]to_<destination>): the destination
 * entity's name, whether the melon keeps its speed (stop/keep, else
 * TELEPORT_KEEP_SPEED) and whether the destination becomes its respawn
 * point (checkpoint_) — or undefined if the name doesn't follow that
 * convention. Surrounding whitespace is ignored — Hammer keeps stray spaces.
 * @param {string} triggerName
 * @returns {{ destination: string, keepSpeed: boolean, setsRespawn: boolean } | undefined}
 */
function ParseTeleportTrigger(triggerName) {
    const match = TELEPORT_TRIGGER_NAME_PATTERN.exec(triggerName.trim());
    if (!match) {
        return undefined;
    }
    const keepSpeed = match[1] === "stop" ? false : match[1] === "keep" ? true : TELEPORT_KEEP_SPEED;
    return { destination: match[3], keepSpeed, setsRespawn: match[2] !== undefined };
}

/**
 * Just the destination entity's name from a teleport trigger's name (see
 * ParseTeleportTrigger), or undefined.
 * @param {string} triggerName
 */
function ParseTeleportTarget(triggerName) {
    return ParseTeleportTrigger(triggerName)?.destination;
}

/**
 * The player's view right after any teleport: turned to face `yaw` (the
 * destination's facing), keeping how far up/down they were looking so the
 * camera doesn't jerk vertically. Steering follows the view's yaw (see
 * UpdateKart), so without this a teleported player kept driving in their
 * old direction.
 * @param {{ pitch: number }} currentEye @param {number} yaw
 */
function ViewAnglesFacing(currentEye, yaw) {
    return { pitch: currentEye.pitch, yaw, roll: 0 };
}

/**
 * The melon's velocity right after the teleport: its horizontal speed
 * carried over but pointed along the destination's facing (so a teleporter
 * keeps the race's flow instead of dead-stopping the melon), or zero with
 * keepSpeed off (the trigger's stop/keep mode, default TELEPORT_KEEP_SPEED).
 * Vertical speed is always dropped — a melon teleported mid-fall would
 * otherwise slam into the floor on arrival.
 * @param {{ x: number, y: number, z: number }} velocity @param {number} destinationYaw degrees
 * @param {boolean} [keepSpeed]
 */
function TeleportExitVelocity(velocity, destinationYaw, keepSpeed = TELEPORT_KEEP_SPEED) {
    if (!keepSpeed) {
        return { x: 0, y: 0, z: 0 };
    }
    const speed = Math.hypot(velocity.x, velocity.y);
    const rad = (destinationYaw * Math.PI) / 180;
    return { x: Math.cos(rad) * speed, y: Math.sin(rad) * speed, z: 0 };
}

// Side-view camera: while the melon is in a side-view zone
// (zones/side-view/), the camera stops chasing it along the mouse and looks
// at it from one side, like a 2D jump & run. The camera is switched to
// CONTROLLED mode and placed by script every tick; it swings over from the
// chase camera and back (SIDE_VIEW_EASE_SECONDS, the math in logic.js).

/** Whether the side-view camera has the camera (also while swinging in or out). @param {import("../../core/kart-registry.js").Kart} kart */
function SideViewCameraOn(kart) {
    return (kart.sideViewBlend ?? 0) > 0;
}

/**
 * Per tick: swings the camera to the side while the melon is in a side-view
 * zone and back to the chase camera after it leaves. Left alone while the
 * melon is breaking — the camera just stays where it was, watching the crash
 * site — and in free look (dev/free-look.js).
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} dt
 */
function UpdateSideViewCamera(kart, dt) {
    if (kart.breaking || kart.freeLook) {
        return;
    }
    const zone = CurrentSideView(kart);
    if (!zone && kart.sideViewZone) {
        LookAlongTravel(kart, kart.sideViewZone);
    }
    if (zone) {
        kart.sideViewZone = zone;
    }
    const before = kart.sideViewBlend ?? 0;
    const blend = StepSideViewBlend(before, Boolean(zone), dt);
    kart.sideViewBlend = blend;
    if (!zone) {
        kart.sideViewZone = undefined;
    }
    if (blend === 0) {
        if (before > 0) {
            kart.sideViewLast = undefined;
            ApplyCameraFollow(kart); // back to the chase camera
        }
        return;
    }
    const sideView = kart.sideViewZone ?? kart.sideViewLast;
    if (!sideView) {
        return;
    }
    kart.sideViewLast = sideView; // swinging back out: from the zone just left
    const camera = kart.pawn.GetCustomCamera();
    if (camera.GetMode() !== CustomCameraMode.CONTROLLED) {
        camera.SetMode(CustomCameraMode.CONTROLLED);
        Debug(`side view: slot ${kart.pawn.GetPlayerController()?.GetPlayerSlot()} camera to the side (yaw ${sideView.yaw})`);
    }
    const origin = kart.melon.GetAbsOrigin();
    const side = SideViewPose(origin, sideView);
    const pose =
        blend >= 1
            ? side
            : BlendPose(
                  ChaseCameraPose(
                      { x: origin.x + FOLLOW_OFFSET.x, y: origin.y + FOLLOW_OFFSET.y, z: origin.z + FOLLOW_OFFSET.z },
                      ZonedFollowOffset(kart),
                      kart.pawn.GetEyeAngles()
                  ),
                  side,
                  blend
              );
    camera.Move({ position: pose.position, angles: pose.angles });
}

/**
 * Leaving a side view: turns the player's view the way the melon goes on
 * screen — steering follows the view again, and the mouse may have pointed
 * anywhere meanwhile. The chase camera then swings in behind it.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {import("../../zones/side-view/logic.js").SideView} sideView
 */
function LookAlongTravel(kart, sideView) {
    if (!kart.pawn.IsValid()) {
        return;
    }
    const { right } = SideViewAxes(sideView.yaw);
    const facing = kart.sideViewDrive?.facing ?? 1;
    const yaw = (Math.atan2(right.y * facing, right.x * facing) * 180) / Math.PI;
    kart.pawn.Teleport({ angles: ViewAnglesFacing(kart.pawn.GetEyeAngles(), yaw) });
}

// Chase camera — one folder per feature: follow/ (the normal chase camera and
// the one place that writes the follow config), wall-clip/ (eased pull-in at
// walls), break-zoom/ (pull-back on a break), lift-zoom/ (zoom-out in lift
// zones), zone-zoom/ (zoom in/out in camera zones), side-view/ (the fixed
// side camera in side-view zones). Other parts of
// melon_drive import from here.

// Pure spawn-point rules — no cs_script import, so they're unit-testable in
// Node (test/kart/spawn-points-logic.test.mjs). Applied by kart/spawn-points.js.

/**
 * Index of the point in `points` nearest to `origin`, if it's within
 * `maxDistance` — undefined if there's none that close. Picks a gate
 * prefab's own shared-name spawn ("start_spawn", "checkpoint_spawn") for its
 * trigger: every copy of the gate carries one, and its own is the one right
 * next to it.
 * @param {Array<{ x: number, y: number, z: number }>} points
 * @param {{ x: number, y: number, z: number }} origin
 * @param {number} maxDistance
 * @returns {number | undefined}
 */
function NearestWithin(points, origin, maxDistance) {
    const maxDistanceSq = maxDistance * maxDistance;
    let best;
    let bestDistanceSq = Infinity;
    points.forEach((p, i) => {
        const dx = p.x - origin.x;
        const dy = p.y - origin.y;
        const dz = p.z - origin.z;
        const distanceSq = dx * dx + dy * dy + dz * dz;
        if (distanceSq <= maxDistanceSq && distanceSq < bestDistanceSq) {
            best = i;
            bestDistanceSq = distanceSq;
        }
    });
    return best;
}

// The one place that turns a Hammer spawn entity into a melon position.
// Every caller that puts a melon at the hub or the intro goes through here,
// so they all agree on where exactly that is.

/**
 * @typedef {{ position: { x: number, y: number, z: number }, angles: { pitch: number, yaw: number, roll: number } }} SpawnPoint
 */

/**
 * `origin` lifted by `upOffset` — a melon placed exactly at a floor-level
 * entity's origin would start embedded in the floor and fall through it.
 * @param {{ x: number, y: number, z: number }} origin @param {number} upOffset
 */
function Lifted(origin, upOffset) {
    return { x: origin.x, y: origin.y, z: origin.z + upOffset };
}

/**
 * Turns a player's view to face `yaw` — called after every teleport or
 * spawn of their melon, so they look (and steer) the way the destination
 * faces. Teleport with only angles sets a player pawn's eye angles and
 * leaves its (frozen) position alone.
 * @param {any} pawn @param {number} yaw
 */
function FacePlayerView(pawn, yaw) {
    if (!pawn?.IsValid()) {
        return;
    }
    pawn.Teleport({ angles: ViewAnglesFacing(pawn.GetEyeAngles(), yaw) });
}

/** Level angles (no pitch/roll) facing `yaw` — a melon should never spawn tilted. @param {number} yaw */
function LevelAngles(yaw) {
    return { pitch: 0, yaw, roll: 0 };
}

/**
 * Where a melon should appear for a spawn entity at `origin`: SPAWN_UP_OFFSET
 * above the real floor under it, found by tracing down — so it doesn't
 * matter whether the entity sits on, slightly in, or floating above the
 * floor in Hammer. The trace starts a bit above the entity in case it's
 * sunk into the floor. No floor found: just SPAWN_UP_OFFSET above the entity.
 * @param {{ x: number, y: number, z: number }} origin
 */
function PositionAboveFloor(origin) {
    const trace = TraceLine({
        start: Lifted(origin, FLOOR_TRACE_UP),
        end: Lifted(origin, -FLOOR_TRACE_DOWN),
        ignorePlayers: true,
    });
    if (!trace.didHit || trace.startedInSolid) {
        Debug(`PositionAboveFloor: no floor found below ${JSON.stringify(origin)}, spawning relative to the entity itself`);
        return Lifted(origin, SPAWN_UP_OFFSET);
    }
    return Lifted(trace.end, SPAWN_UP_OFFSET);
}

/**
 * Spawn point of the entity named `name`, facing the entity named
 * `facingName` if given and placed, otherwise the entity's own yaw.
 * @param {string} name @param {string} [facingName]
 * @returns {SpawnPoint | undefined}
 */
function FindSpawnPoint(name, facingName) {
    const entity = Instance.FindEntityByName(name);
    if (!entity) {
        return undefined;
    }
    const facing = (facingName && Instance.FindEntityByName(facingName)) || entity;
    return {
        position: PositionAboveFloor(entity.GetAbsOrigin()),
        angles: LevelAngles(facing.GetAbsAngles().yaw),
    };
}

/**
 * Spawn point of the entity named `name` nearest to `trigger`, within
 * `maxDistance` — a gate prefab's own spawn (every copy of a start or
 * checkpoint gate has one by that shared name). Undefined if none is that
 * close.
 * @param {string} name @param {any} trigger @param {number} maxDistance
 * @returns {SpawnPoint | undefined}
 */
function FindSharedSpawnPoint(name, trigger, maxDistance) {
    const candidates = Instance.FindEntitiesByName(name);
    if (candidates.length === 0) {
        return undefined;
    }
    const origin = trigger.GetAbsOrigin();
    const nearest = NearestWithin(candidates.map((e) => e.GetAbsOrigin()), origin, maxDistance);
    if (nearest === undefined) {
        Debug(`FindSharedSpawnPoint: no "${name}" within ${maxDistance} units of "${trigger.GetEntityName()}"`);
        return undefined;
    }
    const entity = candidates[nearest];
    return {
        position: PositionAboveFloor(entity.GetAbsOrigin()),
        angles: LevelAngles(entity.GetAbsAngles().yaw),
    };
}

/** Where karts go in the hub: the hub_spawn info_player_start, facing hub_spawn_facing. */
function GetHubSpawnPoint() {
    const spawn = FindSpawnPoint(HUB_SPAWN_NAME, HUB_SPAWN_FACING_NAME);
    if (!spawn) {
        Debug(`GetHubSpawnPoint: no "${HUB_SPAWN_NAME}" in the map — nowhere to put melons`);
    }
    return spawn;
}

/** Where a player's very first melon appears: the intro_spawn tutorial spot, or the hub if there's none. */
function GetIntroSpawnPoint() {
    const spawn = FindSpawnPoint(INTRO_SPAWN_NAME);
    if (!spawn) {
        Debug(`GetIntroSpawnPoint: no "${INTRO_SPAWN_NAME}" in the map, using the hub spawn`);
        return GetHubSpawnPoint();
    }
    return spawn;
}

/**
 * Where a melon respawns after reaching checkpoint `index` of track
 * `trackId`: the checkpoint_spawn_<trackId>_<index> info_target, facing its
 * yaw — else the nearest "checkpoint_spawn" to the checkpoint trigger `trigger`
 * (a checkpoint gate prefab's). Undefined if the map has neither — the
 * caller falls back to the checkpoint trigger itself.
 * @param {number} trackId @param {number} index @param {any} trigger
 */
function GetCheckpointSpawnPoint(trackId, index, trigger) {
    return FindSpawnPoint(CheckpointSpawnName(trackId, index)) ?? FindSharedSpawnPoint(CHECKPOINT_SPAWN_SHARED_NAME, trigger, CHECKPOINT_SPAWN_SHARED_MAX_DISTANCE);
}

/**
 * Where track `trackId` starts: the start_spawn_<trackId> info_target,
 * facing its yaw — else the nearest "start_spawn" to the start trigger (a
 * start gate prefab's), else the start trigger `trigger` itself (lifted
 * TELEPORT_UP_OFFSET, since its brush may be sunk into the floor).
 * @param {number} trackId @param {any} trigger
 * @returns {SpawnPoint}
 */
function GetStartSpawnPoint(trackId, trigger) {
    const spawn = FindSpawnPoint(StartSpawnName(trackId)) ?? FindSharedSpawnPoint(START_SPAWN_SHARED_NAME, trigger, START_SPAWN_SHARED_MAX_DISTANCE);
    if (spawn) {
        return spawn;
    }
    Debug(`GetStartSpawnPoint: no info_target "${StartSpawnName(trackId)}" or "${START_SPAWN_SHARED_NAME}" nearby, starting at the start trigger itself`);
    return {
        position: Lifted(trigger.GetAbsOrigin(), TELEPORT_UP_OFFSET),
        angles: LevelAngles(trigger.GetAbsAngles().yaw),
    };
}

// The one custom_hud_layout entity every HUD panel lives in (speedometer.xml),
// plus the per-player input capture the modals share.

/** @type {any} */
let speedHud = null;
function GetSpeedHud() {
    if (!speedHud || !speedHud.IsValid()) {
        speedHud = Instance.FindEntityByName(SPEED_HUD_ENTITY_NAME);
        if (!speedHud) {
            Debug(`GetSpeedHud: no entity named "${SPEED_HUD_ENTITY_NAME}" found — add a custom_hud_layout in Hammer`);
        }
    }
    return speedHud;
}

/**
 * The layout has a single input-capture flag per player, but two independent
 * modals want it (hub_modal while standing in the hub, user_menu via USE
 * anywhere) and can be open at the same time. Derived from both instead of
 * each modal blindly setting it — otherwise closing either one (e.g. the
 * user menu while standing in the hub, or leaving the hub with the user menu
 * open) left the other one on screen without a mouse to click it with.
 * @param {any} hud @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 */
function SyncInputCapture(hud, slot, kart) {
    hud.SetInputCaptureEnabled(slot, Boolean(kart.hubModalOpen || kart.userMenuOpen));
}

/**
 * Clears everything the HUD holds for a player slot — every per-player class
 * and dialog variable, and input capture — when its player leaves. The layout
 * keeps them per slot, not per player, so whoever joins next in that slot
 * would otherwise start with the old player's open menu, finish image or
 * moderator button, and in cursor mode until their own kart's HUD caught up.
 * @param {number} slot
 */
function ResetHudForPlayer(slot) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    hud.SetInputCaptureEnabled(slot, false);
    hud.ResetForPlayer(slot);
}

// How a kart's melon looks while it's whole: its paint color plus an outline
// glow in that same color — green (MELON_GLOW_UNPAINTED_COLOR) until it's
// first painted (kart.painted) — which each player can switch
// off for their own melon in the user menu ("GLOW", kart.melonGlow). Every path that shows the
// melon (spawn, respawn after a break, repaint) goes through ShowMelonPaint;
// a break turns the glow off with HideMelonGlow — the melon is hidden then,
// and an outline of it floating at the crash site would give that away.

/** @param {import("../core/kart-registry.js").Kart} kart */
function ShowMelonPaint(kart) {
    kart.melon.SetColor(kart.paintColor);
    if (IsMelonGlowOn(kart)) {
        kart.melon.Glow(kart.painted ? kart.paintColor : MELON_GLOW_UNPAINTED_COLOR);
    } else {
        kart.melon.Unglow();
    }
}

/**
 * Whether this kart's melon glows: on by default, unless its player switched
 * it off in the user menu (see UpdateMelonGlowHud in hud/).
 * @param {import("../core/kart-registry.js").Kart} kart
 */
function IsMelonGlowOn(kart) {
    return MELON_GLOW_ENABLED && kart.melonGlow !== false;
}

/** Switches the glow on/off for this kart's melon. @param {import("../core/kart-registry.js").Kart} kart @param {boolean} on */
function SetMelonGlow(kart, on) {
    kart.melonGlow = on;
    if (!kart.breaking) {
        ShowMelonPaint(kart); // a broken melon gets it back on respawn
    }
}

/**
 * Sets a kart's melon color and remembers it so it survives a break/respawn
 * (BreakMelon hides the melon entirely while broken, without losing track of
 * the color underneath — see ScheduleRespawnAfterBreak). Used by both the
 * melon_paint map trigger and the user menu's color swatches.
 * @param {import("../core/kart-registry.js").Kart} kart @param {{ r: number, g: number, b: number, a: number }} color
 */
function SetKartPaintColor(kart, color) {
    kart.paintColor = color;
    kart.painted = true; // its glow takes this color from now on, see ShowMelonPaint
    if (!kart.breaking) {
        ShowMelonPaint(kart);
    }
}

/** @param {import("../core/kart-registry.js").Kart} kart */
function HideMelonGlow(kart) {
    if (kart.melon.IsValid()) {
        kart.melon.Unglow();
    }
}

// Free look: fly through the map with the player's own pawn instead of
// driving. Toggled per player from the user menu (kart.freeLook, see
// SetFreeLook); off by default. The pawn is NOCLIP anyway (FreezePawn), so
// while this is on HoldPawn just stops pulling it back to its anchor, WASD
// flies it along the view, and the camera shows its eyes (DISABLED mode)
// instead of chasing the melon. The melon waits where it was, frozen
// (UpdateKart skips it; physics motion off), and switching back puts the
// pawn back on its anchor and the chase camera back on the melon.

/** @param {import("../core/kart-registry.js").Kart} kart */
function IsFreeLookOn(kart) {
    return Boolean(kart.freeLook);
}

/**
 * Turns free look on/off for this kart's player. Not while the melon is
 * breaking: the respawn would switch its motion and the chase camera back on
 * mid-flight. Returns whether it's on now.
 * @param {import("../core/kart-registry.js").Kart} kart @param {boolean} on
 */
function SetFreeLook(kart, on) {
    if (on === IsFreeLookOn(kart)) {
        return on;
    }
    if (on && (kart.breaking || !kart.melon.IsValid())) {
        Debug("SetFreeLook: melon is breaking/gone, not switching free look on");
        return false;
    }
    kart.freeLook = on;
    if (kart.melon.IsValid()) {
        kart.melon.Move({ velocity: { x: 0, y: 0, z: 0 }, angularVelocity: { x: 0, y: 0, z: 0 } });
        Instance.EntFireAtTarget({ target: kart.melon, input: on ? "DisableMotion" : "EnableMotion" });
    }
    // Driving starts over from rest — the frozen ticks aren't an impact.
    kart.lastVelocity = undefined;
    kart.prevLastVelocity = undefined;
    kart.settled = false;
    if (!kart.pawn.IsValid()) {
        return on;
    }
    if (on) {
        kart.pawn.Teleport({ position: ChaseCameraFeet(kart), velocity: { x: 0, y: 0, z: 0 } });
        kart.pawn.GetCustomCamera().SetMode(CustomCameraMode.DISABLED);
    } else {
        kart.pawn.Teleport({ position: kart.pawnAnchor, velocity: { x: 0, y: 0, z: 0 } });
        ApplyCameraFollow(kart);
    }
    Debug(`SetFreeLook: slot ${kart.pawn.GetPlayerController()?.GetPlayerSlot()} free look ${on ? "on" : "off"}`);
    return on;
}

/**
 * Roughly where the chase camera sits (behind the melon along the view's
 * yaw), as a pawn origin — so the view doesn't jump when free look starts.
 * @param {import("../core/kart-registry.js").Kart} kart
 */
function ChaseCameraFeet(kart) {
    const melon = kart.melon.GetAbsOrigin();
    const yaw = (kart.pawn.GetEyeAngles().yaw * Math.PI) / 180;
    return {
        x: melon.x - Math.cos(yaw) * CAMERA_DISTANCE,
        y: melon.y - Math.sin(yaw) * CAMERA_DISTANCE,
        z: melon.z + FOLLOW_OFFSET.z + CAMERA_HEIGHT - FREE_LOOK_EYE_HEIGHT,
    };
}

// Spawn flow, in one sentence: a player without a kart gets a new one at the
// spawn point the caller picks (the intro on join); a player who already has
// one keeps it as-is — a lost melon is brought back by the break/respawn
// logic in health/breaking/breaking.js, never here, so the two can't race each other.
// A new player's kart comes only from EnsurePlayerKarts (every tick): once
// they've picked a team it shows the Melon Racer logo for
// INTRO_LOGO_SECONDS, then spawns their melon at the intro. OnPlayerReset
// only re-sets-up a player who already has a kart; EnsurePlayerKarts also
// catches a pawn that lost its chase camera — e.g. the engine finishing a
// team-join spawn after that callback ran.

/** Game time each new player's intro logo ends, by slot — see EnsurePlayerKarts. @type {Map<number, number>} */
const introLogoEnd = new Map();

/**
 * Spawns a fresh melon from the melon_template point_template — shared by
 * CreateKart below and health/breaking/breaking.js's respawn of a destroyed melon.
 * @param {{ x: number, y: number, z: number }} position @param {{ pitch: number, yaw: number, roll: number }} angles
 */
function SpawnMelonAt(position, angles) {
    const template = Instance.FindEntityByName(MELON_TEMPLATE_NAME);
    if (!(template instanceof PointTemplate)) {
        Debug(`SpawnMelonAt: no point_template named "${MELON_TEMPLATE_NAME}" found`);
        return undefined;
    }
    const spawned = template.ForceSpawn(position, angles);
    if (!spawned || spawned.length === 0) {
        Debug(`SpawnMelonAt: ForceSpawn() returned nothing — check the point_template's Template entries in Hammer`);
        return undefined;
    }
    // ForceSpawn keeps the melon's offset from the template's own origin in
    // Hammer, so it lands somewhere near `position`, not on it — put it
    // exactly there.
    const melon = spawned[0];
    melon.Teleport({ position, angles, velocity: { x: 0, y: 0, z: 0 } });
    Debug(`SpawnMelonAt: spawned ${melon.GetClassName()} at ${JSON.stringify(position)}, engine health was ${melon.GetHealth()}/${melon.GetMaxHealth()}`);
    MakeUnbreakableByEngine(melon);
    return melon;
}

/**
 * Gives the melon so much engine health that the engine's own physics
 * damage can never break it — whatever its Hammer health/damage settings
 * are. Breaking is our job: kart.health, see health/.
 * @param {any} melon
 */
function MakeUnbreakableByEngine(melon) {
    melon.SetMaxHealth(MELON_ENGINE_HEALTH);
    melon.SetHealth(MELON_ENGINE_HEALTH);
}

/**
 * Takes the player's own body out of the game: non-solid (NOCLIP — NONE
 * would leave its hitbox solid for the melon to crash into), invisible, and
 * standing still wherever it spawned — the map's player spawns sit away from
 * the tracks, so it's out of the way there. Safe to call repeatedly.
 * @param {any} pawn
 */
function FreezePawn(pawn) {
    pawn.SetMoveType(CSMoveType.NOCLIP);
    pawn.SetColor({ r: 255, g: 255, b: 255, a: 0 });
    pawn.Teleport({ velocity: { x: 0, y: 0, z: 0 } });
}

/**
 * Keeps a frozen pawn at `kart.pawnAnchor`: WASD still flies a NOCLIP pawn
 * around (it's the melon's input too), so without this it would drift off
 * across the map while the player drives. Also takes away any weapon it got
 * back (see below). Called every tick.
 * @param {import("../core/kart-registry.js").Kart} kart
 */
function HoldPawn(kart) {
    // No weapons either: the engine hands the pawn a knife again after the
    // gamemode's DestroyWeapons on spawn, and every knife swing (attack)
    // shoved the melon ~140 u/s forward — a free boost that skipped the
    // attack boost's health cost (ATTACK_BOOST_*).
    if (kart.pawn.GetActiveWeapon()) {
        kart.pawn.DestroyWeapons();
    }
    if (kart.freeLook) {
        return; // flying through the map — see dev/free-look.js
    }
    const anchor = kart.pawnAnchor;
    const at = kart.pawn.GetAbsOrigin();
    if (!anchor || Math.hypot(at.x - anchor.x, at.y - anchor.y, at.z - anchor.z) <= PAWN_DRIFT_TOLERANCE) {
        return;
    }
    kart.pawn.Teleport({ position: anchor, velocity: { x: 0, y: 0, z: 0 } });
}

/**
 * A fresh kart record whose respawn point is where its melon just appeared.
 * @param {any} pawn @param {any} melon @param {import("./spawn-points.js").SpawnPoint} spawnPoint
 * @returns {import("../core/kart-registry.js").Kart}
 */
function NewKartRecord(pawn, melon, spawnPoint) {
    return {
        pawn,
        melon,
        wallJumpCharge: WALL_JUMP_CHARGES,
        health: MELON_MAX_HEALTH,
        lastVelocity: undefined,
        trackId: undefined,
        checkpointIndex: 0,
        checkpointPosition: spawnPoint.position,
        checkpointAngles: spawnPoint.angles,
        lapsCompleted: 0,
        inHub: false,
        racing: false,
        finished: false,
        locked: false,
        breaking: false,
        settled: false,
        teleportGen: 0,
        paintColor: { r: 255, g: 255, b: 255, a: 255 },
        userMenuOpen: false,
        hubModalOpen: false,
        collisionDebug: false,
        freeLook: false,
        predictionLine: false,
        melonGlow: true,
        pawnAnchor: pawn.GetAbsOrigin(),
        lastKnownPosition: undefined,
        lastKnownAngles: undefined,
    };
}

/**
 * New kart for `slot`, its melon spawned at `spawnPoint`. The pawn is
 * frozen (non-solid) first, so the melon can't collide with it.
 * @param {any} pawn @param {number} slot @param {import("./spawn-points.js").SpawnPoint} spawnPoint
 */
function CreateKart(pawn, slot, spawnPoint) {
    FreezePawn(pawn);
    const melon = SpawnMelonAt(spawnPoint.position, spawnPoint.angles);
    if (!melon) {
        return undefined;
    }
    FacePlayerView(pawn, spawnPoint.angles.yaw);
    const kart = NewKartRecord(pawn, melon, spawnPoint);
    ShowMelonPaint(kart);
    karts.set(slot, kart);
    if (moderatorSlot === undefined) {
        SetModeratorSlot(slot);
        Debug(`CreateKart: slot ${slot} is the first player on the map, assigned as moderator`);
    }
    Debug(`CreateKart: slot ${slot} got a new kart`);
    return kart;
}

/**
 * Everything a (re)spawned player pawn needs: its kart — created at
 * `newKartSpawnPoint` only if the player has none yet — plus a frozen,
 * hidden pawn and the chase camera on the melon.
 * @param {any} pawn @param {import("./spawn-points.js").SpawnPoint | undefined} newKartSpawnPoint
 */
function SetUpPlayerKart(pawn, newKartSpawnPoint) {
    const slot = pawn.GetPlayerController()?.GetPlayerSlot();
    if (slot === undefined) {
        Debug("SetUpPlayerKart: pawn has no player controller/slot, aborting");
        return undefined;
    }
    let kart = karts.get(slot);
    if (!kart) {
        if (!newKartSpawnPoint) {
            return undefined; // already logged by the spawn point lookup
        }
        kart = CreateKart(pawn, slot, newKartSpawnPoint);
        if (!kart) {
            return undefined;
        }
    }
    // A new pawn ends free look (the old one was flying, the camera is reset).
    SetFreeLook(kart, false);
    kart.pawn = pawn;
    FreezePawn(pawn);
    kart.pawnAnchor = pawn.GetAbsOrigin();
    if (kart.melon.IsValid()) {
        ApplyCameraFollow(kart); // a lost melon gets the camera once health/breaking/breaking.js respawns it
    }
    return kart;
}

/**
 * Every tick: makes sure each player standing on a team has a melon and is
 * looking through its chase camera. A player without a kart first sees the
 * Melon Racer logo (their own body frozen and hidden meanwhile), then gets a
 * melon at the intro. One whose pawn changed or whose camera got reset is
 * set up again on the pawn they have now — OnPlayerReset alone left a
 * player who had just picked a team stuck in their invisible, frozen body.
 */
function EnsurePlayerKarts() {
    for (const controller of Instance.GetAllPlayerControllers()) {
        if (!controller.IsConnected()) {
            continue;
        }
        const pawn = controller.GetPlayerPawn();
        if (!pawn?.IsValid() || !pawn.IsAlive() || !IsOnPlayingTeam(pawn)) {
            continue; // spectating, picking a team, or dead (waiting to respawn)
        }
        const slot = controller.GetPlayerSlot();
        const kart = karts.get(slot);
        if (!kart) {
            ShowIntroLogoThenSpawn(slot, pawn);
        } else if (kart.pawn !== pawn) {
            Debug(`EnsurePlayerKarts: slot ${slot} got a new pawn, moving the kart over`);
            SetUpPlayerKart(pawn, undefined);
        } else if (kart.melon.IsValid() && !kart.breaking && !kart.freeLook && pawn.GetCustomCamera().GetMode() !== CustomCameraMode.FOLLOW_POSITION) {
            Debug(`EnsurePlayerKarts: slot ${slot} lost the chase camera, re-attaching`);
            SetUpPlayerKart(pawn, undefined);
        }
    }
}

/**
 * A new player's first INTRO_LOGO_SECONDS on a team: the logo, then their
 * melon at the intro. Retried a second later if the melon can't spawn.
 * @param {number} slot @param {any} pawn
 */
function ShowIntroLogoThenSpawn(slot, pawn) {
    const now = Instance.GetGameTime();
    const end = introLogoEnd.get(slot);
    if (end === undefined) {
        Debug(`EnsurePlayerKarts: slot ${slot} joined a team, showing the logo before spawning at the intro`);
        FreezePawn(pawn);
        SetIntroLogoVisible(slot, true);
        introLogoEnd.set(slot, now + INTRO_LOGO_SECONDS);
        return;
    }
    if (now < end) {
        return;
    }
    if (SetUpPlayerKart(pawn, GetIntroSpawnPoint())) {
        SetIntroLogoVisible(slot, false);
        introLogoEnd.delete(slot);
    } else {
        introLogoEnd.set(slot, now + 1);
    }
}

/** @param {number} slot @param {boolean} visible */
function SetIntroLogoVisible(slot, visible) {
    GetSpeedHud()?.SetHasClassForPlayer(slot, "intro_logo", "Hidden", !visible);
}

/**
 * Forgets a disconnecting player's logo state and hides the logo, so a
 * reconnect (a first join again) shows it from the start.
 * @param {number} slot
 */
function ForgetIntroLogo(slot) {
    if (introLogoEnd.delete(slot)) {
        SetIntroLogoVisible(slot, false);
    }
}

/** T (2) or CT (3) — not unassigned (0) or spectator (1). @param {any} pawn */
function IsOnPlayingTeam(pawn) {
    const team = pawn.GetTeamNumber();
    return team === 2 || team === 3;
}

// Pure wall-bounce math — no cs_script import, so it's unit-testable in
// Node (see test/movement/wall-bounce.test.mjs). movement/wall-bounce/wall-bounce.js does the engine side
// (detecting the wall normal via traces, applying the velocity, debug draws)
// and calls into these for the numbers. See "Wall bounce — speed for health"
// in GAMEPLAY.md for the design.

/**
 * Whether a wall the traces found is really the thing the melon just hit:
 * it must be close enough to be touching (within WALL_CONTACT_DISTANCE of
 * the melon's center), and the impact must have actually stopped most of
 * the melon's speed into that wall (WALL_CONTACT_MIN_STOP). Without this, a
 * landing or ceiling bump in a small room bounced the melon off whichever
 * wall happened to lie ahead within trace range.
 * @param {{ x: number, y: number }} origin the melon's center now
 * @param {{ x: number, y: number }} hitPoint where the trace hit the wall
 * @param {{ x: number, y: number }} n the wall's horizontal, unit-length normal
 * @param {{ x: number, y: number }} incoming commanded velocity before the impact
 * @param {{ x: number, y: number }} current the melon's actual velocity now
 */
function IsWallContact(origin, hitPoint, n, incoming, current) {
    const gap = (origin.x - hitPoint.x) * n.x + (origin.y - hitPoint.y) * n.y;
    if (gap > WALL_CONTACT_DISTANCE) {
        return false;
    }
    const intoBefore = -(incoming.x * n.x + incoming.y * n.y);
    if (intoBefore <= 0) {
        return false; // wasn't heading into this wall at all
    }
    const intoAfter = -(current.x * n.x + current.y * n.y);
    return (intoBefore - intoAfter) / intoBefore >= WALL_CONTACT_MIN_STOP;
}

/**
 * 0..1 — how close a wall hit's angle (degrees from the wall normal, 0 =
 * head-on) is to WALL_BOUNCE_OPTIMAL_ANGLE. Shared by the bounce itself and
 * the prediction line, so both always agree.
 * @param {number} angle
 */
function WallAngleFactor(angle) {
    return Math.max(0, 1 - Math.abs(angle - WALL_BOUNCE_OPTIMAL_ANGLE) / WALL_BOUNCE_ANGLE_FALLOFF);
}

/** @param {number} angleFactor */
function GetBounceRating(angleFactor) {
    for (const r of BOUNCE_RATINGS) {
        if (angleFactor >= r.minAngleFactor) {
            return r;
        }
    }
    return BOUNCE_RATINGS[BOUNCE_RATINGS.length - 1];
}

/**
 * How well a jump was timed against a wall hit: 1 for the exact same tick,
 * fading linearly to 0 at WALL_BOUNCE_PERFECT_JUMP_WINDOW seconds either way.
 * @param {number} secondsApart
 */
function JumpTimingFactor(secondsApart) {
    return Math.max(0, 1 - Math.abs(secondsApart) / WALL_BOUNCE_PERFECT_JUMP_WINDOW);
}

/**
 * Whether a jump press counts as wall-bounce timing, or is mashing. Only
 * presses that *did nothing* — no ground jump, no wall jump — count towards
 * mashing: a press within WALL_TIMING_SPAM_LOCKOUT of the last such idle
 * press locks timing credit for that long. A real jump just before doesn't,
 * so "jump, then time the wall" works, and so do chained wall jumps.
 * @param {number} now
 * @param {number | undefined} lastIdlePressTime the last press that did nothing
 * @param {number | undefined} lockedUntil timing credit locked until then
 * @returns {{ counts: boolean, mashing: boolean, lockedUntil: number | undefined }}
 */
function WallTimingPress(now, lastIdlePressTime, lockedUntil) {
    if (lastIdlePressTime !== undefined && now - lastIdlePressTime < WALL_TIMING_SPAM_LOCKOUT) {
        return { counts: false, mashing: true, lockedUntil: now + WALL_TIMING_SPAM_LOCKOUT };
    }
    return { counts: now >= (lockedUntil ?? -Infinity), mashing: false, lockedUntil };
}

/** @param {number} jumpFactor */
function JumpMultiplier(jumpFactor) {
    return 1 + (WALL_BOUNCE_PERFECT_JUMP_MULTIPLIER - 1) * jumpFactor;
}

/**
 * Of last tick's and the tick before's commanded velocity, whichever still
 * heads more squarely into the wall — a collision often plays out over two
 * ticks, so the most recent one may already be half-deflected.
 * @template {{ x: number, y: number }} V
 * @param {V} last @param {V | undefined} prev @param {{ x: number, y: number }} n
 * @returns {V}
 */
function PickIncomingVelocity(last, prev, n) {
    if (!prev) {
        return last;
    }
    /** @param {{ x: number, y: number }} v */
    const intoRatio = (v) => {
        const s = Math.hypot(v.x, v.y);
        return s < 1 ? -Infinity : -(v.x * n.x + v.y * n.y) / s;
    };
    return intoRatio(prev) > intoRatio(last) ? prev : last;
}

/**
 * Reflects a horizontal velocity off a wall and scales it by the angle's
 * rating (BOUNCE_RATINGS[].speedMultiplier) and the jump timing (see
 * WALL_BOUNCE_* in movement/wall-bounce/constants.js).
 * @param {{ x: number, y: number }} v incoming velocity
 * @param {{ x: number, y: number }} n the wall's horizontal, unit-length normal
 * @param {number} jumpFactor 0..1, see JumpTimingFactor
 * @returns {{ velocity: { x: number, y: number }, angle: number, angleFactor: number, speedGain: number } | null}
 *   null if the melon wasn't actually moving into the wall
 */
function ReflectOffWall(v, n, jumpFactor) {
    const speed = Math.hypot(v.x, v.y);
    const into = -(v.x * n.x + v.y * n.y); // speed component heading into the wall
    if (into <= 0 || speed < 1) {
        return null;
    }
    // 0 = head-on, 90 = grazing along the wall.
    const angle = (Math.acos(Math.min(1, into / speed)) * 180) / Math.PI;
    const angleFactor = WallAngleFactor(angle);
    const multiplier = GetBounceRating(angleFactor).speedMultiplier * JumpMultiplier(jumpFactor);
    return {
        velocity: {
            x: (v.x + 2 * into * n.x) * multiplier,
            y: (v.y + 2 * into * n.y) * multiplier,
        },
        angle,
        angleFactor,
        speedGain: Math.max(0, speed * multiplier - speed),
    };
}

/**
 * Health a wall bounce costs: the wall's usual impact + speed-gain damage,
 * reduced by how close to the optimal angle it hit — anything the HUD rates
 * as the best rating (PERFECT) is free, one with no angle bonus pays full
 * price. Jump timing only affects the bounce's speed, never its damage.
 * @param {number} impactSpeed @param {number} speedGain @param {number} angleFactor
 */
function WallBounceDamage(impactSpeed, speedGain, angleFactor) {
    if (GetBounceRating(angleFactor) === BOUNCE_RATINGS[0]) {
        return 0;
    }
    const rawDamage =
        Math.max(0, impactSpeed - WALL_IMPACT_DAMAGE_THRESHOLD) * WALL_IMPACT_DAMAGE_SCALE +
        speedGain * WALL_BOUNCE_DAMAGE_PER_SPEED;
    return rawDamage * (1 - angleFactor);
}

/**
 * Whether a bounce already breaks the melon at impact. Its damage is only
 * charged once the jump window has closed, since a jump just after the hit
 * still counts — but such a late jump can only add speed gain, so only add
 * damage (the angle is final at impact). If what's known at impact is
 * already lethal, nothing can save it, and waiting would only let it break
 * mid-air, after it bounced off the wall.
 * @param {number} health @param {number} impactSpeed @param {number} speedGain @param {number} angleFactor
 */
function IsLethalAtImpact(health, impactSpeed, speedGain, angleFactor) {
    return WallBounceDamage(impactSpeed, speedGain, angleFactor) >= health;
}

/**
 * Vertical velocity right after a wall bounce: at least the kick upward — a
 * fall is cancelled, a melon already rising faster keeps its own speed. Not
 * added on top: chained bounces in a narrow shaft or corridor (less time
 * between them than gravity needs to eat a kick) used to stack upward speed
 * bounce after bounce.
 * @param {number} currentZ vertical velocity physics left this tick
 * @param {number} [upSpeed] the kick — WALL_BOUNCE_UP_SPEED, or a lift zone's
 * @param {number} [angleFactor] the bounce's angle closeness — a PERFECT
 *   rating (BOUNCE_RATINGS[0]) makes the kick PERFECT_BOUNCE_UP_MULTIPLIER stronger
 */
function BounceUpVelocity(currentZ, upSpeed = WALL_BOUNCE_UP_SPEED, angleFactor = 0) {
    const perfect = GetBounceRating(angleFactor) === BOUNCE_RATINGS[0];
    return Math.max(currentZ, upSpeed * (perfect ? PERFECT_BOUNCE_UP_MULTIPLIER : 1));
}

/**
 * `v` (horizontal) scaled up to at least `minSpeed`, direction kept. A zero
 * velocity has no direction and stays as it is.
 * @param {{ x: number, y: number }} v @param {number} minSpeed
 */
function WithMinSpeed(v, minSpeed) {
    const speed = Math.hypot(v.x, v.y);
    if (speed <= 0 || speed >= minSpeed) {
        return v;
    }
    const scale = minSpeed / speed;
    return { x: v.x * scale, y: v.y * scale };
}

// Pure jump rules — ground jump, wall jump and the wall-jump charge — no
// cs_script import, so they're unit-testable in Node (see
// test/movement/jump-logic.test.mjs). movement/jump/jump.js applies them; whether the
// melon is on the ground or at a wall comes from movement/contact/. See the
// JUMP_SPEED / WALL_PROBE_DIRECTIONS comments in movement/jump/constants.js
// for the design.

/**
 * Whether a jump press right now is a ground jump: on the ground, and it's
 * a new ground contact since the last jump — touching down is what resets
 * the jump, no cooldown.
 * @param {{ grounded: boolean, lastGroundedTime?: number, lastJumpTime?: number }} s
 */
function CanGroundJump({ grounded, lastGroundedTime, lastJumpTime }) {
    if (!grounded) {
        return false;
    }
    return lastJumpTime === undefined || (lastGroundedTime !== undefined && lastGroundedTime > lastJumpTime);
}

/**
 * The wall-jump charges (0..WALL_JUMP_CHARGES, fractional while one is
 * refilling) after `dt` seconds of refilling — one after the other,
 * WALL_JUMP_RECHARGE_SECONDS each.
 * @param {number} charges @param {number} dt
 */
function RechargeWallJump(charges, dt) {
    return Math.min(WALL_JUMP_CHARGES, charges + Math.max(0, dt) / WALL_JUMP_RECHARGE_SECONDS);
}

/**
 * The charges left after one wall jump: one whole charge used. The one that
 * was refilling keeps its progress.
 * @param {number} charges
 */
function WallJumpChargeAfter(charges) {
    return Math.max(0, charges - 1);
}

/**
 * Whether a jump press right now is a wall jump.
 * @param {Parameters<typeof WallJumpBlockReason>[0]} s
 */
function CanWallJump(s) {
    return WallJumpBlockReason(s) === null;
}

/**
 * Why a jump press right now is *not* a wall jump, or null if it is one —
 * the collision debug log prints this.
 * @param {{
 *   now: number,
 *   grounded: boolean,
 *   wallContact?: { time: number, normal: { x: number, y: number } },
 *   lastWallJump?: { time: number, normal: { x: number, y: number } },
 *   lastGroundedTime?: number,
 *   charge: number, // wall jumps charged, see WALL_JUMP_CHARGES — at least one whole one needed
 *   cooldown?: number, // WALL_JUMP_COOLDOWN, shorter in a lift zone
 *   window?: number, // WALL_JUMP_WINDOW, longer in a lift zone
 *   bounceTiming?: boolean, // a wall bounce's jump-timing window is still open — this press is its timing, not a wall jump
 * }} s
 */
function WallJumpBlockReason({ now, grounded, wallContact, lastWallJump, lastGroundedTime, charge, cooldown = WALL_JUMP_COOLDOWN, window = WALL_JUMP_WINDOW, bounceTiming = false }) {
    if (grounded) {
        return "on the ground";
    }
    if (bounceTiming) {
        return "counts as the wall bounce's jump timing (WALL_BOUNCE_PERFECT_JUMP_WINDOW still open)";
    }
    if (!wallContact) {
        return "no wall contact yet";
    }
    if (now - wallContact.time > window) {
        return `not at a wall (last there ${(now - wallContact.time).toFixed(3)}s ago > ${window}s)`;
    }
    if (charge < 1) {
        return `no wall jump charged (${charge.toFixed(2)} of ${WALL_JUMP_CHARGES})`; // wait for one to refill
    }
    if (!lastWallJump) {
        return null;
    }
    if (now - lastWallJump.time < cooldown) {
        return `cooldown (${(now - lastWallJump.time).toFixed(2)}s since the last wall jump < ${cooldown}s)`;
    }
    if (lastGroundedTime !== undefined && lastGroundedTime > lastWallJump.time) {
        return null; // touched ground since — any wall is fresh again
    }
    const sameWall =
        wallContact.normal.x * lastWallJump.normal.x + wallContact.normal.y * lastWallJump.normal.y > WALL_JUMP_SAME_WALL_DOT;
    return sameWall ? "same wall as the last wall jump (touch ground or another wall first)" : null;
}

/**
 * Velocity right after a wall jump (always full strength): speed along the
 * wall is kept, the part across it points away from the wall at
 * WALL_JUMP_PUSH_SPEED (or faster, if it already was — e.g. just after a
 * wall bounce), plus WALL_JUMP_UP_SPEED up (the caller keeps a faster
 * upward speed the melon already has, see TryWallJump). A zone can change
 * both (WallRules: a side-view zone's are higher).
 * @param {{ x: number, y: number }} v current horizontal velocity @param {{ x: number, y: number }} n wall normal (horizontal, unit length, pointing away from the wall)
 * @param {number} [pushSpeed] @param {number} [upSpeed]
 */
function WallJumpVelocity(v, n, pushSpeed = WALL_JUMP_PUSH_SPEED, upSpeed = WALL_JUMP_UP_SPEED) {
    const across = v.x * n.x + v.y * n.y;
    const alongX = v.x - across * n.x;
    const alongY = v.y - across * n.y;
    const away = Math.max(across, pushSpeed);
    return { x: alongX + away * n.x, y: alongY + away * n.y, z: upSpeed };
}

/**
 * The angle a wall jump came at the wall, rated like a wall bounce. By the
 * time of the press physics has usually stopped the melon against the wall
 * already, so of the velocities given (this tick's, last tick's commanded,
 * the one before) whichever heads most squarely into the wall counts. None
 * heading into it at all (only along it, or already away): 90°, grazing.
 * incomingSpeed is that velocity's horizontal speed — what a bonus builds on
 * (see WallJumpBoostedVelocity).
 * @param {Array<{ x: number, y: number } | undefined>} velocities
 * @param {{ x: number, y: number }} n wall normal (horizontal, unit length, pointing away from the wall)
 * @returns {{ angle: number, angleFactor: number, rating: typeof BOUNCE_RATINGS[number], incomingSpeed: number }}
 */
function WallJumpAngle(velocities, n) {
    const best = MostHeadOn(velocities, n);
    const bestInto = best ? HeadOnRatio(best, n) : 0; // cos(angle)
    const incomingSpeed = best ? Math.hypot(best.x, best.y) : 0;
    const angle = (Math.acos(Math.min(1, bestInto)) * 180) / Math.PI;
    const angleFactor = WallAngleFactor(angle);
    return { angle, angleFactor, rating: GetBounceRating(angleFactor), incomingSpeed };
}

/**
 * A rated wall jump's horizontal velocity: with a bonus (multiplier > 1) it
 * works like a bounce — the full speed the melon came in with (not what's
 * left after the wall stopped it), times the multiplier, in the plain wall
 * jump's direction (away from the wall, along it). Never slower than the
 * plain jump × multiplier. Without a bonus the plain jump stays as it is.
 * @param {{ x: number, y: number }} jump the plain wall jump's horizontal velocity (WallJumpVelocity)
 * @param {number} incomingSpeed see WallJumpAngle @param {number} multiplier see WallJumpRatingMultipliers
 */
function WallJumpBoostedVelocity(jump, incomingSpeed, multiplier) {
    const plain = Math.hypot(jump.x, jump.y);
    if (multiplier <= 1 || plain <= 0) {
        return { x: jump.x, y: jump.y };
    }
    const scale = (Math.max(plain, incomingSpeed) * multiplier) / plain;
    return { x: jump.x * scale, y: jump.y * scale };
}

/**
 * Speed and upward multipliers a wall jump's rating earns (see
 * WALL_JUMP_RATING_SPEED_MULTIPLIER).
 * @param {typeof BOUNCE_RATINGS[number]} rating
 */
function WallJumpRatingMultipliers(rating) {
    const table = /** @type {Record<string, number>} */ (WALL_JUMP_RATING_SPEED_MULTIPLIER);
    return {
        speed: table[rating.label] ?? 1,
        up: rating === BOUNCE_RATINGS[0] ? WALL_JUMP_PERFECT_UP_MULTIPLIER : 1,
    };
}

/**
 * cos of the angle between a horizontal velocity and the way into a wall
 * (1 = head-on, 0 = along it, below 0 = away from it).
 * @param {{ x: number, y: number }} v @param {{ x: number, y: number }} n wall normal, pointing away from the wall
 */
function HeadOnRatio(v, n) {
    const speed = Math.hypot(v.x, v.y);
    return speed < 1 ? -Infinity : -(v.x * n.x + v.y * n.y) / speed;
}

/**
 * Of the velocities given, the one heading most squarely into the wall —
 * undefined if none heads into it at all.
 * @template {{ x: number, y: number }} V
 * @param {Array<V | undefined>} velocities @param {{ x: number, y: number }} n
 * @returns {V | undefined}
 */
function MostHeadOn(velocities, n) {
    /** @type {V | undefined} */
    let best = undefined;
    for (const v of velocities) {
        if (v && HeadOnRatio(v, n) > 0 && (!best || HeadOnRatio(v, n) > HeadOnRatio(best, n))) {
            best = v;
        }
    }
    return best;
}

/**
 * The approach remembered with a wall contact (see WALL_JUMP_APPROACH_MEMORY):
 * a contact that continues the previous one (that wall, last seen within
 * WALL_JUMP_WINDOW) keeps its approach and start time, unless one of this
 * tick's velocities heads in more squarely; a new contact starts from them.
 * @param {{ time: number, normal: { x: number, y: number }, approach?: { x: number, y: number }, approachTime?: number } | undefined} previous kart.lastWallContact
 * @param {number} now @param {{ x: number, y: number }} n this contact's wall normal
 * @param {Array<{ x: number, y: number } | undefined>} velocities this tick's, last tick's and the one before's
 * @returns {{ approach?: { x: number, y: number }, approachTime: number }}
 */
function WallApproach(previous, now, n, velocities) {
    const continues =
        previous !== undefined &&
        now - previous.time <= WALL_JUMP_WINDOW &&
        previous.normal.x * n.x + previous.normal.y * n.y > WALL_JUMP_SAME_WALL_DOT;
    const kept = continues ? previous.approach : undefined;
    const best = MostHeadOn([kept, ...velocities], n);
    return {
        approach: best ? { x: best.x, y: best.y } : undefined,
        approachTime: continues && previous.approachTime !== undefined ? previous.approachTime : now,
    };
}

/**
 * The remembered approach if it's still recent enough to count.
 * @param {{ approach?: { x: number, y: number }, approachTime?: number }} contact @param {number} now
 */
function FreshApproach(contact, now) {
    return contact.approachTime !== undefined && now - contact.approachTime <= WALL_JUMP_APPROACH_MEMORY ? contact.approach : undefined;
}

// Momentum — repeatedly reaching the top speed raises it (MOMENTUM_* in
// movement/momentum/constants.js). Pure rule, no cs_script import; movement/driving/drive.js
// applies it (test/movement/momentum.test.mjs).

// Reaching the cap exactly: the speed is clamped to it, so allow float noise.
const REACH_TOLERANCE = 0.5; // units/sec

/**
 * @typedef {{
 *   steps: number, // top-speed steps earned this run, 0..MOMENTUM_MAX_STEPS
 *   armed: boolean, // reaching the top speed now would count (it dipped below since the last time)
 *   lastHitTime?: number, // game time the top speed was last reached
 * }} MomentumState
 */

/** @returns {MomentumState} */
function NewMomentum() {
    return { steps: 0, armed: true, lastHitTime: undefined };
}

/**
 * The top speed with `momentum`'s steps (plain MAX_SPEED without any).
 * @param {MomentumState | undefined} momentum
 */
function MomentumMaxSpeed(momentum) {
    return MAX_SPEED * (1 + MOMENTUM_STEP * (momentum?.steps ?? 0));
}

/**
 * This tick's momentum. Below MOMENTUM_MIN_SPEED the run ends (reset).
 * While `boosted` (attack boost on, or the speed cap still raised by a
 * boost) nothing counts: no step, and reaching the top speed during/right
 * after a boost needs a real dip first. Otherwise reaching the top speed
 * after dipping MOMENTUM_REARM_DIP below it is a hit, and a hit within
 * MOMENTUM_HIT_WINDOW of the previous one adds a step.
 * @param {MomentumState | undefined} momentum @param {number} horizSpeed the melon's horizontal speed this tick (after the cap)
 * @param {number} now game time @param {boolean} boosted
 * @returns {MomentumState}
 */
function UpdateMomentum(momentum, horizSpeed, now, boosted) {
    if (!momentum || horizSpeed < MOMENTUM_MIN_SPEED) {
        return NewMomentum();
    }
    if (boosted) {
        return { ...momentum, armed: false };
    }
    const max = MomentumMaxSpeed(momentum);
    if (horizSpeed < max * (1 - MOMENTUM_REARM_DIP)) {
        return momentum.armed ? momentum : { ...momentum, armed: true };
    }
    if (!momentum.armed || horizSpeed < max - REACH_TOLERANCE) {
        return momentum;
    }
    const chained = momentum.lastHitTime !== undefined && now - momentum.lastHitTime <= MOMENTUM_HIT_WINDOW;
    const steps = chained ? Math.min(momentum.steps + 1, MOMENTUM_MAX_STEPS) : momentum.steps;
    return { steps, armed: false, lastHitTime: now };
}

// Particle effects from point_templates, the one way every effect in
// melon_drive is spawned: the break burst (health/breaking/effects.js), the
// PERFECT spark (movement/wall-bounce/wall-bounce.js), the heal sparkle (health/heal/effect.js)
// and the boost trail (fx/boost-trail/boost-trail.js).
// Tested against the fake engine in test/fx/particles.test.mjs.
//
// Two engine quirks every caller would otherwise have to know about:
// - ForceSpawn keeps each templated entity's Hammer offset from its
//   point_template, so without moving them the effect plays wherever the
//   template happens to sit relative to it (see PlaceAll).
// - "Start Active" alone doesn't reliably play an info_particle_system
//   spawned later from a point_template — it's started explicitly
//   (StartParticles).

/**
 * A fresh copy of the named point_template's entities, spawned at
 * `position` — still at their Hammer offsets, not started yet.
 * @param {string} templateName @param {any} position @param {any} [angles]
 * @param {{ warn?: boolean }} [options] warn: report a missing/broken
 *   template with Instance.Msg (always in the console) instead of Debug —
 *   for effects that are part of the map's contract, where silently
 *   spawning nothing is the bug.
 * @returns {any[]} empty if nothing spawned
 */
function SpawnFromTemplate(templateName, position, angles, { warn = false } = {}) {
    const report = warn ? (/** @type {string} */ text) => Instance.Msg(`[melon_drive] ${text}`) : Debug;
    const template = Instance.FindEntityByName(templateName);
    if (!template) {
        report(`SpawnFromTemplate: no point_template named "${templateName}" in the map`);
        return [];
    }
    if (!(template instanceof PointTemplate)) {
        report(`SpawnFromTemplate: "${templateName}" is a ${template.GetClassName()}, not a point_template`);
        return [];
    }
    const spawned = template.ForceSpawn(position, angles) ?? [];
    if (spawned.length === 0) {
        report(`SpawnFromTemplate: ForceSpawn of "${templateName}" returned nothing — check its Template01.. entries in Hammer`);
    }
    return spawned;
}

/** @param {any} entity */
function IsParticleSystem(entity) {
    return entity.GetClassName() === "info_particle_system";
}

/** Moves every entity exactly onto `position` (undoing ForceSpawn's Hammer offsets). @param {any[]} entities @param {any} position */
function PlaceAll(entities, position) {
    for (const entity of entities) {
        entity.Teleport({ position });
    }
}

/** Starts every info_particle_system among `entities`. @param {any[]} entities */
function StartParticles(entities) {
    for (const entity of entities) {
        if (IsParticleSystem(entity)) {
            Instance.EntFireAtTarget({ target: entity, input: "Start" });
        }
    }
}

/**
 * Stops every info_particle_system among `entities` that's still around:
 * no new particles, the ones already out play to the end of their lifetime.
 * @param {any[]} entities
 */
function StopParticles(entities) {
    for (const entity of entities) {
        if (entity.IsValid() && IsParticleSystem(entity)) {
            Instance.EntFireAtTarget({ target: entity, input: "Stop" });
        }
    }
}

/**
 * Removes `entities` after `seconds` (those still around — a parented one
 * goes with its parent if that's removed first). Removing an
 * info_particle_system ends its particles, so `seconds` must cover the
 * effect's own duration.
 * @param {any[]} entities @param {number} seconds
 */
function RemoveAfter(entities, seconds) {
    Instance.Delay(seconds).then(() => {
        for (const entity of entities) {
            if (entity.IsValid()) {
                entity.Remove();
            }
        }
    });
}

/**
 * The whole short-lived effect in one call: a fresh copy of the template,
 * placed exactly at `position`, optionally riding along on `parent`,
 * started, and removed after `lifetime` seconds.
 * @param {string} templateName @param {any} position
 * @param {{ lifetime: number, parent?: any, angles?: any, warn?: boolean }} options
 * @returns {any[]} the spawned entities (empty if nothing spawned)
 */
function PlayParticleTemplate(templateName, position, { lifetime, parent, angles, warn }) {
    const spawned = SpawnFromTemplate(templateName, position, angles, { warn });
    PlaceAll(spawned, position);
    if (parent) {
        for (const entity of spawned) {
            entity.SetParent(parent);
        }
    }
    StartParticles(spawned);
    RemoveAfter(spawned, lifetime);
    return spawned;
}

// Pure health-bar math — no cs_script import, so it's unit-testable in
// Node (see test/health/health.test.mjs). hud/ turns the result into HUD classes.

/**
 * What the segmented health bar should show for a given health value.
 * @param {number} health
 * @returns {{ fraction: number, filledSegments: number, low: boolean, critical: boolean }}
 */
function HealthBarState(health) {
    const fraction = Math.max(0, Math.min(1, health / MELON_MAX_HEALTH));
    return {
        fraction,
        // ceil, not round: the melon only breaks at health <= 0, so any health
        // left must still show at least one segment — round() emptied the bar
        // while up to half a segment's worth of health remained.
        // (minus a hair: 70 / 30 per segment leaves float dust like 29.0000000004,
        // which ceil() turned into a still-full segment)
        filledSegments: Math.max(0, Math.ceil(fraction * HEALTH_BAR_SEGMENTS - 1e-9)),
        low: fraction <= HEALTH_LOW_FRACTION,
        critical: fraction <= HEALTH_CRITICAL_FRACTION,
    };
}

/**
 * Whether an impact is the melon landing on flat, level ground: the floor
 * under it is at least FLAT_LANDING_MIN_NORMAL_Z level and the impact
 * (the velocity change physics forced) points mostly upward.
 * @param {{ x: number, y: number, z: number }} impactDelta
 * @param {number | undefined} floorNormalZ this tick's floor trace, undefined if it hit nothing
 */
function IsFlatLanding(impactDelta, floorNormalZ) {
    if (floorNormalZ === undefined || floorNormalZ < FLAT_LANDING_MIN_NORMAL_Z) {
        return false;
    }
    const impactSpeed = Math.hypot(impactDelta.x, impactDelta.y, impactDelta.z);
    return impactSpeed > 0 && impactDelta.z / impactSpeed >= FLAT_LANDING_MIN_VERTICAL_SHARE;
}

/**
 * Health lost from a landing/crash (not a wall bounce): IMPACT_DAMAGE_* above
 * the threshold, times FLAT_LANDING_DAMAGE_MULTIPLIER for a flat landing.
 * @param {{ x: number, y: number, z: number }} impactDelta
 * @param {number | undefined} floorNormalZ
 * @returns {{ damage: number, flatLanding: boolean }}
 */
function ImpactDamage(impactDelta, floorNormalZ) {
    const impactSpeed = Math.hypot(impactDelta.x, impactDelta.y, impactDelta.z);
    const flatLanding = IsFlatLanding(impactDelta, floorNormalZ);
    const base = Math.max(0, impactSpeed - IMPACT_DAMAGE_THRESHOLD) * IMPACT_DAMAGE_SCALE;
    return { damage: flatLanding ? base * FLAT_LANDING_DAMAGE_MULTIPLIER : base, flatLanding };
}

// Healing math (HealedHealth, HealZoneRate): health/heal/logic.js.

// Jump pads (JUMP_PAD_* in zones/jump-pad/constants.js). Pure rules, no cs_script
// import; zones/jump-pad/jump-pad.js applies them (test/zones/jump-pad.test.mjs).

/** @typedef {{ up: number, forward: number }} JumpPad upward launch speed, horizontal speed added (units/sec) */
/** @typedef {{ launchTime: number, landedTime?: number }} PadFlight a launch whose damage protection is still on */

/**
 * A pad's launch, from its trigger name (see JUMP_PAD_NAME_PATTERN), else
 * the defaults. @param {string} triggerName @returns {JumpPad}
 */
function JumpPadFromName(triggerName) {
    const match = JUMP_PAD_NAME_PATTERN.exec(triggerName.trim());
    return {
        up: match ? Number(match[1]) : JUMP_PAD_UP_SPEED,
        forward: match?.[2] !== undefined ? Number(match[2]) : JUMP_PAD_FORWARD_BOOST,
    };
}

/**
 * Whether the melon on a pad launches this tick: a jump press now, or one
 * made at most JUMP_PAD_BUFFER ago that hasn't launched it yet — and not
 * again within JUMP_PAD_COOLDOWN of the last launch.
 * @param {number} now @param {boolean} jumpPressed this tick
 * @param {number | undefined} lastPressTime last jump press @param {number | undefined} lastLaunchTime last pad launch
 */
function ShouldPadLaunch(now, jumpPressed, lastPressTime, lastLaunchTime) {
    if (lastLaunchTime !== undefined && now - lastLaunchTime < JUMP_PAD_COOLDOWN) {
        return false;
    }
    if (jumpPressed) {
        return true;
    }
    return (
        lastPressTime !== undefined &&
        now - lastPressTime <= JUMP_PAD_BUFFER &&
        (lastLaunchTime === undefined || lastPressTime > lastLaunchTime)
    );
}

/**
 * The velocity right after a launch: `pad.up` upward (a fall is cancelled; a
 * melon already rising faster keeps that), and `pad.forward` more horizontal
 * speed along where it's going — along `lookDir` if it's barely moving.
 * @param {{ x: number, y: number, z: number }} v @param {{ x: number, y: number }} lookDir unit vector
 * @param {JumpPad} pad
 */
function PadLaunchVelocity(v, lookDir, pad) {
    const speed = Math.hypot(v.x, v.y);
    const dir = speed > JUMP_PAD_MIN_DIRECTION_SPEED ? { x: v.x / speed, y: v.y / speed } : lookDir;
    const launched = speed + pad.forward;
    return { x: dir.x * launched, y: dir.y * launched, z: Math.max(v.z, pad.up) };
}

/**
 * The launch's damage protection this tick, or undefined once it's over:
 * JUMP_PAD_LANDING_GRACE after the first ground contact after taking off
 * (contact within GROUND_LIFTOFF_TIME of the launch is the pad itself), or
 * JUMP_PAD_MAX_PROTECTED_SECONDS after the launch at the latest.
 * @param {PadFlight | undefined} flight @param {number} now @param {number | undefined} lastGroundedTime
 * @returns {PadFlight | undefined}
 */
function PadFlightAfter(flight, now, lastGroundedTime) {
    if (!flight || now - flight.launchTime > JUMP_PAD_MAX_PROTECTED_SECONDS) {
        return undefined;
    }
    const landedTime =
        flight.landedTime ??
        (lastGroundedTime !== undefined && lastGroundedTime > flight.launchTime + GROUND_LIFTOFF_TIME ? lastGroundedTime : undefined);
    if (landedTime !== undefined && now - landedTime > JUMP_PAD_LANDING_GRACE) {
        return undefined;
    }
    return landedTime === flight.landedTime ? flight : { ...flight, landedTime };
}

// Engine side of jump pads (JUMP_PAD_*): launching a melon off the pad it's
// on when jump is pressed, and the damage protection that follows. The rules
// are in ../logic/jump-pad.js; which pad the melon is on, in zones.js.

/**
 * Per tick, before any damage: ends the launch's damage protection once the
 * melon has landed (see PadFlightAfter).
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} now
 */
function UpdatePadFlight(kart, now) {
    kart.padFlight = PadFlightAfter(kart.padFlight, now, kart.lastGroundedTime);
}

/**
 * Whether the melon takes no damage right now: on a jump pad, or flying off
 * one (until shortly after landing).
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function IsPadProtected(kart) {
    return kart.padFlight !== undefined || CurrentJumpPad(kart) !== undefined;
}

/**
 * On a jump pad with a (just) pressed jump: launches the melon — `v` (the
 * velocity UpdateKart is about to command) is replaced in place, after the
 * normal jump handling, so the launch wins over a ground/wall jump.
 * @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart @param {number} now
 * @param {boolean} jumpPressed @param {{ x: number, y: number, z: number }} v
 * @param {{ x: number, y: number }} lookDir
 * @returns {boolean} whether it launched
 */
function TryPadLaunch(slot, kart, now, jumpPressed, v, lookDir) {
    const pad = CurrentJumpPad(kart);
    if (!pad || !ShouldPadLaunch(now, jumpPressed, kart.lastJumpPressTime, kart.lastPadLaunchTime)) {
        return false;
    }
    const launched = PadLaunchVelocity(v, lookDir, pad);
    v.x = launched.x;
    v.y = launched.y;
    v.z = launched.z;
    kart.lastPadLaunchTime = now;
    // Counts as a jump: the pad still pushing up for a tick isn't ground
    // contact (GROUND_LIFTOFF_TIME), and the next ground jump needs a landing.
    kart.lastJumpTime = now;
    kart.padFlight = { launchTime: now };
    // Faster than the top speed, like a wall-bounce boost — decays at BOOST_DECAY.
    kart.speedCap = Math.max(kart.speedCap ?? MomentumMaxSpeed(kart.momentum), Math.hypot(v.x, v.y));
    Debug(`jump pad: slot ${slot} launched (${launched.z.toFixed(0)} u/s up, ${Math.hypot(v.x, v.y).toFixed(0)} u/s horizontal)`);
    return true;
}

// Health loss from hard impacts (landings, crashes) — see IMPACT_DAMAGE_*.

/**
 * @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart
 * @param {{ x: number, y: number, z: number }} impactDelta the velocity change physics forced this tick
 */
function ApplyImpactDamage(slot, kart, impactDelta) {
    const impactSpeed = Math.hypot(impactDelta.x, impactDelta.y, impactDelta.z);
    const { damage, flatLanding } = ImpactDamage(impactDelta, kart.floorNormalZ);
    DamageKart(slot, kart, damage, `impact ${impactSpeed.toFixed(0)} u/s${flatLanding ? " (flat landing)" : ""}`);
}

/**
 * Impact and wall-bounce damage. None on a jump pad or flying off one (see
 * IsPadProtected) — the attack boost's cost and melon_break triggers still apply.
 * @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart @param {number} damage @param {string} reason
 */
function DamageKart(slot, kart, damage, reason) {
    if (IsPadProtected(kart)) {
        Debug(`slot ${slot}: ${reason} -> no damage (jump pad)`);
        return;
    }
    kart.health -= damage;
    Debug(`slot ${slot}: ${reason} -> ${damage.toFixed(0)} dmg, health ${kart.health.toFixed(0)}/${MELON_MAX_HEALTH}`);
}

// Pure healing math — no cs_script import, so it's unit-testable in Node
// (see test/health/heal.test.mjs). zone.js applies it to karts.

/**
 * Health after healing for dt seconds at rate health/second, never above
 * MELON_MAX_HEALTH (and never lowering a value that's already above it).
 * HEAL_ZONE_FULL_RATE heals to full at once, whatever dt is.
 * @param {number} health @param {number} rate @param {number} dt
 */
function HealedHealth(health, rate, dt) {
    if (health >= MELON_MAX_HEALTH) {
        return health;
    }
    if (rate === HEAL_ZONE_FULL_RATE) {
        return MELON_MAX_HEALTH; // Infinity * a 0 dt would be NaN
    }
    return Math.min(MELON_MAX_HEALTH, health + Math.max(0, rate) * Math.max(0, dt));
}

/**
 * Heal rate (health/second) of a heal trigger: HEAL_ZONE_FULL_RATE for
 * HEAL_ZONE_FULL_NAME, parsed from a "heal_zone_<rate>" name, else
 * HEAL_ZONE_RATE.
 * @param {string} triggerName
 */
function HealZoneRate(triggerName) {
    const name = triggerName.trim(); // Hammer keeps stray trailing spaces
    if (name === HEAL_ZONE_FULL_NAME) {
        return HEAL_ZONE_FULL_RATE;
    }
    const match = HEAL_ZONE_NAME_PATTERN.exec(name);
    return match ? Number(match[1]) : HEAL_ZONE_RATE;
}

// Healing a kart's melon: heal zones (heal_enter / heal_leave, registered in
// ../../zones/inputs.js — which zones it's in: ../../zones/registry.js) and the full
// refill on every respawn/race-flow teleport.

/** Health per second the melon heals right now (0 outside heal zones). @param {import("../../core/kart-registry.js").Kart} kart */
function CurrentHealRate(kart) {
    return StrongestZone(kart, "healZones") ?? 0;
}

/**
 * Heals the melon for this tick at the fastest rate of the zones it's in.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} dt
 */
function ApplyHealing(kart, dt) {
    const rate = CurrentHealRate(kart);
    if (rate > 0) {
        kart.health = HealedHealth(kart.health, rate, dt);
    }
}

/**
 * Back to full health — respawns after a break, checkpoint/race-flow
 * teleports. A melon arriving whole also gets all its wall jumps charged
 * (the HUD jump icons), like a freshly spawned one.
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function RestoreFullHealth(kart) {
    kart.health = MELON_MAX_HEALTH;
    kart.wallJumpCharge = WALL_JUMP_CHARGES;
}

// The heal effect: particle_health_template played on the melon as it
// enters a heal zone (hooked up in ../../zones/inputs.js).

/**
 * Plays a fresh copy of the heal effect on the melon, parented so it rides
 * along while the melon rolls through the zone. Not for melons that can't
 * heal right now (broken, or locked by the race flow — see ApplyHealing's
 * caller).
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function PlayHealEffect(kart) {
    if (kart.breaking || kart.locked || !kart.melon.IsValid()) {
        return;
    }
    PlayParticleTemplate(HEAL_PARTICLE_TEMPLATE_NAME, kart.melon.GetAbsOrigin(), { lifetime: HEAL_PARTICLE_LIFETIME, parent: kart.melon });
}

// Everything that heals a melon, in one place: constants.js (HEAL_ZONE_* and
// the trigger names), logic.js (pure rules, unit-tested in test/health/heal.test.mjs)
// zone.js (applying them to karts) and effect.js (the particle_health_template
// played on entering a zone). The heal_enter/heal_leave inputs are
// registered with the other zones in ../../zones/inputs.js; the constants are
// also re-exported by ../constants/index.js. Import from here.

// What a break leaves at the crash site: the two break templates'
// particles and any physics pieces in them, placed on the crash site, flung
// out, and cleaned up after BREAK_EFFECT_LIFETIME.

/**
 * Converts a direction vector into the pitch/yaw/roll a particle template
 * should spawn with to visually point along it (Source's angle convention:
 * yaw rotates around Z, pitch is negative-up/positive-down from horizontal).
 * @param {{ x: number, y: number, z: number }} dir @param {number} length
 */
function DirectionToAngles(dir, length) {
    const yaw = (Math.atan2(dir.y, dir.x) * 180) / Math.PI;
    const pitch = -(Math.asin(Math.min(1, Math.max(-1, dir.z / length))) * 180) / Math.PI;
    return { pitch, yaw, roll: 0 };
}

// Every break's spawned effect entities, kept so they can stay at the crash
// site for a long time (BREAK_EFFECT_LIFETIME) and still get cleaned up —
// see PruneBreakEffects.
/** @type {Array<{ spawnTime: number, entities: any[] }>} */
let breakEffects = [];

/** Removes break effects that are too old, or too many. */
function CleanUpBreakEffects() {
    const { expired, kept } = PruneBreakEffects(breakEffects, Instance.GetGameTime());
    breakEffects = kept;
    for (const effect of expired) {
        for (const entity of effect.entities) {
            if (entity.IsValid()) {
                entity.Remove();
            }
        }
    }
}

/**
 * Spawns one break template at the crash site and starts its particles.
 * Warns in the console (even with DEBUG off) if it's missing — silently
 * spawning nothing on a break is the bug.
 * @param {string} templateName @param {any} position @param {any} angles
 * @returns {any[]} the spawned entities (empty if nothing spawned)
 */
function SpawnBreakTemplate(templateName, position, angles) {
    const spawned = SpawnFromTemplate(templateName, position, angles, { warn: true });
    PlaceAtCrashSite(spawned, position);
    StartParticles(spawned);
    if (spawned.length > 0) {
        Debug(`SpawnBreakTemplate: "${templateName}" spawned ${spawned.map((e) => e.GetClassName()).join(", ")} at ${JSON.stringify(position)}`);
    }
    return spawned;
}

/**
 * ForceSpawn keeps each templated entity's Hammer offset from its
 * point_template (see fx/particles.js; same as melon_template, SpawnMelonAt) — in the map
 * the break particles sit ~200 units next to their templates, so they
 * played that far away from the crash site, somewhere different on every
 * break (the offset is rotated by the impact direction). Put particle
 * systems exactly on the crash site, and center the pieces' group on it,
 * keeping their layout relative to each other.
 * @param {any[]} entities @param {any} position
 */
function PlaceAtCrashSite(entities, position) {
    const pieces = entities.filter((e) => e.GetClassName().startsWith("prop_physics"));
    const placed = RecenterOnto(pieces.map((p) => p.GetAbsOrigin()), position);
    pieces.forEach((piece, i) => piece.Teleport({ position: placed[i] }));
    PlaceAll(entities.filter((e) => !pieces.includes(e)), position);
}

/**
 * Flings any physics props a break template spawned (e.g. the melon model's
 * own break pieces, models/cs_italy/italy_food_melon/italy_food_melon/
 * piece*.vmdl, added to melon_break_chunks_template in Hammer) outward from
 * the crash site, tinted in the melon's paint color. They then lie there as
 * ordinary physics props until BREAK_EFFECT_LIFETIME removes them — unlike
 * the chunks particle, which is only sprite flecks that fade within moments.
 * @param {any[]} entities @param {any} position @param {{ r: number, g: number, b: number, a: number }} color
 */
function LaunchBreakPieces(entities, position, color) {
    for (const piece of entities) {
        if (!piece.GetClassName().startsWith("prop_physics")) {
            continue;
        }
        piece.SetColor(color);
        const spin = () => (Math.random() * 2 - 1) * BREAK_PIECE_SPIN;
        piece.Teleport({
            velocity: BreakPieceVelocity(position, piece.GetAbsOrigin(), Math.random() * Math.PI * 2),
            angularVelocity: { x: spin(), y: spin(), z: spin() },
        });
    }
}

/**
 * Spawns both break effects at the crash site — the main burst plus the
 * chunks template layered on top of it. Independent of each other (either
 * can be missing from Hammer without the other failing).
 * @param {any} position @param {any} angles @param {{ r: number, g: number, b: number, a: number }} color the melon's paint, for any pieces
 * @returns {boolean} whether at least one of them actually spawned — see
 * BreakMelon's fallback tint for why callers need to know this, not just
 * fire-and-forget.
 */
function SpawnBreakParticles(position, angles, color) {
    const entities = [
        ...SpawnBreakTemplate(BREAK_PARTICLE_TEMPLATE_NAME, position, angles),
        ...SpawnBreakTemplate(BREAK_CHUNKS_PARTICLE_TEMPLATE_NAME, position, angles),
    ];
    LaunchBreakPieces(entities, position, color);
    if (entities.length === 0) {
        return false;
    }
    // Deliberately not removed on respawn — the chunks should keep lying at
    // the crash site long after the melon is back on the track.
    breakEffects.push({ spawnTime: Instance.GetGameTime(), entities });
    CleanUpBreakEffects();
    Instance.Delay(BREAK_EFFECT_LIFETIME).then(CleanUpBreakEffects);
    return true;
}

// Moving a kart's melon on purpose: checkpoint respawn and generic teleports.

/**
 * Teleports a kart's melon back to its last checkpoint and resets it to a
 * fresh, undamaged state — the shared final step of both the automatic
 * post-break respawn and the manual "Respawn at last checkpoint" user menu
 * button.
 * @param {import("../core/kart-registry.js").Kart} kart
 */
function RespawnKartAtCheckpoint(kart) {
    kart.melon.Teleport({
        position: kart.checkpointPosition,
        angles: kart.checkpointAngles,
        velocity: { x: 0, y: 0, z: 0 },
    });
    FacePlayerView(kart.pawn, kart.checkpointAngles.yaw);
    kart.lastWallContact = undefined; // that wall is somewhere else now
    RestoreFullHealth(kart);
    // Cleared, not measured against zero: this is our own intentional
    // velocity reset, not a physical impact to react to.
    kart.lastVelocity = undefined;
    kart.settled = false;
    kart.speedCap = undefined;
    kart.pendingBounce = undefined;
    // Zones are kept: a respawn inside the zone the melon broke in never sends
    // a new OnStartTouch, and leaving one by teleport still sends OnEndTouch.
}

/**
 * Moves a kart's melon somewhere else mid-drive (a generic teleporter, see
 * the melon_teleport input) without touching its health, respawn point or
 * checkpoint progress (a checkpoint_ teleporter sets the respawn point
 * itself, see the melon_teleport input). The tracking state that compares against last tick
 * is cleared, so the jump in position/velocity isn't read as a hard impact
 * (damage) or a wall hit. speedCap is kept, so a wall-bounce boost carried
 * through the teleport isn't clamped away.
 * @param {import("../core/kart-registry.js").Kart} kart @param {any} position @param {any} angles @param {{ x: number, y: number, z: number }} velocity
 */
function TeleportKartTo(kart, position, angles, velocity) {
    kart.melon.Teleport({ position, angles, velocity, angularVelocity: { x: 0, y: 0, z: 0 } });
    FacePlayerView(kart.pawn, angles.yaw);
    kart.lastWallContact = undefined; // that wall is somewhere else now
    kart.lastVelocity = undefined;
    kart.prevLastVelocity = undefined;
    kart.prevOrigin = undefined;
    kart.settled = false;
    kart.pendingBounce = undefined;
    // Zones are kept: a respawn inside the zone the melon broke in never sends
    // a new OnStartTouch, and leaving one by teleport still sends OnEndTouch.
}

// A melon breaking: BreakMelon (health ran out) / HandleMelonLost (the
// entity vanished), the delay at the crash site, and the respawn after it.

/**
 * Common tail end of every break, whether it was caught by our own
 * kart.health tracking (BreakMelon) or discovered after the fact because the
 * melon vanished on its own (HandleMelonLost): wait out BREAK_RESPAWN_DELAY,
 * then bring the kart back — reusing the same (hidden) melon where possible,
 * or spawning a brand new one at the checkpoint if the original is actually
 * gone.
 * @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart
 */
function ScheduleRespawnAfterBreak(slot, kart) {
    // Which race-flow teleport this break happened after — see
    // Kart.teleportGen. Compared against, rather than checking
    // kart.racing/locked: those also describe perfectly ordinary states
    // (free-roaming the hub, parked after finishing) in which a broken melon
    // still needs to go back to its checkpoint.
    const teleportGen = kart.teleportGen;
    Instance.Delay(BREAK_RESPAWN_DELAY).then(() => {
        kart.breaking = false;
        kart.breakTime = undefined;
        if (!kart.pawn.IsValid() || karts.get(slot) !== kart) {
            return; // player disconnected, or a fresh kart already replaced this one
        }
        if (!kart.melon.IsValid()) {
            // The melon wasn't just hidden by us — it's genuinely gone (the
            // engine's own physics broke the prop_physics_multiplayer for
            // real on a hard enough hit, see HandleMelonLost) — spawn a fresh
            // one instead of teleporting an entity that no longer exists.
            // Checked before the teleportGen case below, and regardless of
            // racing/locked: otherwise a melon lost outside a heat would never
            // come back, and Think would re-run HandleMelonLost on it forever.
            // checkpointPosition is correct even if the race flow moved on
            // meanwhile — BeginHeat/ReturnAllToHub set it to their own
            // (skipped, since the melon was dead) teleport target.
            RespawnDestroyedMelon(slot, kart);
            return;
        }
        SetMelonMotion(kart.melon, true); // before any respawn teleport below
        ShowMelonPaint(kart);
        // Back from the pulled-out break camera (ApplyBreakCameraZoom) to the
        // player's normal chase offset.
        ApplyCameraFollow(kart);
        if (kart.teleportGen !== teleportGen) {
            // The race flow moved this kart while it was mid-break (next
            // heat's BeginHeat, or ReturnAllToHub via finish/moderator
            // abort/the player's own "Return to hub" button). That
            // already-current teleport wins — don't stomp it a second later
            // with a now-stale checkpoint.
            RestoreFullHealth(kart);
            return;
        }
        RespawnKartAtCheckpoint(kart);
    });
}

/**
 * Switches a melon's physics motion off for the break and back on for the
 * respawn (prop_physics' DisableMotion/EnableMotion inputs — it has no input
 * to make it non-solid). While broken the hidden melon stays at the crash
 * site, and the break's own prop_physics pieces spawn right inside it: with
 * motion on they shoved it around every physics step, between the ticks that
 * hold it still, and the chase camera following it shook along. With motion
 * off it doesn't budge — the pieces bounce off it instead.
 * @param {any} melon @param {boolean} enabled
 */
function SetMelonMotion(melon, enabled) {
    Instance.EntFireAtTarget({ target: melon, input: enabled ? "EnableMotion" : "DisableMotion" });
}

/** @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart */
function RespawnDestroyedMelon(slot, kart) {
    const melon = SpawnMelonAt(kart.checkpointPosition, kart.checkpointAngles);
    if (!melon) {
        // kart.breaking is already cleared, so Think's invalid-melon check
        // runs HandleMelonLost again next tick — that's the retry.
        Debug(`slot ${slot}: could not respawn a melon after it was destroyed, will keep retrying`);
        return;
    }
    kart.melon = melon;
    FacePlayerView(kart.pawn, kart.checkpointAngles.yaw);
    ShowMelonPaint(kart);
    RestoreFullHealth(kart);
    kart.lastVelocity = undefined;
    kart.settled = false;
    kart.speedCap = undefined;
    kart.pendingBounce = undefined;
    LeaveZones(kart); // a new melon entity — the old one's zones never send heal_leave/lift_leave
    ApplyCameraFollow(kart);
}

/** @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart @param {{ x: number, y: number, z: number }} impactDir @param {number} impactSpeed */
function BreakMelon(slot, kart, impactDir, impactSpeed) {
    if (kart.breaking) {
        return; // already broken and counting down to its respawn
    }
    kart.breaking = true;
    kart.breakTime = Instance.GetGameTime();
    const breakPosition = kart.melon.GetAbsOrigin();
    // Oriented along the velocity change the impact caused, not the melon's
    // own orientation — while rolling, that's an essentially random tumble
    // unrelated to which way it just got hit.
    const breakAngles = DirectionToAngles(impactDir, impactSpeed);
    Debug(`slot ${slot}: melon broke at ${JSON.stringify(breakPosition)} — respawning at checkpoint ${kart.checkpointIndex} in ${BREAK_RESPAWN_DELAY}s`);

    kart.melon.Move({ velocity: { x: 0, y: 0, z: 0 } });
    SetMelonMotion(kart.melon, false); // so the break pieces below can't shove it (and the camera) around
    kart.lastVelocity = undefined;
    kart.settled = false;
    // Hidden entirely when the break particle actually spawned — it reads as
    // the melon shredding apart, which a dark husk just sitting there in one
    // piece doesn't. But without a "melon_break_template" placed in Hammer
    // there's nothing else marking the crash site: the melon would just
    // vanish and silently reappear at the checkpoint BREAK_RESPAWN_DELAY
    // later, which looks like the camera instantly cut to the respawn. Tint
    // it dark and leave it visible instead, so there's always something at
    // the crash site to see while it waits out the respawn delay.
    // kart.paintColor itself is untouched either way, restored in
    // ScheduleRespawnAfterBreak.
    const particlesSpawned = SpawnBreakParticles(breakPosition, breakAngles, kart.paintColor);
    kart.melon.SetColor(particlesSpawned ? { r: 255, g: 255, b: 255, a: 0 } : BREAK_TINT_FALLBACK);
    HideMelonGlow(kart);

    ScheduleRespawnAfterBreak(slot, kart);
}

/**
 * Recovery path for a melon that broke for real instead of just being hidden
 * by BreakMelon above — the engine's own physics can destroy a
 * prop_physics_multiplayer outright on a hard enough impact, sometimes
 * before our own kart.health tracking even gets a chance to react. Without
 * this, that kart would silently lose its melon with no break particle, no
 * delay, and (since nothing else re-creates it while the player's pawn stays
 * alive — see gamemode/index.js) no way back at all. Runs the same
 * particle + delay + checkpoint-respawn sequence as a script-detected break,
 * using the last position/angles Think() saw the melon at (it's already gone
 * by the time this runs, so it can't be asked directly).
 * @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart
 */
function HandleMelonLost(slot, kart) {
    if (kart.breaking) {
        return; // already mid-break/respawn over this same loss
    }
    kart.breaking = true;
    kart.health = 0;
    const breakPosition = kart.lastKnownPosition ?? kart.checkpointPosition;
    const breakAngles = kart.lastKnownAngles ?? kart.checkpointAngles;
    Debug(`slot ${slot}: melon was destroyed at ${JSON.stringify(breakPosition)} — respawning at checkpoint ${kart.checkpointIndex} in ${BREAK_RESPAWN_DELAY}s`);
    SpawnBreakParticles(breakPosition, breakAngles, kart.paintColor);
    ScheduleRespawnAfterBreak(slot, kart);
}

// Engine side of the wall bounce: finding the wall's normal on impact
// (traces + IsWallContact), computing the bounce, DEBUG logging, and
// charging its damage once the jump-timing window closes. The math is in
// ../logic/wall-bounce.js.

/**
 * Whether the impact this tick was against a wall, and if so that wall's
 * (horizontal, unit-length) normal — see the trace order inside. Floors/
 * ceilings (mostly vertical normal) and other physics props (other karts'
 * melons, loose melons in the map) don't count — only walls bounce.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {{ x: number, y: number, z: number }} impactDelta
 * @returns {{ x: number, y: number, method: string, hitPoint?: any } | null}
 */
function DetectWallNormal(kart, impactDelta) {
    const v = kart.lastVelocity;
    if (!v) {
        return null;
    }
    const horizSpeed = Math.hypot(v.x, v.y);
    if (horizSpeed < 1) {
        return null; // purely vertical motion — a landing, never a wall
    }
    const dir = { x: v.x / horizSpeed, y: v.y / horizSpeed };
    const ignoreEntity = [kart.melon, kart.pawn];

    // 1st choice: a thin ray from where the melon was *last* tick (before
    // contact) along its incoming direction — gives the wall's real face
    // normal, independent of how vphysics resolved the collision. Long
    // enough to still reach the wall at grazing angles, where the distance
    // along the travel direction grows with 1/cos(angle).
    // 2nd: a sphere sweep from the current position (catches thin posts or
    // edges the center ray slips past).
    // Neither finds a wall -> no bounce. (There used to be a last resort
    // that took the impact direction itself as the normal, but with no wall
    // found that bounced the melon off thin air.)
    // Whatever they find must then pass IsWallContact: the ray reaches far
    // ahead, and in a small room it finds some wall on nearly every hard
    // landing or bump, even though the melon isn't touching it.
    const from = kart.prevOrigin ?? kart.melon.GetAbsOrigin();
    const ray = TraceLine({
        start: from,
        end: {
            x: from.x + dir.x * WALL_BOUNCE_TRACE_DISTANCE,
            y: from.y + dir.y * WALL_BOUNCE_TRACE_DISTANCE,
            z: from.z,
        },
        ignoreEntity,
        ignorePlayers: true,
    });
    /** @type {any} */
    let trace = ray.didHit && !ray.startedInSolid ? ray : null;
    let method = "ray";
    if (!trace) {
        const start = kart.melon.GetAbsOrigin();
        const sphere = TraceSphere({
            radius: WALL_BOUNCE_TRACE_RADIUS,
            start,
            end: {
                x: start.x + dir.x * WALL_BOUNCE_SPHERE_TRACE_DISTANCE,
                y: start.y + dir.y * WALL_BOUNCE_SPHERE_TRACE_DISTANCE,
                z: start.z,
            },
            ignoreEntity,
            ignorePlayers: true,
        });
        trace = sphere.didHit && !sphere.startedInSolid ? sphere : null;
        method = "sphere";
    }

    if (!trace) {
        return null;
    }
    const hit = trace.hitEntity;
    if (hit && !hit.IsWorld() && hit.GetClassName().startsWith("prop_physics")) {
        return null;
    }
    const { x: nx, y: ny, z: nz } = trace.normal;
    if (Math.abs(nz) > WALL_NORMAL_MAX_Z) {
        return null;
    }
    const h = Math.hypot(nx, ny);
    if (h <= 0) {
        return null;
    }
    const n = { x: nx / h, y: ny / h };
    const hitPoint = trace.end;
    const incoming = PickIncomingVelocity(v, kart.prevLastVelocity, n);
    if (!IsWallContact(kart.melon.GetAbsOrigin(), hitPoint, n, incoming, kart.melon.GetAbsVelocity())) {
        Debug(`wall bounce rejected: wall found via ${method} isn't actually being touched (impact ${Math.hypot(impactDelta.x, impactDelta.y, impactDelta.z).toFixed(0)} u/s)`);
        return null;
    }
    return { ...n, method, hitPoint };
}

/**
 * DEBUG only: logs the velocity-based bounce angle next to the look-based
 * one, so a "that felt like 45°" mismatch can be told apart from a
 * measuring bug.
 * @param {import("../../core/kart-registry.js").Kart} kart
 * @param {{ x: number, y: number, method: string }} n @param {number} angle
 */
function DebugLogBounce(kart, n, angle) {
    if (!DEBUG) {
        return;
    }
    const yaw = (kart.pawn.GetEyeAngles().yaw * Math.PI) / 180;
    const lookDir = { x: Math.cos(yaw), y: Math.sin(yaw) };
    const lookInto = -(lookDir.x * n.x + lookDir.y * n.y);
    const lookAngle = lookInto > 0 ? (Math.acos(Math.min(1, lookInto)) * 180) / Math.PI : NaN;
    Debug(
        `bounce angle: velocity ${angle.toFixed(1)}°, look ${Number.isNaN(lookAngle) ? "away from wall" : lookAngle.toFixed(1) + "°"}, ` +
        `normal via ${n.method}`
    );
}

/**
 * Reflects the melon's pre-impact horizontal velocity off a wall and scales
 * it by how well the hit was angled (see WALL_BOUNCE_* in movement/wall-bounce/constants.js).
 * Horizontal only — the upward kick (WALL_BOUNCE_UP_SPEED) is added by UpdateKart.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {{ x: number, y: number, method: string, hitPoint?: any }} n @param {number} now
 * @returns {{ velocity: { x: number, y: number }, angle: number, angleFactor: number, jumpFactor: number, speedGain: number } | null}
 *   null if the melon wasn't actually moving into the wall
 */
function ComputeWallBounce(kart, n, now) {
    const v = PickIncomingVelocity(/** @type {{ x: number, y: number, z: number }} */ (kart.lastVelocity), kart.prevLastVelocity, n);
    // A timing press just *before* the hit counts here; one just after is
    // handled by UpdateKart's jump code upgrading kart.pendingBounce.
    const jumpFactor = kart.wallTimingPressTime !== undefined ? JumpTimingFactor(now - kart.wallTimingPressTime) : 0;
    const bounce = ReflectOffWall(v, n, jumpFactor);
    if (!bounce) {
        return null;
    }
    DebugLogBounce(kart, n, bounce.angle);
    // A PERFECT hit shows its own spark instead of the boost trail — see
    // ShouldShowBoostTrail. Any other rating's speed shows the trail again.
    kart.perfectBounceBoost = GetBounceRating(bounce.angleFactor) === BOUNCE_RATINGS[0];
    if (kart.perfectBounceBoost) {
        PlayPerfectSpark(kart);
    }
    return { ...bounce, jumpFactor };
}

/**
 * Spawns two fresh copies of the perfect_hit_particle_template and starts
 * them, removed again after PERFECT_SPARK_LIFETIME: one left at the hit spot
 * on the wall, and one parented to the melon so it rides along — the melon
 * is off the wall so fast that the player would otherwise never see the
 * spark behind them. Fresh copies per hit, so several karts' perfect hits
 * at the same moment each show their own. Also played by a PERFECT wall jump.
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function PlayPerfectSpark(kart) {
    const position = kart.melon.GetAbsOrigin();
    PlayParticleTemplate(PERFECT_SPARK_TEMPLATE_NAME, position, { lifetime: PERFECT_SPARK_LIFETIME });
    PlayParticleTemplate(PERFECT_SPARK_TEMPLATE_NAME, position, { lifetime: PERFECT_SPARK_LIFETIME, parent: kart.melon });
}

/**
 * Whether kart.pendingBounce breaks the melon right at the wall — see
 * IsLethalAtImpact. A jump pad's damage protection still saves it.
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function WallBounceBreaksAtImpact(kart) {
    const p = kart.pendingBounce;
    return p !== undefined && !IsPadProtected(kart) && IsLethalAtImpact(kart.health, p.impactSpeed, p.speedGain, p.angleFactor);
}

/**
 * Charges kart.pendingBounce's damage now that its jump window is over (a
 * late jump can still have raised its speed gain): the wall's usual impact +
 * speed-gain damage, reduced by angle closeness — a perfect 45° hit is free.
 * @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart
 * @returns {boolean} whether the melon broke from it
 */
function SettleWallBounceDamage(slot, kart) {
    const p = kart.pendingBounce;
    kart.pendingBounce = undefined;
    if (!p) {
        return false;
    }
    const damage = WallBounceDamage(p.impactSpeed, p.speedGain, p.angleFactor);
    DamageKart(
        slot,
        kart,
        damage,
        `wall bounce ${p.angle.toFixed(0)}° (angle ${p.angleFactor.toFixed(2)}, jump ${p.jumpFactor.toFixed(2)}), ` +
        `impact ${p.impactSpeed.toFixed(0)} u/s, gained ${p.speedGain.toFixed(0)} u/s`
    );
    if (kart.health <= 0) {
        BreakMelon(slot, kart, p.impactDir, p.impactSpeed);
        return true;
    }
    return false;
}

// Collision debug view: everything that shows how ground/wall contact and jump
// presses are judged — the on-screen status line, the probes drawn into the
// world, and the "Jump pressed" console log. Toggled per player from the
// user menu (kart.collisionDebug, see SetCollisionDebug); off by default. The contact
// code in contact.js/drive.js/jump.js only hands its results to the
// Record*/Log*/Draw* functions here, so none of this lives in the gameplay
// code itself. Debug draws only show in dev environments (tools mode).

/**
 * What this tick's probes saw. Rebuilt every tick (while the view is on)
 * by the Record* functions below.
 * @typedef {"miss" | "ignored" | "far" | "near" | "chosen"} ProbeState
 * @typedef {{
 *   origin: any,
 *   support: string,
 *   floorEnd: any, floorHit: boolean, floorOk: boolean, floorText: string,
 *   probes: { end: any, state: ProbeState }[],
 *   wallText: string,
 *   wall?: WallDebug,
 * }} ContactDebug
 * @typedef {{ point: any, normal: { x: number, y: number }, gap: number, reach: number, actual: any, touching: boolean }} WallDebug
 *   the nearest wall the probes found: `gap` center to its plane, `reach` how close it had to be (see WallContactReach)
 */

/** @param {import("../core/kart-registry.js").Kart} kart */
function IsCollisionDebugOn(kart) {
    return Boolean(kart.collisionDebug);
}

/** Turns the view on/off for this kart's player. @param {import("../core/kart-registry.js").Kart} kart @param {boolean} on */
function SetCollisionDebug(kart, on) {
    kart.collisionDebug = on;
    if (!on) {
        kart.contactDebug = undefined;
    }
}

/**
 * Start of a tick's record: the measured support and the floor trace.
 * @param {import("../core/kart-registry.js").Kart} kart @param {any} origin
 * @param {boolean} supported @param {number | undefined} verticalAccel
 * @param {any} trace the floor TraceLine result @param {boolean} grounded
 */
function RecordFloorProbe(kart, origin, supported, verticalAccel, trace, grounded) {
    if (!IsCollisionDebugOn(kart)) {
        return;
    }
    const floorHit = trace.didHit && !trace.startedInSolid;
    kart.contactDebug = {
        origin,
        support: `supported=${supported}, az=${verticalAccel === undefined ? "—" : verticalAccel.toFixed(0)}`,
        floorEnd: trace.end,
        floorHit,
        floorOk: grounded,
        floorText: trace.startedInSolid
            ? "started in solid"
            : floorHit
              ? `hit ${(origin.z - trace.end.z).toFixed(1)} below, normal z ${trace.normal.z.toFixed(2)}`
              : "nothing",
        probes: [],
        wallText: "—",
    };
}

/**
 * The wall probes (every tick while the view is on, also on the ground) and the nearest wall they found, with
 * its measured distance from the melon's center — read that off to tune
 * WALL_JUMP_CONTACT_RADIUS.
 * @param {import("../core/kart-registry.js").Kart} kart
 * @param {{ end: any, state: ProbeState }[]} probes
 * @param {WallDebug} [wall]
 */
function RecordWallProbes(kart, probes, wall) {
    const d = kart.contactDebug;
    if (!IsCollisionDebugOn(kart) || !d) {
        return;
    }
    d.probes = probes;
    d.wall = wall;
    if (!wall) {
        d.wallText = "no wall";
        return;
    }
    const into = -(wall.actual.x * wall.normal.x + wall.actual.y * wall.normal.y);
    d.wallText = `${wall.gap.toFixed(1)} from center (counts <= ${wall.reach.toFixed(1)}), into ${into.toFixed(0)} u/s${wall.touching ? " AT WALL" : ""}`;
}

/**
 * Console log of a jump press: why it was (or wasn't) allowed.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart @param {number} now
 * @param {boolean} grounded @param {boolean} groundJump @param {boolean} timingPress
 */
function LogJumpPress(slot, kart, now, grounded, groundJump, timingPress) {
    if (!IsCollisionDebugOn(kart)) {
        return;
    }
    const d = kart.contactDebug;
    const groundAge = kart.lastGroundedTime === undefined ? "never" : `${(now - kart.lastGroundedTime).toFixed(3)}s ago`;
    const wallAge = kart.lastWallContact === undefined ? "never" : `${(now - kart.lastWallContact.time).toFixed(3)}s ago`;
    Instance.Msg(
        `[collision debug] slot ${slot} jump pressed: grounded=${grounded} groundJump=${groundJump} ` +
            `(ground contact ${groundAge}, ${d?.support ?? "—"}, floor: ${d?.floorText ?? "—"}) ` +
            `wall contact ${wallAge} (${d?.wallText ?? "—"}) wallCharge=${(kart.wallJumpCharge ?? 1).toFixed(2)} wallTiming=${timingPress}`
    );
}

/**
 * Console log of whether that press became a wall jump, and if not, why.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 * @param {string | null} blockedBy see WallJumpBlockReason @param {boolean} inLift
 */
function LogWallJumpVerdict(slot, kart, blockedBy, inLift) {
    if (!IsCollisionDebugOn(kart)) {
        return;
    }
    Instance.Msg(`[collision debug] slot ${slot} wall jump: ${blockedBy === null ? "YES" : `no — ${blockedBy}`}${inLift ? " (in lift zone)" : " (not in a lift zone)"}`);
}

// Colors — see the legend in GAMEPLAY.md's "Jumping".
const COLOR_MISS = { r: 110, g: 110, b: 110 };
const COLOR_IGNORED = { r: 170, g: 80, b: 200 };
const COLOR_FAR = { r: 80, g: 120, b: 200 };
const COLOR_NEAR = { r: 60, g: 220, b: 230 };
const COLOR_CHOSEN = { r: 255, g: 180, b: 60 };
const COLOR_TOUCH = { r: 60, g: 255, b: 60 };
const COLOR_ACTUAL = { r: 80, g: 140, b: 255 };
const COLOR_RING = { r: 230, g: 230, b: 230 }; // bright: a dark ring vanished against the floor
const COLOR_WHITE = { r: 255, g: 255, b: 255 };
const PROBE_COLORS = { miss: COLOR_MISS, ignored: COLOR_IGNORED, far: COLOR_FAR, near: COLOR_NEAR, chosen: COLOR_CHOSEN };
const VELOCITY_DRAW_SCALE = 0.15; // units of line per unit/sec
const RING_SEGMENTS = 24;
const FLOOR_RING_LIFT = 1; // units above the floor trace's hit
// The marker at the wall's hit point — small: the melon itself is only ~7
// units in radius, and a bigger sphere (8) hid it close up.
const WALL_MARKER_RADIUS_AT = 2.5; // at the melon
const WALL_MARKER_RADIUS_FAR = 1.5; // found, too far
const JUMPABLE_RING_RADIUS = WALL_JUMP_CONTACT_RADIUS + 8;

/** @param {any} start @param {any} end @param {{ r: number, g: number, b: number }} color */
function Line(start, end, color) {
    Instance.DebugLine({ start, end, duration: 0, color });
}

/** @param {any} center @param {number} radius @param {{ r: number, g: number, b: number }} color */
function Circle(center, radius, color) {
    for (let i = 0; i < RING_SEGMENTS; i++) {
        const a0 = (i / RING_SEGMENTS) * Math.PI * 2;
        const a1 = ((i + 1) / RING_SEGMENTS) * Math.PI * 2;
        Line(
            { x: center.x + Math.cos(a0) * radius, y: center.y + Math.sin(a0) * radius, z: center.z },
            { x: center.x + Math.cos(a1) * radius, y: center.y + Math.sin(a1) * radius, z: center.z },
            color
        );
    }
}

/**
 * A horizontal velocity as a line from `from`, VELOCITY_DRAW_SCALE long per unit/sec.
 * @param {any} from @param {{ x: number, y: number }} v @param {{ r: number, g: number, b: number }} color @param {number} dz
 */
function Velocity(from, v, color, dz) {
    const start = { x: from.x, y: from.y, z: from.z + dz };
    Line(start, { x: start.x + v.x * VELOCITY_DRAW_SCALE, y: start.y + v.y * VELOCITY_DRAW_SCALE, z: start.z }, color);
}

/**
 * Draws this tick's record: the status line on screen, and in the world
 * the floor trace, the WALL_JUMP_CONTACT_RADIUS ring, every wall probe
 * colored by what it hit, and at the nearest wall its normal and the
 * melon's velocity.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart @param {boolean} grounded
 * @param {{ x: number, y: number } | undefined} wallNormal @param {number} jumpWindow seconds a wall contact stays jumpable (WallRules.wallJumpWindow)
 */
function DrawCollisionDebug(slot, kart, grounded, wallNormal, jumpWindow) {
    const d = kart.contactDebug;
    if (!IsCollisionDebugOn(kart) || !d) {
        return;
    }
    Instance.DebugScreenText({
        text: `slot ${slot}: ${grounded ? "GROUND" : "AIR"}${wallNormal ? " + WALL" : ""}  (${d.support}, floor: ${d.floorText}, wall: ${d.wallText})`,
        x: 20,
        y: 200 + slot * 16,
        duration: 0,
        color: grounded ? { r: 90, g: 220, b: 90 } : wallNormal ? COLOR_CHOSEN : COLOR_WHITE,
    });
    const o = d.origin;
    // Floor trace: green = ground contact, white = hit something but not
    // held up by it (or not floor-like), grey = nothing below.
    Line(o, d.floorEnd, d.floorOk ? COLOR_TOUCH : d.floorHit ? COLOR_WHITE : COLOR_MISS);
    if (d.probes.length === 0) {
        return; // no probes ran (view switched on mid-tick)
    }
    // How close a wall must be to the center to count (standing still —
    // moving at it, one tick's travel is added): at the center's height,
    // and again flat on the floor below (FLOOR_RING_LIFT up, so it doesn't
    // sink into it) — from the chase camera the one at center height is
    // mostly hidden by the melon while it's on the ground.
    Circle(o, WALL_JUMP_CONTACT_RADIUS, COLOR_RING);
    if (d.floorHit) {
        Circle({ x: o.x, y: o.y, z: d.floorEnd.z + FLOOR_RING_LIFT }, WALL_JUMP_CONTACT_RADIUS, COLOR_RING);
    }
    for (const p of d.probes) {
        Line(o, p.end, PROBE_COLORS[p.state]);
    }
    // Jumpable right now (at a wall this tick, or within jumpWindow): a
    // green ring just outside the contact ring.
    if (kart.lastWallContact && Instance.GetGameTime() - kart.lastWallContact.time <= jumpWindow) {
        Circle(o, JUMPABLE_RING_RADIUS, COLOR_TOUCH);
    }
    const w = d.wall;
    if (!w) {
        return;
    }
    // Wall normal at the nearest wall, and a marker: green = at the melon
    // now (within reach), orange = found but too far.
    const color = w.touching ? COLOR_TOUCH : COLOR_CHOSEN;
    Line(w.point, { x: w.point.x + w.normal.x * 32, y: w.point.y + w.normal.y * 32, z: w.point.z }, color);
    Instance.DebugSphere({ center: w.point, radius: w.touching ? WALL_MARKER_RADIUS_AT : WALL_MARKER_RADIUS_FAR, duration: 0, color });
    // The melon's velocity now: its part towards the wall widens the reach.
    Velocity(o, w.actual, COLOR_ACTUAL, 0);
}

// Engine side of jumping: what a jump press does each tick (ground jump,
// wall jump, wall-bounce timing credit) and the wall-jump charges the HUD's
// jump icons show. The rules themselves are in ./logic.js (jumps, charge)
// and ../wall-bounce/logic.js (timing); whether the melon is on the ground
// or at a wall comes from ../contact/; what a lift zone changes arrives as
// WallRules (../../zones/lift/logic.js).

/**
 * Records a jump-button press for wall-bounce timing, separately from the
 * normal (ground-contact gated) jump. Anti-spam (WallTimingPress): a press
 * soon after one that did nothing locks timing credit, so mashing jump along
 * a wall never counts — a ground or wall jump just before doesn't (see
 * RecordIdlePress for what counts as doing nothing).
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} now
 * @returns {boolean} whether this press counts for wall timing
 */
function RegisterWallTimingPress(kart, now) {
    kart.lastJumpPressTime = now; // every press — jump pads buffer on it
    const press = WallTimingPress(now, kart.lastIdleJumpPressTime, kart.wallTimingLockedUntil);
    kart.wallTimingLockedUntil = press.lockedUntil;
    if (press.mashing) {
        kart.wallTimingPressTime = undefined; // an earlier press in the same mash doesn't count either
    }
    if (press.counts) {
        kart.wallTimingPressTime = now;
    }
    return press.counts;
}

/**
 * Refills the wall-jump charges — every tick, from the top of UpdateKart, so
 * it also fills while the melon stands still, is race-locked or broken (it
 * used to refill only on ticks that got as far as the jump handling).
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} dt
 */
function RechargeWallJumpCharge(kart, dt) {
    // ?? full: karts carried over a hot reload from before the charge existed.
    kart.wallJumpCharge = RechargeWallJump(kart.wallJumpCharge ?? WALL_JUMP_CHARGES, dt);
}

/**
 * How many wall jumps are charged, 0..WALL_JUMP_CHARGES — fractional while
 * one is refilling. What the HUD's jump icons show.
 * @param {{ wallJumpCharge?: number }} kart
 */
function GetWallJumpCharges(kart) {
    return kart.wallJumpCharge ?? WALL_JUMP_CHARGES;
}

/**
 * Everything a jump press does this tick, applied to `v` (the velocity
 * UpdateKart is about to command, modified in place): the ground jump, the
 * wall-bounce timing credit, and the wall jump. Also fires a buffered wall
 * jump (lift zones) without a new press. (The charge refills in
 * RechargeWallJumpCharge.)
 * @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart @param {number} now
 * @param {boolean} grounded see UpdateGrounded @param {boolean} jumpPressed
 * @param {{ x: number, y: number, z: number }} v
 * @param {import("../../zones/lift/logic.js").WallRules} rules see CurrentWallRules
 */
function ApplyJump(slot, kart, now, grounded, jumpPressed, v, rules) {
    if (!jumpPressed) {
        FireBufferedWallJump(slot, kart, now, grounded, v, rules);
        return;
    }
    // Jump: straight-up force, only with real ground contact (see
    // UpdateGrounded / IsSupported) — no cooldown, touching down again is
    // what resets it (CanGroundJump). In the air at a wall, a wall jump
    // instead, as strong as its charge.
    const groundJump = CanGroundJump({ grounded, lastGroundedTime: kart.lastGroundedTime, lastJumpTime: kart.lastJumpTime });
    const timingPress = RegisterWallTimingPress(kart, now);
    LogJumpPress(slot, kart, now, grounded, groundJump, timingPress);
    if (groundJump) {
        v.z = JUMP_SPEED;
        kart.lastJumpTime = now;
    }
    // Wall timing — independent of the normal jump above (works in the air
    // too), purely about *when* it's pressed.
    if (timingPress) {
        UpgradePendingBounce(kart, now, v);
    }
    // Wall jump — after the bounce-timing upgrade, so that one's extra speed
    // isn't lost.
    const blockedBy = groundJump ? "ground jump instead" : TryWallJump(slot, kart, now, grounded, v, rules);
    LogWallJumpVerdict(slot, kart, blockedBy, rules.inLift);
    // Neither a ground nor a wall jump: the press did nothing, so the next
    // one soon after is mashing (see WallTimingPress).
    if (!groundJump && blockedBy !== null) {
        kart.lastIdleJumpPressTime = now;
    }
    // In the air and not a wall jump yet: where there's a jump buffer (lift
    // and side-view zones), remember the press — a wall touched soon after still gets it.
    kart.bufferedWallJumpTime = blockedBy !== null && !grounded && rules.jumpBuffer > 0 ? now : undefined;
}

/**
 * A timing press just *after* a wall bounce whose damage is still pending:
 * if this timing beats whatever press (if any) the bounce already counted,
 * upgrade it — more speed (the speed gain it'll settle damage for grows with
 * it; a perfect angle still makes that free).
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} now @param {{ x: number, y: number, z: number }} v
 */
function UpgradePendingBounce(kart, now, v) {
    const pending = kart.pendingBounce;
    if (!pending) {
        return;
    }
    const lateFactor = JumpTimingFactor(now - pending.time);
    if (lateFactor <= pending.jumpFactor) {
        return;
    }
    const ratio = JumpMultiplier(lateFactor) / JumpMultiplier(pending.jumpFactor);
    const before = Math.hypot(v.x, v.y);
    v.x *= ratio;
    v.y *= ratio;
    const after = Math.hypot(v.x, v.y);
    pending.speedGain += after - before;
    pending.jumpFactor = lateFactor;
    if (kart.lastBounceInfo) {
        kart.lastBounceInfo.jumpFactor = lateFactor;
    }
    kart.speedCap = Math.max(kart.speedCap ?? MomentumMaxSpeed(kart.momentum), after);
}

/**
 * A jump pressed shortly *before* touching a wall (within rules.jumpBuffer,
 * lift and side-view zones only) fires the wall jump once the melon touches one.
 * @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart @param {number} now @param {boolean} grounded
 * @param {{ x: number, y: number, z: number }} v @param {import("../../zones/lift/logic.js").WallRules} rules
 */
function FireBufferedWallJump(slot, kart, now, grounded, v, rules) {
    const pressed = kart.bufferedWallJumpTime;
    if (pressed === undefined) {
        return;
    }
    if (now - pressed > rules.jumpBuffer) {
        kart.bufferedWallJumpTime = undefined; // too long ago, or left the zone (no buffer outside)
        return;
    }
    const wallContact = kart.lastWallContact;
    if (wallContact && wallContact.time > pressed && TryWallJump(slot, kart, now, grounded, v, rules) === null) {
        kart.bufferedWallJumpTime = undefined;
        if (kart.lastIdleJumpPressTime === pressed) {
            kart.lastIdleJumpPressTime = undefined; // that press did something after all — not mashing
        }
        Debug(`wall jump: slot ${slot} from a press ${(now - pressed).toFixed(2)}s before touching the wall`);
    }
}

/**
 * Wall jump, if allowed right now: in the air, at (or just off) a wall, push
 * away from it and up at full strength, using up one of the
 * WALL_JUMP_CHARGES (none left: no wall jump). WallJumpVelocity keeps whichever
 * push away from the wall is stronger. Rated by the angle it came at the
 * wall like a bounce (WallJumpAngle, WALL_JUMP_RATING_SPEED_MULTIPLIER): only
 * (rules.ratedWallJumps — not in a lift or side-view zone) a PERFECT/GOOD one leaves with the speed it came in with times the
 * multiplier, like a bounce (WallJumpBoostedVelocity) — that raises kart.speedCap — a plain wall jump
 * doesn't, chained wall jumps used to ratchet the melon ever faster.
 * Never lowers the melon's upward speed (a jump just after a ground jump,
 * a bounce's kick or a jump pad launch keeps the faster one).
 * While a wall bounce's jump-timing window is open (kart.pendingBounce),
 * the press is that bounce's timing and no wall jump — otherwise every
 * well-timed bounce also used up charge. Not in lift and side-view zones
 * (rules.freeWallJumps): there it costs no charge (none needed either),
 * may follow a bounce at once, and the cooldown is rules.wallJumpCooldown.
 * @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart @param {number} now @param {boolean} grounded
 * @param {{ x: number, y: number, z: number }} v modified in place @param {import("../../zones/lift/logic.js").WallRules} rules
 * @returns {string | null} why it didn't happen, or null if it did
 */
function TryWallJump(slot, kart, now, grounded, v, rules) {
    const wallContact = kart.lastWallContact;
    const charge = rules.freeWallJumps ? WALL_JUMP_CHARGES : kart.wallJumpCharge;
    const blockedBy = WallJumpBlockReason({
        now,
        grounded,
        wallContact,
        lastWallJump: kart.lastWallJump,
        lastGroundedTime: kart.lastGroundedTime,
        charge,
        cooldown: rules.wallJumpCooldown,
        window: rules.wallJumpWindow,
        bounceTiming: !rules.freeWallJumps && kart.pendingBounce !== undefined,
    });
    if (!wallContact || blockedBy !== null) {
        return blockedBy;
    }
    const jump = WallJumpVelocity({ x: v.x, y: v.y }, wallContact.normal, rules.wallJumpPushSpeed, rules.wallJumpUpSpeed);
    // In a lift zone the angle doesn't matter — the shaft is climbed, not
    // raced — nor in a side-view zone (2D jump & run): a plain wall jump, no
    // rating, boost or feedback.
    /** @type {ReturnType<typeof WallJumpAngle> | undefined} */
    let rated = undefined;
    let bonus = { speed: 1, up: 1 };
    if (!rules.ratedWallJumps) {
        v.x = jump.x;
        v.y = jump.y;
        v.z = Math.max(v.z, jump.z);
    } else {
        // The approach remembered at the contact's start counts too: a press a
        // tick or two after the touch would otherwise only see the slide along
        // the wall (WALL_JUMP_APPROACH_MEMORY).
        rated = WallJumpAngle([v, kart.lastVelocity, kart.prevLastVelocity, FreshApproach(wallContact, now)], wallContact.normal);
        bonus = WallJumpRatingMultipliers(rated.rating);
        const boosted = WallJumpBoostedVelocity(jump, rated.incomingSpeed, bonus.speed);
        v.x = boosted.x;
        v.y = boosted.y;
        v.z = Math.max(v.z, jump.z * bonus.up);
        if (bonus.speed > 1) {
            kart.speedCap = Math.max(kart.speedCap ?? MomentumMaxSpeed(kart.momentum), Math.hypot(v.x, v.y));
        }
        // Same feedback as a bounce: the bounce panel and speedometer flash
        // (jump timing full — it was jumped), a PERFECT's spark instead of the
        // boost trail.
        kart.lastBounceTime = now;
        kart.lastBounceInfo = { angle: rated.angle, angleFactor: rated.angleFactor, jumpFactor: 1 };
        kart.perfectBounceBoost = rated.rating === BOUNCE_RATINGS[0];
        if (kart.perfectBounceBoost) {
            PlayPerfectSpark(kart);
        }
    }
    kart.lastWallJump = { time: now, normal: wallContact.normal };
    if (!rules.freeWallJumps) {
        kart.wallJumpCharge = WallJumpChargeAfter(charge);
    }
    Debug(`wall jump: slot ${slot}, ${rated ? `${rated.rating.label} ${rated.angle.toFixed(0)}° (×${bonus.speed})` : "not rated"}, charges ${charge.toFixed(2)}${rules.freeWallJumps ? " (lift/side-view zone, free)" : ""}, off wall normal (${wallContact.normal.x.toFixed(2)}, ${wallContact.normal.y.toFixed(2)})`);
    return null;
}

// Pure rule for the HUD's wall-jump dots — no cs_script import, so it's
// unit-testable in Node (see test/hud/jump-dots.test.mjs). Applied by
// UpdateJumpHud in ./speedometer.js.

/**
 * How full each jump dot is, in fill steps (0 = empty ..
 * JUMP_DOT_FILL_STEPS = charged): the first floor(charges) dots are
 * charged, the next one shows how far it has refilled (rounded down, so it
 * only looks full once it is), the rest are empty.
 * @param {number} charges wall jumps charged, fractional while one refills (see GetWallJumpCharges)
 * @param {number} dots how many dots there are (WALL_JUMP_CHARGES)
 * @returns {number[]}
 */
function JumpDotFills(charges, dots) {
    const fills = [];
    for (let i = 0; i < dots; i++) {
        const part = Math.max(0, Math.min(1, charges - i));
        fills.push(Math.floor(part * JUMP_DOT_FILL_STEPS + 1e-9));
    }
    return fills;
}

// The speed panel, bottom center: km/h, the health bar under it and the
// wall-jump dots next to it.

/** @param {number} slot @param {import("../core/kart-registry.js").Kart} kart */
function UpdateSpeedHud(slot, kart) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    const vel = kart.melon.GetAbsVelocity();
    const horizSpeed = Math.hypot(vel.x, vel.y);
    const kmh = Math.round(horizSpeed * UNITS_TO_KMH);
    hud.SetDialogVariableStringForPlayer(slot, "speed_panel", "speed", String(kmh));
    // Wall-bounce feedback: Boosted while a bounce has the melon above its
    // normal top speed (momentum included — that's earned, not a boost), PerfectBounce as a short flash after a bounce that
    // was clean enough to cost (almost) no health.
    hud.SetHasClassForPlayer(slot, "speed_panel", "Boosted", horizSpeed > MomentumMaxSpeed(kart.momentum) + 1);
    const info = kart.lastBounceInfo;
    const perfectFlash =
        info !== undefined &&
        info.angleFactor >= PERFECT_BOUNCE_ANGLE_FACTOR &&
        kart.lastBounceTime !== undefined &&
        Instance.GetGameTime() - kart.lastBounceTime < PERFECT_BOUNCE_FLASH_SECONDS;
    hud.SetHasClassForPlayer(slot, "speed_panel", "PerfectBounce", perfectFlash);
}

/**
 * Whether `key`'s whole HUD state is due to be sent again (every
 * HUD_RESEND_SECONDS, and on the first call) — in between only changes are.
 * @param {import("../core/kart-registry.js").Kart} kart @param {"health" | "jump"} key
 */
function HudResendDue(kart, key) {
    const now = Instance.GetGameTime();
    const due = (kart.hudResendAt ??= {});
    if (due[key] !== undefined && now < due[key]) {
        return false;
    }
    due[key] = now + HUD_RESEND_SECONDS;
    return true;
}

/**
 * Jump dots = the wall-jump charges (see GetWallJumpCharges, JumpDotFills):
 * a dot's fill ("jump_dot_<i>") is transparent by default and shown with
 * "On" while that charge is ready — nothing while it refills. Sent when a
 * dot changed (kart.hudJumpReady), and every dot again every
 * HUD_RESEND_SECONDS. One class per panel: several classes toggled on one
 * panel every tick never showed in-game.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 */
function UpdateJumpHud(slot, kart) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    const ready = JumpDotFills(GetWallJumpCharges(kart), WALL_JUMP_CHARGES).map((fill) => fill === JUMP_DOT_FILL_STEPS);
    const shown = HudResendDue(kart, "jump") ? undefined : kart.hudJumpReady;
    for (let i = 0; i < ready.length; i++) {
        if (shown === undefined || shown[i] !== ready[i]) {
            hud.SetHasClassForPlayer(slot, `jump_dot_${i}`, "On", ready[i]);
        }
    }
    kart.hudJumpReady = ready;
}

/**
 * Health bar under the km/h: HEALTH_BAR_SEGMENTS pieces, transparent by
 * default, the ones up to the health left shown with "On". Sent when the
 * count changed (kart.hudHealthSegments), and all of it again every
 * HUD_RESEND_SECONDS (see UpdateJumpHud).
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 */
function UpdateHealthHud(slot, kart) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    const filled = HealthBarState(kart.health).filledSegments;
    if (!HudResendDue(kart, "health") && filled === kart.hudHealthSegments) {
        return;
    }
    for (let i = 0; i < HEALTH_BAR_SEGMENTS; i++) {
        hud.SetHasClassForPlayer(slot, `health_seg_${i}`, "On", i < filled);
    }
    kart.hudHealthSegments = filled;
}

/**
 * Wall-bounce feedback panel (bounce_panel in speedometer.xml), shown for
 * BOUNCE_HUD_SECONDS after each bounce: a rating word, the exact angle hit,
 * an angle scale with the hit's segment marked against the 45° target, and
 * how well the jump was timed. Reads kart.lastBounceInfo live, so a jump just
 * *after* the hit still updates the timing bar while the panel is up.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 */
function UpdateBounceHud(slot, kart) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    const info = kart.lastBounceInfo;
    const visible =
        info !== undefined &&
        kart.lastBounceTime !== undefined &&
        Instance.GetGameTime() - kart.lastBounceTime < BOUNCE_HUD_SECONDS;
    hud.SetHasClassForPlayer(slot, "bounce_panel", "Hidden", !visible);
    if (!visible || !info) {
        return;
    }

    const rating = GetBounceRating(info.angleFactor);
    for (const r of BOUNCE_RATINGS) {
        hud.SetHasClassForPlayer(slot, "bounce_panel", r.cssClass, r === rating);
    }
    hud.SetDialogVariableStringForPlayer(slot, "bounce_panel", "bounce_rating", rating.label);
    hud.SetDialogVariableStringForPlayer(slot, "bounce_panel", "bounce_angle", String(Math.round(info.angle)));

    const hitSegment = Math.min(BOUNCE_ANGLE_SEGMENTS - 1, Math.floor((info.angle / 90) * BOUNCE_ANGLE_SEGMENTS));
    for (let i = 0; i < BOUNCE_ANGLE_SEGMENTS; i++) {
        hud.SetHasClassForPlayer(slot, `bounce_angle_seg_${i}`, "Hit", i === hitSegment);
    }
    const jumpFilled = Math.round(info.jumpFactor * BOUNCE_JUMP_SEGMENTS);
    for (let i = 0; i < BOUNCE_JUMP_SEGMENTS; i++) {
        hud.SetHasClassForPlayer(slot, `bounce_jump_seg_${i}`, "Filled", i < jumpFilled);
    }
}

// Per-track config comes straight from Hammer instead of a hand-maintained
// lookup: each track has one trigger_multiple named "start_<trackId>" or
// "start_<trackId>_laps<lapsToWin>" (e.g. "start_1_laps3"; without _laps
// it's DEFAULT_LAPS_TO_WIN), and its checkpoint count is however many
// "checkpoint_<trackId>_<index>" triggers the map has (the highest index —
// they must run 1..N without gaps, or finish_<trackId> can never be
// reached; a gap is logged). The start trigger's transform also doubles as
// where racers are teleported to start that track. Parsed once and cached —
// the geometry can't change without a full map reload anyway. Only the
// entity *name* is kept, not the entity handle itself: unlike
// Instance.FindEntityByName's handles, the ones yielded by
// FindEntitiesByClass's iterator below don't stay valid once the loop moves
// on, so resolving to a live entity happens at each point of use instead
// (see BeginHeat in race/heat/race-flow.js).
/** @typedef {{ checkpoints: number, lapsToWin: number, startEntityName: string }} TrackConfig */
/** @type {Record<number, TrackConfig> | null} */
let trackConfigCache = null;
// When no start triggers are found yet, the result isn't cached (see below),
// and GetTrackConfig is called per kart every tick by the HUD — so without
// this, a map with no tracks rescanned every trigger_multiple (and logged
// about it) several times per tick. Retry at most once a second instead.
const EMPTY_RESCAN_INTERVAL = 1; // seconds
let lastEmptyScanTime = -Infinity;

function GetTrackConfig() {
    if (trackConfigCache) {
        return trackConfigCache;
    }
    const now = Instance.GetGameTime();
    if (now - lastEmptyScanTime < EMPTY_RESCAN_INTERVAL) {
        return {};
    }
    /** @type {Record<number, TrackConfig>} */
    const config = {};
    /** @type {Map<number, Set<number>>} checkpoint indices found per track */
    const checkpointIndices = new Map();
    for (const trigger of Instance.FindEntitiesByClass("trigger_multiple")) {
        const name = trigger.GetEntityName();
        const start = START_TRIGGER_NAME_PATTERN.exec(name);
        if (start) {
            config[Number(start[1])] = {
                checkpoints: 0, // counted below
                lapsToWin: start[2] !== undefined ? Number(start[2]) : DEFAULT_LAPS_TO_WIN,
                startEntityName: name,
            };
            continue;
        }
        const checkpoint = CHECKPOINT_TRIGGER_NAME_PATTERN.exec(name);
        if (checkpoint) {
            const trackId = Number(checkpoint[1]);
            if (!checkpointIndices.has(trackId)) {
                checkpointIndices.set(trackId, new Set());
            }
            checkpointIndices.get(trackId)?.add(Number(checkpoint[2]));
        }
    }
    if (Object.keys(config).length === 0) {
        // Don't cache an empty result — entities may not have spawned yet.
        lastEmptyScanTime = now;
        Debug("GetTrackConfig: no start_<id> triggers found yet");
        return config;
    }
    for (const [trackId, track] of Object.entries(config)) {
        const indices = checkpointIndices.get(Number(trackId)) ?? new Set();
        track.checkpoints = indices.size > 0 ? Math.max(...indices) : 0;
        for (let i = 1; i <= track.checkpoints; i++) {
            if (!indices.has(i)) {
                Debug(`GetTrackConfig: track ${trackId} has checkpoint_${trackId}_${track.checkpoints} but no checkpoint_${trackId}_${i} — its finish can never be reached`);
            }
        }
    }
    trackConfigCache = config;
    Debug(`GetTrackConfig: found track(s) ${JSON.stringify(config)}`);
    return config;
}

/** Track ids in race order (ascending), derived from whatever start triggers exist. */
function GetTrackOrder() {
    return Object.keys(GetTrackConfig()).map(Number).sort((a, b) => a - b);
}

// Pure time-trial rules — no cs_script import, so they're unit-testable in
// Node (see test/race/time-trial.test.mjs). race/time-trial/time-trial.js applies them: starts
// and stops a kart's run clock, and reads/writes the best times through
// Instance.GetSaveData/SetSaveData.

/**
 * Best time (seconds) per track id per player name.
 * @typedef {Record<string, Record<string, number>>} BestTimes
 */

/**
 * "m:ss.cc", e.g. 83.456 -> "1:23.45". Truncated, not rounded, like a
 * stopwatch — a run is never shown faster than it was.
 * @param {number} seconds
 */
function FormatRaceTime(seconds) {
    const centis = Math.floor(Math.max(0, seconds) * 100 + 1e-6);
    const minutes = Math.floor(centis / 6000);
    const secs = Math.floor(centis / 100) % 60;
    const rest = centis % 100;
    return `${minutes}:${String(secs).padStart(2, "0")}.${String(rest).padStart(2, "0")}`;
}

/**
 * The addon's whole save data as an object — anything unreadable (empty on
 * first run, or written by something else) counts as empty rather than
 * throwing, so a broken file can't stop the script.
 * @param {string} raw
 * @returns {Record<string, any>}
 */
function ParseSaveData(raw) {
    if (!raw) {
        return {};
    }
    try {
        const data = JSON.parse(raw);
        return data && typeof data === "object" && !Array.isArray(data) ? data : {};
    } catch {
        return {};
    }
}

/**
 * The best times inside parsed save data (a fresh object if there are none).
 * Drops entries that aren't positive numbers.
 * @param {Record<string, any>} saveData
 * @returns {BestTimes}
 */
function GetBestTimes(saveData) {
    const raw = saveData[SAVE_DATA_BEST_TIMES_KEY];
    /** @type {BestTimes} */
    const best = {};
    if (!raw || typeof raw !== "object") {
        return best;
    }
    for (const [trackId, players] of Object.entries(raw)) {
        if (!players || typeof players !== "object") {
            continue;
        }
        for (const [name, time] of Object.entries(players)) {
            if (typeof time === "number" && time > 0 && Number.isFinite(time)) {
                (best[trackId] ??= {})[name] = time;
            }
        }
    }
    return best;
}

/**
 * Records a finished run. Only a faster time than the player's best on
 * that track replaces it.
 * @param {BestTimes} best @param {number} trackId @param {string} playerName @param {number} time
 * @returns {boolean} whether it's a new best
 */
function RecordRunTime(best, trackId, playerName, time) {
    const previous = best[trackId]?.[playerName];
    if (previous !== undefined && previous <= time) {
        return false;
    }
    (best[trackId] ??= {})[playerName] = time;
    return true;
}

// Time trial: every run over a track is timed, for every player on their
// own — from crossing the start line (outside a heat) or GO (in a heat) to
// the finish of the last lap. Breaking doesn't stop the clock (the lost time
// is the penalty); leaving the track (hub, tutorial, a new heat) cancels the
// run. Each player's best time per track is kept in the addon's save data,
// keyed by player name — the API has no stable player id. The rules are in
// race/time-trial/logic.js; race/checkpoints/checkpoints.js and race/heat/race-flow.js call in here.

// Parsed from the save data, re-parsed only when that string changes (the
// HUD asks for the best time every tick; the engine itself reads the file
// from disk only once).
/** @type {import("./logic.js").BestTimes} */
let bestTimes = {};
/** @type {string | undefined} */
let bestTimesSource = undefined;

function BestTimes() {
    const raw = Instance.GetSaveData();
    if (raw !== bestTimesSource) {
        bestTimes = GetBestTimes(ParseSaveData(raw));
        bestTimesSource = raw;
    }
    return bestTimes;
}

function SaveBestTimes() {
    // Re-read so keys other systems may keep in the save data survive.
    const data = ParseSaveData(Instance.GetSaveData());
    data[SAVE_DATA_BEST_TIMES_KEY] = bestTimes;
    const raw = JSON.stringify(data);
    Instance.SetSaveData(raw);
    bestTimesSource = raw; // already what bestTimes holds — no re-parse
}

/** @param {import("../../core/kart-registry.js").Kart} kart */
function PlayerName(kart) {
    return kart.pawn.GetPlayerController()?.GetPlayerName() ?? "";
}

/** Starts (or restarts) the kart's run clock. @param {import("../../core/kart-registry.js").Kart} kart @param {number} [now] */
function StartRun(kart, now = Instance.GetGameTime()) {
    kart.runStartTime = now;
}

/** Stops the clock without a result — the kart left the track. @param {import("../../core/kart-registry.js").Kart} kart */
function CancelRun(kart) {
    kart.runStartTime = undefined;
}

/**
 * The run is complete: stops the clock, records the time as the player's
 * best if it is one, and keeps it in kart.lastRun for the HUD. No-op without
 * a running clock.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} trackId
 */
function FinishRun(kart, trackId) {
    if (kart.runStartTime === undefined) {
        return;
    }
    const now = Instance.GetGameTime();
    const time = now - kart.runStartTime;
    kart.runStartTime = undefined;
    const name = PlayerName(kart);
    // RecordRunTime updates the cached object in place; SaveBestTimes then
    // writes exactly that object back.
    const newBest = name !== "" && RecordRunTime(BestTimes(), trackId, name, time);
    if (newBest) {
        SaveBestTimes();
    }
    kart.lastRun = { trackId, time, newBest, at: now };
    Debug(`FinishRun: "${name}" ran track ${trackId} in ${FormatRaceTime(time)}${newBest ? " — new best" : ""}`);
}

/** Seconds on the kart's clock right now (0 if it isn't running). @param {import("../../core/kart-registry.js").Kart} kart @param {number} now */
function RunElapsed(kart, now) {
    return kart.runStartTime === undefined ? 0 : now - kart.runStartTime;
}

/**
 * Whether the user menu offers "Restart Time Trial" (RestartTimeTrial in
 * race/checkpoints/checkpoints.js): only while the kart is on a track in a free-roaming time
 * trial (a finish puts it back at that track's start, so it stays), and
 * never in a heat (restarting there would be a free reset mid-race).
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function CanRestartTimeTrial(kart) {
    return !kart.racing && kart.trackId !== undefined;
}

/** This player's best time on `trackId`, if any. @param {import("../../core/kart-registry.js").Kart} kart @param {number} trackId */
function GetBestTime(kart, trackId) {
    return BestTimes()[trackId]?.[PlayerName(kart)];
}

// What the HUD's checkpoint strip shows (start flag -> numbered checkpoints
// -> finish flag) for a kart's progress — pure, see
// test/hud/checkpoint-strip.test.mjs; hud/ applies it to the panels.

/**
 * @typedef {"reached" | "next" | "pending"} StripState
 * @typedef {{
 *   slots: { number: number, state: StripState }[], // the visible checkpoints, in order
 *   finish: StripState,
 *   moreBefore: boolean, moreAfter: boolean, // checkpoints left out of the window on either side
 * }} Strip
 */

/**
 * @param {number} total the track's checkpoint count
 * @param {number} reached checkpoints reached this lap (kart.checkpointIndex)
 * @param {number} maxSlots how many checkpoints fit (CHECKPOINT_HUD_SLOTS)
 * @param {boolean} [done] the run is over — everything, finish included, reached
 * @returns {Strip}
 */
function CheckpointStrip(total, reached, maxSlots, done = false) {
    const visible = Math.min(total, maxSlots);
    if (done) {
        reached = total;
    }
    // Keep the next checkpoint in view, about in the middle of the window.
    const offset = Math.max(0, Math.min(total - visible, reached - Math.floor(visible / 2)));
    const slots = [];
    for (let i = 0; i < visible; i++) {
        const number = offset + i + 1;
        slots.push({ number, state: number <= reached ? "reached" : number === reached + 1 ? "next" : "pending" });
    }
    return {
        slots,
        finish: done ? "reached" : reached >= total ? "next" : "pending",
        moreBefore: offset > 0,
        moreAfter: offset + visible < total,
    };
}

/**
 * The track HUD: the time trial panel top left (see race/time-trial/time-trial.js) — run
 * clock, the player's best on the track, and for RUN_RESULT_SECONDS after a
 * finish (in a heat: until it's over) the finish time — and the checkpoint
 * strip top center (start -> checkpoints -> finish, see
 * hud/checkpoint-strip-logic.js) with the lap below it on multi-lap tracks. Shown
 * while the kart is on a track — or, right after a free-roaming finish took
 * it off the track, while that result is up.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 */
function UpdateCheckpointHud(slot, kart) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    const now = Instance.GetGameTime();
    const result = kart.lastRun && (kart.finished || now - kart.lastRun.at < RUN_RESULT_SECONDS) ? kart.lastRun : undefined;
    const trackId = kart.trackId ?? result?.trackId;
    hud.SetHasClassForPlayer(slot, "run_panel", "Hidden", trackId === undefined);
    hud.SetHasClassForPlayer(slot, "checkpoint_panel", "Hidden", trackId === undefined);
    if (trackId === undefined) {
        return;
    }
    const config = GetTrackConfig()[trackId];
    // Taken off the track by its finish (or parked after a heat's): show the
    // track as complete.
    const done = kart.trackId === undefined || kart.finished;
    UpdateRunPanel(hud, slot, kart, trackId, now, result);
    UpdateCheckpointStrip(hud, slot, config?.checkpoints ?? 0, kart.checkpointIndex, done);

    const laps = config?.lapsToWin ?? 1;
    hud.SetHasClassForPlayer(slot, "lap_row", "Hidden", laps <= 1);
    hud.SetDialogVariableStringForPlayer(slot, "lap_row", "lap_current", String(done ? laps : Math.min(kart.lapsCompleted + 1, laps)));
    hud.SetDialogVariableStringForPlayer(slot, "lap_row", "lap_total", String(laps));
}

/**
 * @param {any} hud @param {number} slot @param {import("../core/kart-registry.js").Kart} kart @param {number} trackId @param {number} now
 * @param {import("../core/kart-registry.js").Kart["lastRun"]} result the finish time to show, if any
 */
function UpdateRunPanel(hud, slot, kart, trackId, now, result) {
    const clock = kart.runStartTime !== undefined ? RunElapsed(kart, now) : result ? result.time : 0;
    hud.SetDialogVariableStringForPlayer(slot, "run_panel", "time", FormatRaceTime(clock));
    const best = GetBestTime(kart, trackId);
    hud.SetDialogVariableStringForPlayer(slot, "run_panel", "best", best !== undefined ? FormatRaceTime(best) : "-:--.--");
    hud.SetHasClassForPlayer(slot, "run_result", "Hidden", !result);
    if (result) {
        hud.SetHasClassForPlayer(slot, "run_result", "NewBest", result.newBest);
        hud.SetDialogVariableStringForPlayer(slot, "run_result", "result", `${result.newBest ? "NEW BEST" : "FINISH"} ${FormatRaceTime(result.time)}`);
    }
}

/**
 * Sets the strip's CHECKPOINT_HUD_SLOTS circles ("cp_slot_<i>", each with the
 * line "cp_link_<i>" before it), the "…" markers and the finish flag.
 * @param {any} hud @param {number} slot @param {number} total @param {number} reached @param {boolean} done
 */
function UpdateCheckpointStrip(hud, slot, total, reached, done) {
    const strip = CheckpointStrip(total, reached, CHECKPOINT_HUD_SLOTS, done);
    for (let i = 0; i < CHECKPOINT_HUD_SLOTS; i++) {
        const shown = strip.slots[i];
        const state = shown?.state;
        for (const id of [`cp_slot_${i}`, `cp_link_${i}`]) {
            hud.SetHasClassForPlayer(slot, id, "Unused", !shown);
            hud.SetHasClassForPlayer(slot, id, "Reached", state === "reached");
        }
        hud.SetHasClassForPlayer(slot, `cp_slot_${i}`, "Next", state === "next");
        if (shown) {
            hud.SetDialogVariableStringForPlayer(slot, `cp_slot_${i}`, "n", String(shown.number));
        }
    }
    hud.SetHasClassForPlayer(slot, "cp_more_before", "Hidden", !strip.moreBefore);
    hud.SetHasClassForPlayer(slot, "cp_more_after", "Hidden", !strip.moreAfter);
    hud.SetHasClassForPlayer(slot, "cp_link_finish", "Reached", strip.finish === "reached");
    hud.SetHasClassForPlayer(slot, "cp_finish", "Next", strip.finish === "next");
    hud.SetHasClassForPlayer(slot, "cp_finish", "Reached", strip.finish === "reached");
}

// Kept in sync every tick (see Think in core/think.js) as well as on hub_enter,
// since a standing-in-hub player's WaitingForOthers/IsModerator state can
// change underneath them — a heat starting/ending elsewhere, or the
// moderator disconnecting and reassigning to whoever's currently in the hub.
// `currentPhase` is passed in rather than imported from race/heat/race-flow.js so
// this module has no dependency on it (race/heat/race-flow.js already depends on this
// one, for Show/HideHubModal — an import back the other way would make the
// two modules circular for the sake of a single enum comparison).
/** @param {number} slot @param {typeof RacePhase[keyof typeof RacePhase]} currentPhase */
function ApplyHubModalState(slot, currentPhase) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    hud.SetHasClassForPlayer(slot, "hub_modal", "WaitingForOthers", currentPhase !== RacePhase.HUB);
    hud.SetHasClassForPlayer(slot, "hub_modal", "IsModerator", IsModerator(slot));
}

/** @param {number} slot @param {import("../core/kart-registry.js").Kart} kart @param {typeof RacePhase[keyof typeof RacePhase]} currentPhase */
function ShowHubModal(slot, kart, currentPhase) {
    kart.hubModalOpen = true;
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    hud.SetHasClassForPlayer(slot, "hub_modal", "Hidden", false);
    ApplyHubModalState(slot, currentPhase);
    SyncInputCapture(hud, slot, kart);
}

/** @param {number} slot @param {import("../core/kart-registry.js").Kart} kart */
function HideHubModal(slot, kart) {
    kart.hubModalOpen = false;
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    hud.SetHasClassForPlayer(slot, "hub_modal", "Hidden", true);
    SyncInputCapture(hud, slot, kart);
}

// Wall-bounce prediction line — see PREDICTION_* in fx/prediction/constants.js for the
// design. Recomputed every tick from the melon's actual velocity (the same
// direction the bounce itself measures its angle from), and its angle
// rating comes from the same WallAngleFactor/GetBounceRating the bounce
// uses, so the line's color always matches the rating the hit would get.

const HIDDEN_COLOR = { r: 255, g: 255, b: 255, a: 0 };
// Only warn about a missing template once, not every tick.
let warnedMissingTemplate = false;

/**
 * @param {import("../../core/kart-registry.js").Kart} kart
 * @returns {any[] | null} this kart's dot entities, spawning them on first use; null if the map has no template
 */
function GetDots(kart) {
    const total = PREDICTION_DOTS_IN + PREDICTION_DOTS_OUT;
    const existing = (kart.predictionDots ?? []).filter((d) => d.IsValid());
    // Re-registered every call rather than only on spawn: a tools-mode hot
    // reload rebuilds core/trace.js's Set empty while karts (and their dots) persist.
    for (const dot of existing) {
        predictionDotSet.add(dot);
    }
    if (existing.length >= total) {
        kart.predictionDots = existing;
        return existing;
    }
    const template = Instance.FindEntityByName(PREDICTION_DOT_TEMPLATE_NAME);
    if (!(template instanceof PointTemplate)) {
        if (!warnedMissingTemplate) {
            warnedMissingTemplate = true;
            Debug(
                `prediction: no point_template named "${PREDICTION_DOT_TEMPLATE_NAME}" — falling back to DebugLine ` +
                `(dev environments only, real players won't see it)`
            );
        }
        return null;
    }
    const origin = kart.melon.GetAbsOrigin();
    while (existing.length < total) {
        const spawned = template.ForceSpawn(origin, { pitch: 0, yaw: 0, roll: 0 });
        if (!spawned || spawned.length === 0) {
            Debug(`prediction: ForceSpawn of "${PREDICTION_DOT_TEMPLATE_NAME}" returned nothing — check its Template entries`);
            break;
        }
        existing.push(spawned[0]);
        predictionDotSet.add(spawned[0]);
    }
    Debug(`prediction: kart has ${existing.length}/${total} dots, class ${existing[0]?.GetClassName() ?? "-"}`);
    kart.predictionDots = existing;
    return existing;
}

/** @param {any} dot @param {{ r: number, g: number, b: number, a: number }} color */
function SetDotColor(dot, color) {
    // Entity variables are reference-stable, so the last applied color can
    // be cached on the dot itself — skips re-sending an unchanged color
    // every tick.
    const key = `${color.r},${color.g},${color.b},${color.a}`;
    if (dot.predictionColorKey !== key && typeof dot.SetColor === "function") {
        dot.SetColor(color);
        dot.predictionColorKey = key;
    }
}

/** @param {import("../../core/kart-registry.js").Kart} kart */
function HidePrediction(kart) {
    for (const dot of kart.predictionDots ?? []) {
        if (dot.IsValid()) {
            SetDotColor(dot, HIDDEN_COLOR);
        }
    }
}

/**
 * @param {any} from @param {{ x: number, y: number }} dir @param {number} length
 * @param {any[]} ignoreEntity
 */
function TraceAhead(from, dir, length, ignoreEntity) {
    return TraceLine({
        start: from,
        end: { x: from.x + dir.x * length, y: from.y + dir.y * length, z: from.z },
        ignoreEntity,
        ignorePlayers: true,
    });
}

/** @param {any} trace */
function IsWallHit(trace) {
    if (!trace.didHit || trace.startedInSolid || Math.abs(trace.normal.z) > WALL_NORMAL_MAX_Z) {
        return false;
    }
    const hit = trace.hitEntity;
    // Same rule as the bounce's DetectWallNormal: other physics props aren't walls.
    return !(hit && !hit.IsWorld() && hit.GetClassName().startsWith("prop_physics"));
}

/**
 * Evenly spaced points from `a` to `b`, `count` of them (b included).
 * @param {any} a @param {any} b @param {number} count
 */
function PointsAlong(a, b, count) {
    const points = [];
    for (let i = 1; i <= count; i++) {
        const t = i / count;
        points.push({ x: a.x + (b.x - a.x) * t, y: a.y + (b.y - a.y) * t, z: a.z + (b.z - a.z) * t });
    }
    return points;
}

/**
 * Whether this kart's player has the line switched on (user menu toggle,
 * off by default — see UpdatePredictionHud in hud/).
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function IsPredictionOn(kart) {
    return Boolean(kart.predictionLine);
}

/** Turns the line on/off for this kart's player. @param {import("../../core/kart-registry.js").Kart} kart @param {boolean} on */
function SetPrediction(kart, on) {
    kart.predictionLine = on;
    if (!on) {
        HidePrediction(kart);
    }
}

/** @param {import("../../core/kart-registry.js").Kart} kart @param {number} dt */
function UpdatePrediction(kart, dt) {
    if (PREDICTION_RENDER_MODE !== "dots") {
        HidePrediction(kart); // switched away from dots at runtime (hot reload) — don't leave them standing
    }
    if (!PREDICTION_ENABLED || !IsPredictionOn(kart) || kart.locked || kart.breaking || !kart.melon.IsValid()) {
        HidePrediction(kart);
        return;
    }
    const vel = kart.melon.GetAbsVelocity();
    const speed = Math.hypot(vel.x, vel.y);
    if (speed < PREDICTION_MIN_SPEED) {
        HidePrediction(kart);
        return;
    }
    const dir = { x: vel.x / speed, y: vel.y / speed };
    const center = kart.melon.GetAbsOrigin();
    const start = {
        x: center.x + dir.x * PREDICTION_START_OFFSET,
        y: center.y + dir.y * PREDICTION_START_OFFSET,
        z: center.z,
    };
    const ignoreEntity = [kart.melon, kart.pawn];

    const ahead = TraceAhead(center, dir, PREDICTION_LENGTH, ignoreEntity);
    const wallHit = IsWallHit(ahead);
    const end = ahead.didHit ? ahead.end : { x: center.x + dir.x * PREDICTION_LENGTH, y: center.y + dir.y * PREDICTION_LENGTH, z: center.z };

    let color = PREDICTION_NEUTRAL_COLOR;
    /** @type {any[]} */
    let outPoints = [];
    if (wallHit) {
        const nLen = Math.hypot(ahead.normal.x, ahead.normal.y) || 1;
        const n = { x: ahead.normal.x / nLen, y: ahead.normal.y / nLen };
        const into = -(dir.x * n.x + dir.y * n.y);
        if (into > 0) {
            const angle = (Math.acos(Math.min(1, into)) * 180) / Math.PI;
            color = GetBounceRating(WallAngleFactor(angle)).color;
            // Continue along the reflected direction, stopping at whatever
            // it would run into next.
            const out = { x: dir.x + 2 * into * n.x, y: dir.y + 2 * into * n.y };
            const back = TraceAhead(end, out, PREDICTION_REFLECT_LENGTH, ignoreEntity);
            const outEnd = back.didHit
                ? back.end
                : { x: end.x + out.x * PREDICTION_REFLECT_LENGTH, y: end.y + out.y * PREDICTION_REFLECT_LENGTH, z: end.z };
            outPoints = PointsAlong(end, outEnd, PREDICTION_DOTS_OUT);
        }
    }
    // The first leg starts at `start`, not the melon's center — skip the
    // leg entirely if the wall is closer than that.
    const firstLegLength = Math.hypot(end.x - center.x, end.y - center.y);
    const inPoints = firstLegLength > PREDICTION_START_OFFSET ? [start, ...PointsAlong(start, end, PREDICTION_DOTS_IN - 1)] : [];

    const dots = PREDICTION_RENDER_MODE === "dots" ? GetDots(kart) : null;
    if (!dots) {
        DrawDebugPrediction(start, end, inPoints.length > 0, outPoints, color, dt);
        return;
    }
    const inDots = dots.slice(0, PREDICTION_DOTS_IN);
    const outDots = dots.slice(PREDICTION_DOTS_IN);
    PlaceDots(inDots, inPoints, color);
    PlaceDots(outDots, outPoints, color);
}

/** @param {any[]} dots @param {any[]} points @param {{ r: number, g: number, b: number, a: number }} color */
function PlaceDots(dots, points, color) {
    for (let i = 0; i < dots.length; i++) {
        const dot = dots[i];
        if (i < points.length) {
            dot.Teleport({ position: points[i] });
            SetDotColor(dot, color);
        } else {
            SetDotColor(dot, HIDDEN_COLOR);
        }
    }
}

/**
 * Fallback when the map has no dot template — only visible in dev
 * environments (tools mode), see PREDICTION_DOT_TEMPLATE_NAME.
 * @param {any} start @param {any} end @param {boolean} drawFirstLeg @param {any[]} outPoints
 * @param {{ r: number, g: number, b: number, a: number }} color @param {number} dt
 */
function DrawDebugPrediction(start, end, drawFirstLeg, outPoints, color, dt) {
    // Slightly longer than one tick so the line doesn't flicker between
    // redraws, short enough not to leave a visible trail.
    const duration = Math.max(0.02, dt * 1.5);
    if (drawFirstLeg) {
        Instance.DebugLine({ start, end, duration, color });
    }
    if (outPoints.length > 0) {
        Instance.DebugLine({ start: end, end: outPoints[outPoints.length - 1], duration, color });
    }
}

// Pure rules of the heat flow (no engine calls) — see race-flow.js.

/**
 * The number the BREAK countdown under the FINISH image shows, `remaining`
 * seconds before the break ends: rounded, so it runs BREAK_SECONDS … 0 with
 * every number but the first and the last up for a full second (0 for the
 * break's last half second). Never below 0.
 * @param {number} remaining
 */
function BreakCountdownValue(remaining) {
    return Math.max(0, Math.round(remaining));
}

/**
 * The digit images that show `value`: tens undefined below 10 (no leading
 * zero), at most two digits (above 99 shows 99).
 * @param {number} value
 * @returns {{ tens: number | undefined, ones: number }}
 */
function CountdownDigits(value) {
    const clamped = Math.min(99, Math.max(0, Math.floor(value)));
    return { tens: clamped >= 10 ? Math.floor(clamped / 10) : undefined, ones: clamped % 10 };
}

// --- Race flow: hub -> countdown -> racing -> break --------------------
// See GAMEPLAY.md's "Hub -> race -> next-track flow" for the full design.
// Lives here (not a separate point_script) because it's tightly coupled to
// the same per-kart state as checkpoints/laps (the `Kart` typedef in
// core/kart-registry.js, and race/checkpoints/checkpoints.js).

/** @type {typeof RacePhase[keyof typeof RacePhase]} */
let phase = RacePhase.HUB;
/** Which track the current/last heat was run on — undefined while in HUB.
 * @type {number | undefined} */
let activeTrackId = undefined;
/** GetGameTime() at which the current COUNTDOWN/BREAK phase should end. */
let phaseEndTime = 0;

/** One class per countdown image on the HUD's countdown_panel (see
 * speedometer.xml/.css) — exactly one is set at a time. There's no image for
 * values above 3, so a COUNTDOWN_SECONDS > 3 shows nothing until 3.
 */
const COUNTDOWN_SHOW_CLASSES = ["Show3", "Show2", "Show1", "ShowGo"];

/** Number the BREAK countdown last sent to each slot — the digit images are
 * only re-sent when it changes (one class per image, see speedometer.xml).
 * @type {Map<number, number>} */
const breakCountdownShown = new Map();

/**
 * Shows `value` on one player's break_countdown (number-0..9 images, a tens
 * digit only from 10 up), or hides it with `value` undefined.
 * @param {number} slot @param {number | undefined} value
 */
function SetBreakCountdown(slot, value) {
    const hud = GetSpeedHud();
    if (value === undefined) {
        breakCountdownShown.delete(slot);
    } else {
        breakCountdownShown.set(slot, value);
    }
    const digits = value === undefined ? undefined : CountdownDigits(value);
    hud?.SetHasClassForPlayer(slot, "break_countdown", "Hidden", value === undefined);
    hud?.SetHasClassForPlayer(slot, "break_tens", "On", digits?.tens !== undefined);
    for (let d = 0; d <= 9; d++) {
        hud?.SetHasClassForPlayer(slot, `break_tens_${d}`, "On", digits?.tens === d);
        hud?.SetHasClassForPlayer(slot, `break_ones_${d}`, "On", digits?.ones === d);
    }
}

/**
 * Restores phase/activeTrackId/phaseEndTime from an OnScriptReload snapshot
 * (see index.js) — the counterpart write to these otherwise-internal `let`s
 * for the one caller outside this module that legitimately needs to set them.
 * @param {{ phase?: typeof RacePhase[keyof typeof RacePhase], activeTrackId?: number, phaseEndTime?: number } | undefined} snapshot
 */
function RestoreRaceFlowSnapshot(snapshot) {
    if (!snapshot) {
        return;
    }
    phase = snapshot.phase ?? phase;
    activeTrackId = snapshot.activeTrackId;
    phaseEndTime = snapshot.phaseEndTime ?? phaseEndTime;
}

function CurrentRacers() {
    return [...karts.values()].filter((kart) => kart.racing);
}

/** Track id after `activeTrackId` in race order, or undefined if it was the last one. */
function NextTrackId() {
    if (activeTrackId === undefined) {
        return undefined;
    }
    const order = GetTrackOrder();
    const index = order.indexOf(activeTrackId);
    if (index === -1 || index + 1 >= order.length) {
        return undefined;
    }
    return order[index + 1];
}

function TryStartRace() {
    if (phase !== RacePhase.HUB) {
        Debug("TryStartRace: ignored, a heat is already running");
        return;
    }
    const order = GetTrackOrder();
    if (order.length === 0) {
        Debug("TryStartRace: no start_<id> triggers found, ignoring");
        return;
    }
    const racers = [...karts.values()].filter((kart) => kart.inHub && kart.melon.IsValid());
    if (racers.length === 0) {
        Debug("TryStartRace: no karts currently in the hub trigger, ignoring");
        return;
    }
    for (const kart of racers) {
        kart.racing = true;
        const slot = kart.pawn.GetPlayerController()?.GetPlayerSlot();
        if (slot !== undefined) {
            HideHubModal(slot, kart);
        }
    }
    Debug(`TryStartRace: starting heat on track ${order[0]} with ${racers.length} racer(s)`);
    BeginHeat(order[0]);
}

// Moderator-only: cuts a heat short from wherever it's at (COUNTDOWN,
// RACING, or BREAK) and sends everyone back to the hub, same as a normal
// heat ending — see "Moderator" in GAMEPLAY.md.
function TryAbortRace() {
    if (phase === RacePhase.HUB) {
        Debug("TryAbortRace: ignored, no heat is running");
        return;
    }
    Debug(`TryAbortRace: moderator aborted the heat on track ${activeTrackId}`);
    ReturnAllToHub(CurrentRacers());
    phase = RacePhase.HUB;
    activeTrackId = undefined;
}

/**
 * Spot `i` of `count` karts lined up side by side, centered on `center` and
 * perpendicular to `angles`' facing — so a group teleported together doesn't
 * spawn inside each other. Keeps `center`'s height as-is.
 * @param {{ x: number, y: number, z: number }} center @param {{ yaw: number }} angles @param {number} i @param {number} count
 */
function LineUpPosition(center, angles, i, count) {
    const rad = (angles.yaw * Math.PI) / 180;
    const lateral = (i - (count - 1) / 2) * RACE_SPAWN_LATERAL_SPACING;
    return {
        x: center.x + Math.sin(rad) * lateral,
        y: center.y - Math.cos(rad) * lateral,
        z: center.z,
    };
}

/** @param {number} trackId */
function BeginHeat(trackId) {
    const config = GetTrackConfig()[trackId];
    const start = config && Instance.FindEntityByName(config.startEntityName);
    if (!start) {
        Debug(`BeginHeat: track ${trackId} has no start_${trackId} trigger, aborting heat back to HUB`);
        // Route through ReturnAllToHub, not a bare phase reset: callers
        // (TryStartRace, or the BREAK->next-heat transition) may already
        // have marked these karts racing/hidden their hub modal before
        // calling in here, and they'd otherwise be stranded with racing:true
        // and no hub UI, silently swept into whatever heat starts next.
        ReturnAllToHub(CurrentRacers());
        phase = RacePhase.HUB;
        activeTrackId = undefined;
        return;
    }
    activeTrackId = trackId;
    // start_spawn_<trackId> if placed, else the nearest start_spawn, else the start trigger itself.
    const { position: center, angles } = GetStartSpawnPoint(trackId, start);

    const racers = CurrentRacers();
    racers.forEach((kart, i) => {
        const position = LineUpPosition(center, angles, i, racers.length);
        SetFreeLook(kart, false); // a racer flying around would miss the countdown in a frozen melon
        // A melon destroyed mid-BREAK is still pending its respawn (see
        // HandleMelonLost) — skip the teleport rather than throw on a dead
        // entity; that respawn lands it at the checkpointPosition set below.
        if (kart.melon.IsValid()) {
            kart.melon.Teleport({
                position,
                angles,
                velocity: { x: 0, y: 0, z: 0 },
            });
        }
        kart.teleportGen = (kart.teleportGen ?? 0) + 1; // ?? 0: karts carried over a hot reload from before this field existed
        RestoreFullHealth(kart); // every heat starts on a whole melon
        kart.lastVelocity = undefined;
        kart.settled = false;
        kart.speedCap = undefined; // back to plain MAX_SPEED — no carrying a wall-bounce boost through a teleport
        kart.pendingBounce = undefined;
        // trackId is set directly instead of waiting for the physical
        // start_<trackId> trigger touch to report it, so the
        // checkpoint/lap panel is already visible ("0/N", lap "1/M") the
        // moment the countdown starts instead of popping in a tick later —
        // and crossing the start line after GO then changes nothing (see
        // ApplyStartTouch).
        kart.trackId = trackId;
        kart.checkpointIndex = 0;
        kart.lapsCompleted = 0;
        CancelRun(kart); // a free-roaming run doesn't carry into the heat — its clock starts at GO
        kart.finished = false;
        kart.locked = true;
        // Its own lined-up spot, not the start line's center — a respawn
        // before reaching checkpoint 1 (break, or the user menu's respawn
        // button during the countdown) would otherwise stack it on whoever
        // is standing in the middle.
        kart.checkpointPosition = position;
        kart.checkpointAngles = angles;
        FacePlayerView(kart.pawn, angles.yaw);
        SetFinishImageVisible(kart.pawn.GetPlayerController()?.GetPlayerSlot(), false);
    });

    phase = RacePhase.COUNTDOWN;
    phaseEndTime = Instance.GetGameTime() + COUNTDOWN_SECONDS;
    Debug(`BeginHeat: track ${trackId}, ${racers.length} racer(s), countdown started`);
}

/**
 * Shows or hides the big "FINISH" image (finish_image in speedometer.xml)
 * for one player. @param {number | undefined} slot @param {boolean} visible
 */
function SetFinishImageVisible(slot, visible) {
    if (slot !== undefined) {
        GetSpeedHud()?.SetHasClassForPlayer(slot, "finish_image", "Hidden", !visible);
    }
}

/** A kart reached lapsToWin — park it (still locked) until the whole heat ends. */
/** @param {import("../../core/kart-registry.js").Kart} kart */
function FinishKart(kart) {
    kart.finished = true;
    kart.locked = true;
    // Shown the moment this racer crosses the line, not only once the whole
    // heat is over — stays up through BREAK until the next heat/the hub.
    SetFinishImageVisible(kart.pawn.GetPlayerController()?.GetPlayerSlot(), true);
    Debug(`FinishKart: slot ${kart.pawn.GetPlayerController()?.GetPlayerSlot()} finished track ${activeTrackId}`);
}

/** @param {import("../../core/kart-registry.js").Kart[]} returning */
function ReturnAllToHub(returning) {
    SendKartsOutOfRace(returning, GetHubSpawnPoint(), "hub");
}

/**
 * The user menu's "Play Tutorial": same as the hub button (leaves a
 * running heat, respawn point moves along), just landing at intro_spawn —
 * or the hub, if the map has no intro_spawn.
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function SendKartToTutorial(kart) {
    SendKartsOutOfRace([kart], GetIntroSpawnPoint(), "tutorial");
}

/**
 * Takes karts out of any heat and teleports them (lined up side by side)
 * to `spawn`, which also becomes their respawn point.
 * @param {import("../../core/kart-registry.js").Kart[]} returning
 * @param {import("../../kart/spawn-points.js").SpawnPoint | undefined} spawn where to put them
 * @param {string} label for the debug log
 */
function SendKartsOutOfRace(returning, spawn, label) {
    Debug(`SendKartsOutOfRace: sending ${returning.length} kart(s) to the ${label} at ${spawn ? JSON.stringify(spawn.position) : "nowhere (spawn entity missing)"}`);
    returning.forEach((kart, i) => {
        kart.racing = false;
        kart.finished = false;
        kart.locked = false;
        // kart.inHub (and the hub modal) is deliberately left to the
        // hub_start_trigger's own hub_enter/hub_leave inputs: the teleport
        // below lands inside it and fires hub_enter from there. Forcing it
        // here left inHub stuck at true whenever the melon ended up outside
        // the trigger volume — hub_leave never fires for a trigger that was
        // never entered — and that kart then got pulled into the next heat
        // from anywhere on the map.
        // Leaving the heat also leaves its track: without this the HUD kept
        // showing the old track's checkpoint/lap panel in the hub, and a
        // break or the user menu's respawn button would send the kart right
        // back onto that track's last checkpoint.
        kart.trackId = undefined;
        kart.checkpointIndex = 0;
        kart.lapsCompleted = 0;
        CancelRun(kart);
        if (spawn) {
            const spawnAngles = spawn.angles;
            const spawnPosition = LineUpPosition(spawn.position, spawnAngles, i, returning.length);
            kart.checkpointPosition = spawnPosition;
            kart.checkpointAngles = spawnAngles;
            FacePlayerView(kart.pawn, spawnAngles.yaw);
            // Same dead-melon guard as BeginHeat — its pending respawn lands
            // it at the checkpointPosition just set.
            if (kart.melon.IsValid()) {
                kart.melon.Teleport({
                    position: spawnPosition,
                    angles: spawnAngles,
                    velocity: { x: 0, y: 0, z: 0 },
                });
            }
        }
        kart.teleportGen = (kart.teleportGen ?? 0) + 1; // ?? 0: karts carried over a hot reload from before this field existed
        // Arrives whole — hub/tutorial button, hub_teleport, a heat ending.
        RestoreFullHealth(kart);
        kart.lastVelocity = undefined;
        kart.settled = false;
        kart.speedCap = undefined; // back to plain MAX_SPEED — no carrying a wall-bounce boost through a teleport
        kart.pendingBounce = undefined;
        const slot = kart.pawn.GetPlayerController()?.GetPlayerSlot();
        if (slot === undefined) {
            return;
        }
        // Both labels, since ReturnAllToHub can now be reached from any
        // non-HUB phase (a moderator abort can land mid-COUNTDOWN, not just
        // after a heat finishes normally in BREAK).
        GetSpeedHud()?.SetHasClassForPlayer(slot, "countdown_panel", "Hidden", true);
        SetBreakCountdown(slot, undefined);
        SetFinishImageVisible(slot, false);
    });
}

/** Drives the COUNTDOWN/RACING/BREAK timers and transitions — called once per Think tick (see core/think.js). */
/** @param {number} now */
function UpdateRaceFlow(now) {
    const hud = GetSpeedHud();

    if (phase === RacePhase.COUNTDOWN) {
        const racers = CurrentRacers();
        if (racers.length === 0) {
            // Everyone who was in this heat disconnected/despawned before it
            // even started — nothing left to count down for. Without this,
            // the countdown would still finish into RACING below and then
            // get permanently stuck there (see the RACING branch's own
            // "nobody left" check), bricking the race flow for everyone.
            Debug("UpdateRaceFlow: all racers left during countdown, aborting heat back to HUB");
            phase = RacePhase.HUB;
            activeTrackId = undefined;
            return;
        }
        const remaining = phaseEndTime - now;
        const showClass = remaining > 0 ? `Show${Math.ceil(remaining)}` : "ShowGo";
        for (const kart of racers) {
            const slot = kart.pawn.GetPlayerController()?.GetPlayerSlot();
            if (slot === undefined) {
                continue;
            }
            hud?.SetHasClassForPlayer(slot, "countdown_panel", "Hidden", false);
            for (const cls of COUNTDOWN_SHOW_CLASSES) {
                hud?.SetHasClassForPlayer(slot, "countdown_panel", cls, cls === showClass);
            }
        }
        if (remaining <= 0) {
            for (const kart of racers) {
                kart.locked = false;
                StartRun(kart, now); // the heat's time trial clock
            }
            // The "GO" image just shown above stays up for GO_DISPLAY_SECONDS —
            // hiding it in this same tick meant it was never actually seen.
            // RACING reuses phaseEndTime as the moment to hide it.
            phase = RacePhase.RACING;
            phaseEndTime = now + GO_DISPLAY_SECONDS;
            Debug(`UpdateRaceFlow: countdown finished for track ${activeTrackId}, GO`);
        }
        return;
    }

    if (phase === RacePhase.RACING) {
        const racers = CurrentRacers();
        if (now >= phaseEndTime) {
            for (const kart of racers) {
                const slot = kart.pawn.GetPlayerController()?.GetPlayerSlot();
                if (slot !== undefined) {
                    hud?.SetHasClassForPlayer(slot, "countdown_panel", "Hidden", true);
                }
            }
            phaseEndTime = Infinity; // hidden — don't re-hide every tick
        }
        if (racers.length === 0) {
            // Same "everyone left" case as COUNTDOWN above, but mid-race:
            // without this, an empty heat sits in RACING forever since
            // `racers.every(...)` on an empty array is vacuously true only
            // when length is also checked, and TryStartRace refuses to start
            // a new heat while phase isn't HUB.
            Debug("UpdateRaceFlow: all racers left mid-heat, aborting back to HUB");
            phase = RacePhase.HUB;
            activeTrackId = undefined;
            return;
        }
        if (racers.every((kart) => kart.finished)) {
            phase = RacePhase.BREAK;
            phaseEndTime = now + BREAK_SECONDS;
            // The countdown itself is drawn by the BREAK branch below, under
            // the finish_image FinishKart already shows.
            breakCountdownShown.clear();
            Debug(`UpdateRaceFlow: heat on track ${activeTrackId} complete, break started`);
        }
        return;
    }

    if (phase === RacePhase.BREAK && now < phaseEndTime) {
        // Counting down to the next track / the hub: BREAK_SECONDS … 0 in
        // number images under the finish image, re-sent only on change.
        const value = BreakCountdownValue(phaseEndTime - now);
        for (const kart of CurrentRacers()) {
            const slot = kart.pawn.GetPlayerController()?.GetPlayerSlot();
            if (slot !== undefined && breakCountdownShown.get(slot) !== value) {
                SetBreakCountdown(slot, value);
            }
        }
        return;
    }

    if (phase === RacePhase.BREAK) {
        const racers = CurrentRacers();
        const nextTrackId = NextTrackId();
        if (nextTrackId !== undefined) {
            for (const kart of racers) {
                const slot = kart.pawn.GetPlayerController()?.GetPlayerSlot();
                if (slot !== undefined) {
                    SetBreakCountdown(slot, undefined);
                }
            }
            BeginHeat(nextTrackId);
        } else {
            ReturnAllToHub(racers);
            phase = RacePhase.HUB;
            activeTrackId = undefined;
            Debug("UpdateRaceFlow: last track done, group returned to hub");
        }
    }
}

// Pure checkpoint/lap progression rules — no cs_script import, so they're
// unit-testable in Node (see test/race/checkpoint-progress.test.mjs).
// race/checkpoints/checkpoints.js wires these to the start_<trackId> /
// checkpoint / finish_<trackId> script inputs and handles
// the engine side (respawn position, FinishKart, debug logging). See
// "Multiple tracks & checkpoints" in GAMEPLAY.md for the design.
//
// The three Apply* functions mutate the kart's progress fields in place and
// return what happened, so the caller can log it and react (e.g. call FinishKart).


/**
 * start_line: the track a start trigger belongs to, from its name
 * ("start_2", "start_2_laps3" -> 2). Undefined for any other name.
 * @param {string} triggerName
 * @returns {number | undefined}
 */
function StartLineTrackId(triggerName) {
    const m = START_TRIGGER_NAME_PATTERN.exec(triggerName.trim());
    return m ? Number(m[1]) : undefined;
}

/**
 * finish_line: the track a finish line belongs to, from the firing
 * trigger's name — "finish_2" (point-to-point), or a start trigger's name
 * (a loop track's shared start/finish line). Undefined for any other name.
 * @param {string} triggerName
 * @returns {number | undefined}
 */
function FinishLineTrackId(triggerName) {
    const m = FINISH_TRIGGER_NAME_PATTERN.exec(triggerName.trim());
    return m ? Number(m[1]) : StartLineTrackId(triggerName);
}

/**
 * checkpoint: which checkpoint a trigger is, from its name
 * ("checkpoint_2_3" -> track 2, 3rd checkpoint). Undefined for any other name.
 * @param {string} triggerName
 * @returns {{ trackId: number, index: number } | undefined}
 */
function CheckpointFromTrigger(triggerName) {
    const m = CHECKPOINT_TRIGGER_NAME_PATTERN.exec(triggerName.trim());
    return m ? { trackId: Number(m[1]), index: Number(m[2]) } : undefined;
}

/**
 * @typedef {{ trackId: number | undefined, checkpointIndex: number, lapsCompleted: number, racing: boolean, finished: boolean }} KartProgress
 * @typedef {{ checkpoints: number, lapsToWin: number }} TrackRules
 * @typedef {{ activeTrackId: number | undefined, config: TrackRules | undefined }} ProgressContext
 *   config is the touched track's own config (undefined if the map has no
 *   start_* trigger for it)
 */

/**
 * @typedef {"ignored-finished" | "ignored-other-track" | "ignored-incomplete" | "lap" | "finished"} LapResult
 *   "finished" = that lap was the kart's last one — the run is over: the
 *   caller stops its clock and, in a heat, must FinishKart it.
 */

/**
 * finish_<trackId>: counts a completed lap if the kart is on this track (in
 * a heat: racing the heat's track) and has reached its last checkpoint
 * since the previous lap. Counts outside a heat too — a free-roaming run is
 * a time trial (see race/time-trial/time-trial.js).
 * @param {KartProgress} kart @param {number} trackId @param {ProgressContext} ctx
 * @returns {LapResult}
 */
function ApplyLapCompletion(kart, trackId, ctx) {
    if (kart.finished) {
        return "ignored-finished"; // already parked after finishing this heat
    }
    if (kart.trackId !== trackId || (kart.racing && trackId !== ctx.activeTrackId)) {
        return "ignored-other-track";
    }
    if (!ctx.config || kart.checkpointIndex < ctx.config.checkpoints) {
        return "ignored-incomplete";
    }
    kart.lapsCompleted += 1;
    if (kart.lapsCompleted >= ctx.config.lapsToWin) {
        return "finished";
    }
    // Not done yet — back to "no checkpoints reached" for the next lap.
    kart.checkpointIndex = 0;
    return "lap";
}

/**
 * @typedef {"ignored-finished" | "ignored-foreign-start" | "ignored-mid-lap" | "picked" | "lap" | "finished"} StartResult
 *   "picked" = a new run on this track starts here, no checkpoints reached
 *   (the caller starts its clock); "lap" = a lap counted, next one started;
 *   "finished" = ...and it was the kart's last one — the run is over (see
 *   LapResult). "picked"/"lap" make the start the kart's respawn point.
 */

/**
 * start_<trackId>: the start line.
 *
 * A kart isn't on any track until it crosses a start line, which picks
 * (starts its progress on) that track. Outside a heat, crossing it again
 * before checkpoint 1 starts the run over (e.g. after respawning behind the
 * line). A racing kart can't pick a
 * *different* track's start mid-heat — that would silently overwrite
 * kart.trackId to the wrong track and then reject the racer's own further
 * progress on their actual active track. (A heat puts its racers on the
 * track itself, see BeginHeat, so crossing the line right after the
 * countdown changes nothing.)
 *
 * On a loop track start_ and finish_ sit on the same trigger, and Hammer
 * doesn't guarantee which fires first — so crossing the start with the whole
 * lap already run counts the lap right here (via ApplyLapCompletion);
 * finish_<trackId> firing afterwards then sees no checkpoints reached and is
 * ignored. A track without checkpoints never counts a lap here (it would
 * count the very first crossing) — only finish_ does, so a point-to-point
 * track needs none.
 * @param {KartProgress} kart @param {number} trackId @param {ProgressContext} ctx
 * @returns {StartResult}
 */
function ApplyStartTouch(kart, trackId, ctx) {
    if (kart.finished) {
        return "ignored-finished"; // parked after finishing this heat
    }
    if (kart.racing && trackId !== ctx.activeTrackId) {
        return "ignored-foreign-start";
    }
    const freshStart = !kart.racing && kart.checkpointIndex === 0 && kart.lapsCompleted === 0;
    if (kart.trackId !== trackId || freshStart) {
        kart.trackId = trackId;
        kart.checkpointIndex = 0;
        kart.lapsCompleted = 0;
        return "picked";
    }
    if (!ctx.config || ctx.config.checkpoints === 0 || kart.checkpointIndex < ctx.config.checkpoints) {
        return "ignored-mid-lap"; // doubling back over the line must not reset progress
    }
    // Can only be "lap" or "finished" here: the kart is on this track (a
    // racing one on the heat's, see above) with the whole lap run.
    return ApplyLapCompletion(kart, trackId, ctx) === "finished" ? "finished" : "lap";
}

/**
 * @typedef {"ignored-finished" | "ignored-other-track" | "ignored-skipped" | "ignored-behind" | "advanced"} CheckpointResult
 *   Only "advanced" moved checkpointIndex forward, i.e. the touched
 *   checkpoint is the kart's new respawn point.
 */

/**
 * checkpoint_<trackId>_<index>.
 *
 * Only counts while the kart is on that same track (picked by its start
 * line, start_<trackId>), and only ever moves progress forward, one
 * checkpoint at a time (no skipping ahead).
 * @param {KartProgress} kart @param {number} trackId @param {number} index
 * @returns {CheckpointResult}
 */
function ApplyCheckpointTouch(kart, trackId, index) {
    if (kart.finished) {
        return "ignored-finished"; // parked after finishing this heat
    }
    if (kart.trackId !== trackId) {
        return "ignored-other-track";
    }
    // Strictly the next checkpoint in sequence — skipping ahead (e.g. 1 -> 5
    // via a shortcut) must not count, or touching just the last checkpoint
    // would be enough for finish_<trackId> to accept the lap.
    if (index !== kart.checkpointIndex + 1) {
        return index > kart.checkpointIndex ? "ignored-skipped" : "ignored-behind";
    }
    kart.checkpointIndex = index;
    return "advanced";
}

// Start line: a trigger_multiple named "start_<trackId>[_laps<M>]",
// filtered to the melon (prop_physics) so the frozen/parked pawn can't
// trigger it, with its OnStartTouch calling this point_script's
// RunScriptInput with parameter "start_<trackId>" — puts the melon on that
// track and makes the start its respawn point: the info_target named
// "start_spawn_<trackId>" (also where a heat lines racers up), else the
// nearest "start_spawn", else the trigger's own position/angles (see
// GetStartSpawnPoint). The output may fire the generic "start_line" instead,
// which takes the track from the trigger's name — for a start gate prefab,
// whose trigger name is a prefab variable but whose output is fixed.
//
// Checkpoints: a trigger_multiple per checkpoint along the track, named
// "checkpoint_<trackId>_<index>" — e.g. track 2's 3rd checkpoint is
// "checkpoint_2_3", counted from 1 after the start line — with
// OnStartTouch -> RunScriptInput "checkpoint", which reads the checkpoint
// from that name. If the melon breaks
// after reaching it, it respawns at the info_target named
// "checkpoint_spawn_<trackId>_<index>", facing that entity's yaw — else at
// the nearest "checkpoint_spawn" (a checkpoint gate prefab's), else at the
// trigger's own position/angles.
//
// The progression rules themselves (which touch counts, one checkpoint at
// a time, the start picks the track, lap counting on a start re-touch) live
// in race/checkpoints/logic.js so they can be unit-tested without the
// engine — this is just the engine side around them.
/** @param {number} trackId @param {number} index @param {import("../../core/kart-registry.js").Kart} kart @param {any} trigger */
function OnCheckpointTouched(trackId, index, kart, trigger) {
    const result = ApplyCheckpointTouch(kart, trackId, index);
    switch (result) {
        case "ignored-finished":
        case "ignored-behind":
            return;
        case "ignored-other-track":
            Debug(`checkpoint_${trackId}_${index}: kart is on track ${kart.trackId}, ignoring (start_${trackId} not crossed)`);
            return;
        case "ignored-skipped":
            Debug(`checkpoint_${trackId}_${index}: kart is at checkpoint ${kart.checkpointIndex}, skipped one — ignoring`);
            return;
    }
    const spawn = GetCheckpointSpawnPoint(trackId, index, trigger);
    if (spawn) {
        kart.checkpointPosition = spawn.position;
        kart.checkpointAngles = spawn.angles;
    } else {
        Debug(`checkpoint_${trackId}_${index}: no info_target "checkpoint_spawn_${trackId}_${index}" or "checkpoint_spawn" nearby, respawning at the trigger itself`);
        // + TELEPORT_UP_OFFSET for the same reason BeginHeat adds
        // it to their teleport targets: mappers commonly sink a checkpoint
        // trigger's brush into the floor so a fast-moving melon reliably
        // touches it, and teleporting to that exact (embedded) height would
        // otherwise make a later respawn (e.g. after BreakMelon) tunnel the
        // melon down through the floor instead of landing on it.
        kart.checkpointPosition = Lifted(trigger.GetAbsOrigin(), TELEPORT_UP_OFFSET);
        // Only the yaw, like every other spawn: a rotated brush mustn't respawn the melon tilted.
        kart.checkpointAngles = LevelAngles(trigger.GetAbsAngles().yaw);
    }
    Debug(`checkpoint_${trackId}_${index}: kart advanced to checkpoint ${index} on track ${trackId}`);
}

/** @param {number} trackId @param {import("../../core/kart-registry.js").Kart} kart @param {any} trigger */
function OnStartTouched(trackId, kart, trigger) {
    if (kart.finishRestartAt !== undefined && Instance.GetGameTime() - kart.finishRestartAt < FINISH_RESTART_START_GUARD) {
        // The same loop-finish touch whose finish_ already sent the melon back
        // to the start spawn (see CompleteRun) — not a new crossing.
        Debug(`start_${trackId}: right after the finish sent the melon back to the start, ignoring`);
        return;
    }
    const config = GetTrackConfig()[trackId];
    const result = ApplyStartTouch(kart, trackId, { activeTrackId, config });
    switch (result) {
        case "ignored-finished":
        case "ignored-mid-lap":
            return;
        case "ignored-foreign-start":
            Debug(`start_${trackId}: kart is racing active track ${activeTrackId}, ignoring foreign track's start`);
            return;
        case "finished":
            LogLapCompleted(trackId, kart, config);
            CompleteRun(trackId, kart);
            return;
        case "lap":
            LogLapCompleted(trackId, kart, config);
            break;
        case "picked":
            if (!kart.racing) {
                StartRun(kart); // a heat's clock starts at GO instead
            }
            break;
    }
    // Respawn at the start (start_spawn_<trackId>, else the trigger) until
    // the first checkpoint.
    const spawn = GetStartSpawnPoint(trackId, trigger);
    kart.checkpointPosition = spawn.position;
    kart.checkpointAngles = spawn.angles;
    Debug(`start_${trackId}: kart ${result === "picked" ? "is now on" : "starts a new lap on"} track ${trackId}`);
}

/**
 * The kart's last lap is done: stops its run clock (recording a best time),
 * then parks it if it's in a heat — or, free-roaming, sends it straight back
 * to the track's start spawn for the next attempt (the finish time stays on
 * the HUD; the clock starts again on crossing the start line).
 * @param {number} trackId @param {import("../../core/kart-registry.js").Kart} kart
 */
function CompleteRun(trackId, kart) {
    FinishRun(kart, trackId);
    if (kart.racing) {
        FinishKart(kart);
        return;
    }
    if (SendToTrackStart(kart, trackId)) {
        kart.finishRestartAt = Instance.GetGameTime();
        return;
    }
    // No start trigger to go back to (can't happen for a track that was
    // picked by one): off the track until a start line is crossed again.
    kart.trackId = undefined;
    kart.checkpointIndex = 0;
    kart.lapsCompleted = 0;
}

/**
 * Puts the kart back at the start of `trackId` — on the track, no
 * checkpoints or laps, the start spawn its respawn point — and the melon
 * there, whole and standing still (a breaking melon is left to its own
 * respawn, which now goes there too). The run clock isn't touched.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {number} trackId
 * @returns {boolean} false if the track has no start trigger
 */
function SendToTrackStart(kart, trackId) {
    const config = GetTrackConfig()[trackId];
    const trigger = config && Instance.FindEntityByName(config.startEntityName);
    if (!trigger) {
        Debug(`SendToTrackStart: track ${trackId} has no start_${trackId} trigger`);
        return false;
    }
    const spawn = GetStartSpawnPoint(trackId, trigger);
    kart.trackId = trackId;
    kart.checkpointIndex = 0;
    kart.lapsCompleted = 0;
    kart.checkpointPosition = spawn.position;
    kart.checkpointAngles = spawn.angles;
    if (!kart.breaking) {
        kart.teleportGen = (kart.teleportGen ?? 0) + 1;
        RespawnKartAtCheckpoint(kart);
    }
    return true;
}

// Finish: add an OnStartTouch output, RunScriptInput with parameter
// "finish_<trackId>", to whichever trigger_multiple physically sits on that
// track's finish line — on a loop track that's the start_<trackId> trigger
// itself (start and finish are the same line), on a point-to-point track its
// own trigger at the end; only the activator (the melon) is read here, not
// which entity fired it. Filtered to prop_physics like the checkpoints.
// Or the generic "finish_line", which takes the track from the firing
// trigger's name instead: "finish_<trackId>", or the start trigger's own
// name on a loop track — for a finish gate prefab.
// Kept a separate input from start_<trackId> so a track can end somewhere
// else than it starts; on a shared trigger either one may fire first (see
// ApplyStartTouch). See "Hub -> race -> next-track flow" in GAMEPLAY.md.
/** @param {number} trackId @param {import("../../core/kart-registry.js").Kart} kart */
function OnFinishTouched(trackId, kart) {
    const config = GetTrackConfig()[trackId];
    const result = ApplyLapCompletion(kart, trackId, { activeTrackId, config });
    switch (result) {
        case "ignored-finished":
            return;
        case "ignored-other-track":
            Debug(
                `finish_${trackId}: kart isn't on this track ` +
                `(racing=${kart.racing}, trackId=${kart.trackId}, activeTrackId=${activeTrackId}), ignoring`
            );
            return;
        case "ignored-incomplete":
            Debug(`finish_${trackId}: kart hasn't reached all ${config?.checkpoints ?? "?"} checkpoint(s) this lap yet (at ${kart.checkpointIndex}), ignoring`);
            return;
        case "lap":
            LogLapCompleted(trackId, kart, config);
            return;
        case "finished":
            LogLapCompleted(trackId, kart, config);
            CompleteRun(trackId, kart);
            return;
    }
}

/** @param {number} trackId @param {import("../../core/kart-registry.js").Kart} kart @param {{ lapsToWin: number } | undefined} config */
function LogLapCompleted(trackId, kart, config) {
    Debug(`finish_${trackId}: lap ${kart.lapsCompleted}/${config?.lapsToWin ?? "?"} completed on track ${trackId}`);
}

/**
 * The user menu's "Restart Time Trial": back to the track's start spawn,
 * whole and standing still, clock at zero — it starts again on crossing the
 * start line. Ignored while the melon is breaking (its respawn is already
 * under way) or locked.
 * @param {import("../../core/kart-registry.js").Kart} kart
 * @returns {boolean} whether it restarted
 */
function RestartTimeTrial(kart) {
    const trackId = kart.trackId;
    if (!CanRestartTimeTrial(kart) || trackId === undefined || kart.breaking || kart.locked) {
        Debug(`RestartTimeTrial: not now (trackId=${trackId}, racing=${kart.racing}, breaking=${kart.breaking}, locked=${kart.locked})`);
        return false;
    }
    if (!SendToTrackStart(kart, trackId)) {
        return false;
    }
    CancelRun(kart);
    kart.lastRun = undefined;
    Debug(`RestartTimeTrial: back to the start of track ${trackId}`);
    return true;
}

/**
 * The track a start_line / finish_line input is for, from the firing
 * trigger's name — undefined (logged) for a name that names no track or one
 * beyond MAX_TRACKS (the numbered inputs don't go further either).
 * @param {string} input @param {any} caller @param {(name: string) => number | undefined} parse
 */
function TrackIdFromCaller(input, caller, parse) {
    const name = caller?.GetEntityName() ?? "";
    const trackId = parse(name);
    if (trackId === undefined || trackId < 1 || trackId > MAX_TRACKS) {
        Instance.Msg(`[melon_drive] ${input} fired by "${name}", which names no track 1..${MAX_TRACKS} — ignoring. See docs/mapping-api/04-tracks.md.`);
        return undefined;
    }
    return trackId;
}

/** Registers the start_<trackId> and finish_<trackId> OnScriptInput handlers for every track the map is allowed to use, plus the generic start_line / finish_line and checkpoint. Called once from index.js. */
function RegisterCheckpointAndFinishInputs() {
    Instance.OnScriptInput("start_line", ({ caller, activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart || !caller) {
            Debug("start_line: activator wasn't a tracked melon, ignoring");
            return;
        }
        const trackId = TrackIdFromCaller("start_line", caller, StartLineTrackId);
        if (trackId !== undefined) {
            OnStartTouched(trackId, kart, caller);
        }
    });
    Instance.OnScriptInput("finish_line", ({ caller, activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart) {
            Debug("finish_line: activator wasn't a tracked melon, ignoring");
            return;
        }
        const trackId = TrackIdFromCaller("finish_line", caller, FinishLineTrackId);
        if (trackId !== undefined) {
            OnFinishTouched(trackId, kart);
        }
    });

    for (let t = 1; t <= MAX_TRACKS; t++) {
        const trackId = t;
        Instance.OnScriptInput(`start_${trackId}`, ({ caller, activator }) => {
            const kart = activator && FindKartByMelon(activator);
            if (!kart || !caller) {
                Debug(`start_${trackId}: activator wasn't a tracked melon, ignoring`);
                return;
            }
            OnStartTouched(trackId, kart, caller);
        });
    }

    Instance.OnScriptInput("checkpoint", ({ caller, activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart || !caller) {
            Debug("checkpoint: activator wasn't a tracked melon, ignoring");
            return;
        }
        const name = caller.GetEntityName();
        const checkpoint = CheckpointFromTrigger(name);
        if (!checkpoint || checkpoint.trackId < 1 || checkpoint.trackId > MAX_TRACKS || checkpoint.index < 1 || checkpoint.index > MAX_CHECKPOINTS_PER_TRACK) {
            Instance.Msg(`[melon_drive] checkpoint fired by "${name}", which isn't named checkpoint_<trackId 1..${MAX_TRACKS}>_<index 1..${MAX_CHECKPOINTS_PER_TRACK}> — ignoring. See docs/mapping-api/04-tracks.md.`);
            return;
        }
        OnCheckpointTouched(checkpoint.trackId, checkpoint.index, kart, caller);
    });

    for (let t = 1; t <= MAX_TRACKS; t++) {
        const trackId = t;
        Instance.OnScriptInput(`finish_${trackId}`, ({ activator }) => {
            const kart = activator && FindKartByMelon(activator);
            if (!kart) {
                Debug(`finish_${trackId}: activator wasn't a tracked melon, ignoring`);
                return;
            }
            OnFinishTouched(trackId, kart);
        });
    }
}

// User menu: press USE anywhere (regardless of race phase) to open a small
// panel with actions/settings that aren't tied to any single map trigger —
// currently "respawn at last checkpoint" and a color picker, with room to
// add more rows later (see "usermenu_*" buttonId handling in hud/inputs.js's
// OnCustomHudClicked). Deliberately independent of kart.locked/breaking so
// it also works as an unstuck button while the melon is frozen.
/** @param {number} slot @param {import("../core/kart-registry.js").Kart} kart @param {boolean} open */
function SetUserMenuOpen(slot, kart, open) {
    kart.userMenuOpen = open;
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    hud.SetHasClassForPlayer(slot, "user_menu", "Hidden", !open);
    if (open) {
        // Refreshed on every open: a layout or script reload in tools mode
        // wipes what was set when the kart spawned.
        UpdateMelonGlowHud(slot, kart);
        UpdatePredictionHud(slot, kart);
        UpdateCollisionDebugHud(slot, kart);
        UpdateFreeLookHud(slot, kart);
    }
    SyncInputCapture(hud, slot, kart);
}

/**
 * The user menu's glow toggle button: its ON/OFF text and highlight.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 */
function UpdateMelonGlowHud(slot, kart) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    const on = IsMelonGlowOn(kart);
    hud.SetDialogVariableStringForPlayer(slot, "usermenu_glow_button", "glow_state", on ? "ON" : "OFF");
    hud.SetHasClassForPlayer(slot, "usermenu_glow_button", "ToggleOn", on);
}

/**
 * The user menu's guide line (prediction line) toggle button: its ON/OFF
 * text and highlight.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 */
function UpdatePredictionHud(slot, kart) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    const on = IsPredictionOn(kart);
    hud.SetDialogVariableStringForPlayer(slot, "usermenu_prediction_button", "prediction_state", on ? "ON" : "OFF");
    hud.SetHasClassForPlayer(slot, "usermenu_prediction_button", "ToggleOn", on);
}

/**
 * The user menu's collision debug toggle button: its ON/OFF text and highlight.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 */
function UpdateCollisionDebugHud(slot, kart) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    const on = IsCollisionDebugOn(kart);
    hud.SetDialogVariableStringForPlayer(slot, "usermenu_collisiondebug_button", "collisiondebug_state", on ? "ON" : "OFF");
    hud.SetHasClassForPlayer(slot, "usermenu_collisiondebug_button", "ToggleOn", on);
}

/**
 * The user menu's free look toggle button: its ON/OFF text and highlight.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 */
function UpdateFreeLookHud(slot, kart) {
    const hud = GetSpeedHud();
    if (!hud) {
        return;
    }
    const on = IsFreeLookOn(kart);
    hud.SetDialogVariableStringForPlayer(slot, "usermenu_freelook_button", "freelook_state", on ? "ON" : "OFF");
    hud.SetHasClassForPlayer(slot, "usermenu_freelook_button", "ToggleOn", on);
}

/** @param {number} slot @param {import("../core/kart-registry.js").Kart} kart */
function UpdateUserMenu(slot, kart) {
    if (kart.pawn.WasInputJustPressed(CSInputs.USE)) {
        SetUserMenuOpen(slot, kart, !kart.userMenuOpen);
    }
    // Shortcut for the menu's "Restart Time Trial" button: reload (R), menu
    // open or not, so a bad start costs one key instead of USE + a click.
    // Pressed outside a time trial it does nothing.
    if (kart.pawn.WasInputJustPressed(CSInputs.RELOAD) && CanRestartTimeTrial(kart) && RestartTimeTrial(kart)) {
        if (kart.userMenuOpen) {
            SetUserMenuOpen(slot, kart, false);
        }
    }
    if (kart.userMenuOpen) {
        // Every tick while open: the time trial can start or end (finish,
        // a heat, the hub) with the menu up.
        GetSpeedHud()?.SetHasClassForPlayer(slot, "usermenu_restart_row", "Hidden", !CanRestartTimeTrial(kart));
    }
}

// Every button click in the HUD layout (OnCustomHudClicked): the hub modal's
// start/close/abort buttons and the user menu's rows.

function RegisterHudInputs() {
    Instance.OnCustomHudClicked((event) => {
        if (event.layout !== GetSpeedHud()) {
            return;
        }
        if (event.buttonId === "hub_start_button") {
            TryStartRace();
        } else if (event.buttonId === "hub_close_button") {
            // Dismiss just for the player who clicked it — doesn't touch
            // kart.inHub, so they're still pulled into the next heat that starts
            // while they're standing in hub_start_trigger, same as before.
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (kart) {
                HideHubModal(slot, kart);
            }
        } else if (event.buttonId === "hub_abort_button") {
            const slot = event.player.GetPlayerSlot();
            if (IsModerator(slot)) {
                TryAbortRace();
            } else {
                Debug(`hub_abort_button: slot ${slot} clicked but isn't the moderator, ignoring`);
            }
        } else if (event.buttonId === "usermenu_close_button") {
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (kart) {
                SetUserMenuOpen(slot, kart, false);
            }
        } else if (event.buttonId === "usermenu_respawn_button") {
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (!kart) {
                return;
            }
            if (kart.breaking) {
                // Already mid-respawn from a break — it's about to land at this
                // same checkpoint on its own, nothing for this click to do.
                Debug(`usermenu_respawn_button: slot ${slot} kart is already breaking/respawning, ignoring`);
                return;
            }
            if (kart.locked) {
                // Held on the start grid for the countdown, or parked after
                // finishing — it isn't going anywhere that respawning would fix,
                // and mid-countdown it'd just teleport a racer around the grid.
                Debug(`usermenu_respawn_button: slot ${slot} kart is locked, ignoring`);
                return;
            }
            RespawnKartAtCheckpoint(kart);
            SetUserMenuOpen(slot, kart, false);
        } else if (event.buttonId === "usermenu_restart_button") {
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (kart && RestartTimeTrial(kart)) {
                SetUserMenuOpen(slot, kart, false);
            }
        } else if (event.buttonId === "usermenu_hub_button") {
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (!kart) {
                return;
            }
            // Self-service pull-out: just this racer leaves the heat, everyone
            // else keeps going — unlike hub_abort_button, which is moderator-only
            // and ends it for the whole group. ReturnAllToHub already supports a
            // single-kart list (it's the same path a disconnecting racer takes).
            Debug(`usermenu_hub_button: slot ${slot} returning to hub (racing=${kart.racing}, phase=${phase})`);
            SetUserMenuOpen(slot, kart, false);
            ReturnAllToHub([kart]);
        } else if (event.buttonId === "usermenu_tutorial_button") {
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (!kart) {
                return;
            }
            // Same self-service pull-out as the hub button above, to intro_spawn.
            Debug(`usermenu_tutorial_button: slot ${slot} going to the tutorial (racing=${kart.racing}, phase=${phase})`);
            SetUserMenuOpen(slot, kart, false);
            SendKartToTutorial(kart);
        } else if (event.buttonId === "usermenu_glow_button") {
            // Per player: only this player's own melon (everyone still sees
            // whatever glow a melon has — the engine's Glow isn't per viewer).
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (kart) {
                SetMelonGlow(kart, !IsMelonGlowOn(kart));
                UpdateMelonGlowHud(slot, kart);
            }
        } else if (event.buttonId === "usermenu_prediction_button") {
            // Per player: only this player's melon gets the line (drawn with
            // DebugLine in the default render mode, so tools mode only).
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (kart) {
                SetPrediction(kart, !IsPredictionOn(kart));
                UpdatePredictionHud(slot, kart);
            }
        } else if (event.buttonId === "usermenu_collisiondebug_button") {
            // Per player: only this player's melon is drawn/logged (debug
            // draws themselves only show in tools mode).
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (kart) {
                SetCollisionDebug(kart, !IsCollisionDebugOn(kart));
                UpdateCollisionDebugHud(slot, kart);
            }
        } else if (event.buttonId === "usermenu_freelook_button") {
            // Per player: this player flies their own pawn around, their
            // melon waits frozen (dev/free-look.js). Switching it on closes
            // the menu so the mouse looks around right away.
            const slot = event.player.GetPlayerSlot();
            const kart = karts.get(slot);
            if (kart) {
                const on = SetFreeLook(kart, !IsFreeLookOn(kart));
                UpdateFreeLookHud(slot, kart);
                if (on) {
                    SetUserMenuOpen(slot, kart, false);
                }
            }
        } else if (event.buttonId.startsWith("usermenu_color_")) {
            const key = event.buttonId.slice("usermenu_color_".length);
            const preset = COLOR_PRESETS[key];
            if (!preset) {
                Debug(`usermenu_color_${key}: no such color preset, ignoring`);
                return;
            }
            const kart = karts.get(event.player.GetPlayerSlot());
            if (kart) {
                SetKartPaintColor(kart, preset);
            }
        }
    });
}

// The custom HUD (panorama/layout/custom_game/speedometer.xml), one file per
// panel: speedometer.js (speed, jump and health bars), bounce-panel.js,
// track.js (time trial clock + checkpoint strip), hub-modal.js, user-menu.js.
// layout.js finds the custom_hud_layout entity; inputs.js handles every
// button click.

// Pure ground/wall contact rules — is the melon on the ground, is a wall
// right at it — no cs_script import, so it's unit-testable in Node (see
// test/movement/contact.test.mjs). movement/contact/contact.js runs the traces and
// feeds the results in here; what a jump does with them is
// movement/jump/logic.js.

/**
 * The melon's vertical acceleration over the last tick: the vertical
 * velocity physics left it with, compared to the one we commanded.
 * @param {number} commandedVz @param {number} actualVz @param {number} dt
 */
function VerticalAccel(commandedVz, actualVz, dt) {
    return dt > 0 ? (actualVz - commandedVz) / dt : 0;
}

/**
 * Whether something held the melon up last tick: in free fall gravity
 * takes the full GRAVITY off its vertical velocity every second, anything
 * it rests or rolls on cancels a clear part of that.
 * @param {number} verticalAccel units/sec^2, see VerticalAccel
 */
function IsSupported(verticalAccel) {
    return verticalAccel > -FREE_FALL_FRACTION * GRAVITY;
}

/**
 * On the ground = held up (IsSupported) by a floor-like surface underneath
 * (the floor trace's normal; undefined if it found nothing).
 * @param {boolean} supported @param {number | undefined} floorNormalZ
 */
function IsGrounded(supported, floorNormalZ) {
    return supported && floorNormalZ !== undefined && floorNormalZ >= GROUND_NORMAL_MIN_Z;
}

/**
 * Whether the melon is still taking off from a jump (ground or wall, see
 * GROUND_LIFTOFF_TIME) — ground contact measured now doesn't count then.
 * @param {number} now @param {number | undefined} lastJumpTime @param {number | undefined} lastWallJumpTime
 */
function InLiftoff(now, lastJumpTime, lastWallJumpTime) {
    const last = Math.max(lastJumpTime ?? -Infinity, lastWallJumpTime ?? -Infinity);
    return now - last < GROUND_LIFTOFF_TIME;
}

/**
 * How far from the melon's center (to the wall's plane) a wall still counts
 * as at the melon: WALL_JUMP_CONTACT_RADIUS, plus how far the melon gets
 * towards it in one tick — at speed it would otherwise go from outside the
 * radius into the wall and off it again between two ticks.
 * @param {number} speedIntoWall units/sec towards the wall (negative: moving away)
 * @param {number} dt
 */
function WallContactReach(speedIntoWall, dt) {
    return WALL_JUMP_CONTACT_RADIUS + Math.max(0, speedIntoWall) * Math.max(0, dt);
}

/**
 * Whether a wall `gap` units from the melon's center is at the melon (see
 * WallContactReach) — the wall jump's contact test.
 * @param {number} gap center to the wall's plane
 * @param {{ x: number, y: number }} n the wall's horizontal, unit-length normal (pointing away from it)
 * @param {{ x: number, y: number }} velocity the melon's velocity now
 * @param {number} dt
 */
function IsAtWall(gap, n, velocity, dt) {
    return gap <= WallContactReach(-(velocity.x * n.x + velocity.y * n.y), dt);
}

// Steering grip (see STEER_GRIP_* in movement/driving/constants.js): turning the
// melon's velocity towards where the player looks. Pure math, no engine.

/**
 * Turns horizontal velocity `v` towards unit direction `dir` by at most
 * `maxTurn` degrees, keeping its length. Unchanged if it's standing still or
 * more than `maxAngle` degrees away from `dir`.
 * @param {{ x: number, y: number }} v @param {{ x: number, y: number }} dir
 * @param {number} maxTurn @param {number} maxAngle
 * @returns {{ x: number, y: number }}
 */
function SteerTowards(v, dir, maxTurn, maxAngle) {
    const speed = Math.hypot(v.x, v.y);
    if (speed === 0 || maxTurn <= 0) {
        return { x: v.x, y: v.y };
    }
    const current = Math.atan2(v.y, v.x);
    const target = Math.atan2(dir.y, dir.x);
    // Signed difference in -PI..PI.
    const diff = Math.atan2(Math.sin(target - current), Math.cos(target - current));
    if (Math.abs(diff) > (maxAngle * Math.PI) / 180) {
        return { x: v.x, y: v.y };
    }
    const limit = (maxTurn * Math.PI) / 180;
    const angle = current + Math.max(-limit, Math.min(limit, diff));
    return { x: Math.cos(angle) * speed, y: Math.sin(angle) * speed };
}

// Attack boost — speed for health (ATTACK_BOOST_* in movement/attack-boost/constants.js).
// Pure rule, no cs_script import; movement/driving/drive.js applies it
// (test/movement/attack-boost.test.mjs).

/**
 * `velocity`'s horizontal part limited to the horizontal speed of
 * `commanded` (what the script set last tick) — drops whatever speed an
 * engine push (knife swing, see ATTACK_PUSH_GUARD_SECONDS) added, keeping
 * the direction and the vertical part.
 * @param {{ x: number, y: number, z: number }} velocity @param {{ x: number, y: number, z: number }} commanded
 */
function WithoutEnginePush(velocity, commanded) {
    const speed = Math.hypot(velocity.x, velocity.y);
    const allowed = Math.hypot(commanded.x, commanded.y);
    if (speed <= allowed) {
        return velocity;
    }
    const scale = allowed / speed;
    return { x: velocity.x * scale, y: velocity.y * scale, z: velocity.z };
}

/**
 * Whether the boost is on this tick and the health left after paying for
 * it. On whenever attack is held and there's health left — no floor: at 0
 * or below the melon breaks (the caller's job).
 * @param {number} health @param {boolean} attackHeld @param {number} dt
 * @returns {{ boosting: boolean, health: number }}
 */
function AttackBoost(health, attackHeld, dt) {
    if (!attackHeld || health <= 0) {
        return { boosting: false, health };
    }
    return {
        boosting: true,
        health: health - ATTACK_BOOST_HEALTH_PER_SECOND * dt,
    };
}

// Diagnostics for the attack button (DEBUG only, console). Found with it: the
// engine gave the pawn a knife back after spawn, and each knife swing shoved
// the melon ~140 u/s even with the attack boost off — HoldPawn now takes
// weapons away every tick. Kept in case anything else reacts to attack. These logs show
// what's going on: per kart while attack is held, how much speed physics
// added on top of what the script commanded last tick, and which weapon the
// pawn holds; plus every gun shot, bullet impact and knife attack.

const ATTACK_DEBUG_INTERVAL = 0.25; // seconds between two per-kart lines while attack is held

/** @param {any} entity */
function Describe(entity) {
    if (!entity?.IsValid?.()) {
        return "none";
    }
    const name = entity.GetEntityName?.();
    return `${entity.GetClassName()}${name ? ` "${name}"` : ""}`;
}

/**
 * Called by UpdateKart every tick attack is held.
 * @param {number} slot @param {import("../core/kart-registry.js").Kart} kart
 * @param {{ x: number, y: number, z: number }} currentVelocity @param {boolean} boosting
 */
function LogAttackHeld(slot, kart, currentVelocity, boosting) {
    const now = Instance.GetGameTime();
    if (!DEBUG || now < (kart.nextAttackDebugTime ?? 0)) {
        return;
    }
    kart.nextAttackDebugTime = now + ATTACK_DEBUG_INTERVAL;
    const actual = Math.hypot(currentVelocity.x, currentVelocity.y);
    const commanded = kart.lastVelocity ? Math.hypot(kart.lastVelocity.x, kart.lastVelocity.y) : undefined;
    const added = commanded === undefined ? "?" : (actual - commanded).toFixed(1);
    Debug(
        `[attack debug] slot ${slot}: health ${kart.health.toFixed(1)}, boost ${boosting ? "ON" : "off"}, ` +
        `speed commanded ${commanded?.toFixed(0) ?? "?"} -> now ${actual.toFixed(0)} (physics added ${added} u/s this tick), ` +
        `weapon ${Describe(kart.pawn.GetActiveWeapon?.())}`
    );
}

/** Registers the engine-event logs. Called once from index.js. */
function RegisterAttackDebug() {
    if (!DEBUG) {
        return;
    }
    Instance.OnGunFire(({ weapon }) => {
        Debug(`[attack debug] gun fired: ${Describe(weapon)}`);
    });
    Instance.OnBulletImpact(({ weapon, position, hitEntity }) => {
        const melonKart = hitEntity ? FindKartByMelon(hitEntity) : undefined;
        Debug(
            `[attack debug] bullet from ${Describe(weapon)} hit ${Describe(hitEntity)}` +
            `${melonKart ? " — A MELON" : ""} at (${position.x.toFixed(0)}, ${position.y.toFixed(0)}, ${position.z.toFixed(0)})`
        );
    });
    Instance.OnKnifeAttack(({ weapon, attackType }) => {
        Debug(`[attack debug] knife attack: ${Describe(weapon)} (type ${attackType})`);
    });
}

// Engine side of ground/wall contact: the floor and wall probes (line
// traces — see UpdateGrounded for why not TraceSphere). The rules are in
// ./logic.js; what the probes saw goes to dev/collision-debug.js for the
// optional debug view.

/**
 * Refreshes kart.lastGroundedTime if the melon is on the ground right now —
 * held up (`supported`, measured from physics in UpdateKart) by a floor-like
 * surface a trace finds underneath — and reports whether it had ground
 * contact within the last GROUND_COYOTE_TIME seconds. Not while still
 * taking off from a jump (InLiftoff): the floor pushing the melon up for a
 * tick after it jumped looks just like support.
 * Line traces only, not TraceSphere: a sphere started at the melon's center
 * apparently counts as starting inside it in-engine — with sphere probes no
 * floor was ever found and jumping stopped working entirely.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {any} origin @param {number} now
 * @param {boolean} supported @param {number | undefined} verticalAccel only for the debug view
 */
function UpdateGrounded(kart, origin, now, supported, verticalAccel) {
    const trace = TraceLine({
        start: origin,
        end: { x: origin.x, y: origin.y, z: origin.z - GROUND_CHECK_DISTANCE },
        ignoreEntity: [kart.melon, kart.pawn],
        ignorePlayers: true,
    });
    const floorNormalZ = trace.didHit && !trace.startedInSolid ? trace.normal.z : undefined;
    kart.floorNormalZ = floorNormalZ; // for this tick's landing damage (FLAT_LANDING_*)
    const grounded = IsGrounded(supported, floorNormalZ) && !InLiftoff(now, kart.lastJumpTime, kart.lastWallJump?.time);
    RecordFloorProbe(kart, origin, supported, verticalAccel, trace, grounded);
    if (grounded) {
        kart.lastGroundedTime = now;
    }
    return kart.lastGroundedTime !== undefined && now - kart.lastGroundedTime <= GROUND_COYOTE_TIME;
}

/**
 * In the air: whether a wall is right at the melon — a line trace in each of
 * WALL_PROBE_DIRECTIONS horizontal directions; a steep, non-prop hit counts
 * if its plane is within WallContactReach of the melon's center (the tight
 * WALL_JUMP_CONTACT_RADIUS plus one tick's travel towards it, IsAtWall).
 * The nearest such wall is recorded as kart.lastWallContact (the wall
 * jump's normal). No physics check on top: being that close *is* the
 * contact, so a press counts when the wall is at the melon — just before
 * the touch, on it, or the tick after (WALL_JUMP_WINDOW).
 * On the ground there's no wall jump: nothing is recorded, and the probes
 * only run at all for the collision debug view, so it shows them always.
 * @param {import("../../core/kart-registry.js").Kart} kart @param {any} origin @param {number} now
 * @param {any} currentVelocity @param {number} dt @param {boolean} grounded see UpdateGrounded
 * @returns {{ x: number, y: number } | undefined} the wall's normal, if one is at the melon (in the air)
 */
function UpdateWallContact(kart, origin, now, currentVelocity, dt, grounded) {
    if (grounded && !IsCollisionDebugOn(kart)) {
        return undefined;
    }
    /** @type {{ normal: { x: number, y: number }, gap: number, point: any, probe: number, at: boolean } | undefined} */
    let nearest = undefined;
    /** @type {{ end: any, state: import("../../dev/collision-debug.js").ProbeState }[]} */
    const probes = [];
    // Long enough for the widest reach this tick (moving straight at a
    // wall), and a wall between two probe directions is hit at up to
    // 1/cos(half the angle between them) times its real distance.
    const reach = WallContactReach(Math.hypot(currentVelocity.x, currentVelocity.y), dt) / Math.cos(Math.PI / WALL_PROBE_DIRECTIONS);
    for (let i = 0; i < WALL_PROBE_DIRECTIONS; i++) {
        const a = (i / WALL_PROBE_DIRECTIONS) * Math.PI * 2;
        const trace = TraceLine({
            start: origin,
            end: {
                x: origin.x + Math.cos(a) * reach,
                y: origin.y + Math.sin(a) * reach,
                z: origin.z,
            },
            ignoreEntity: [kart.melon, kart.pawn],
            ignorePlayers: true,
        });
        if (!trace.didHit || trace.startedInSolid) {
            probes.push({ end: trace.end, state: "miss" });
            continue;
        }
        const hit = trace.hitEntity;
        if (Math.abs(trace.normal.z) >= WALL_NORMAL_MAX_Z || (hit && !hit.IsWorld() && hit.GetClassName().startsWith("prop_physics"))) {
            probes.push({ end: trace.end, state: "ignored" }); // floor/ceiling, or other melons, break pieces — not a wall to jump off
            continue;
        }
        const h = Math.hypot(trace.normal.x, trace.normal.y);
        const n = { x: trace.normal.x / h, y: trace.normal.y / h };
        const gap = (origin.x - trace.end.x) * n.x + (origin.y - trace.end.y) * n.y; // center to wall plane
        const at = IsAtWall(gap, n, currentVelocity, dt);
        probes.push({ end: trace.end, state: at ? "near" : "far" });
        // A wall at the melon beats one that isn't; among equals the nearest.
        if (!nearest || (at && !nearest.at) || (at === nearest.at && gap < nearest.gap)) {
            nearest = { normal: n, gap, point: trace.end, probe: probes.length - 1, at };
        }
    }
    if (!nearest) {
        RecordWallProbes(kart, probes);
        return undefined;
    }
    if (nearest.at) {
        probes[nearest.probe].state = "chosen";
    }
    const into = -(currentVelocity.x * nearest.normal.x + currentVelocity.y * nearest.normal.y);
    RecordWallProbes(kart, probes, {
        point: nearest.point,
        normal: nearest.normal,
        gap: nearest.gap,
        reach: WallContactReach(into, dt),
        actual: currentVelocity,
        touching: nearest.at,
    });
    if (!nearest.at || grounded) {
        return undefined;
    }
    // How the melon came at this wall, for the wall jump's angle rating —
    // remembered from the contact's start (WallApproach), before physics
    // stopped it against the wall.
    const approach = WallApproach(kart.lastWallContact, now, nearest.normal, [currentVelocity, kart.lastVelocity, kart.prevLastVelocity]);
    kart.lastWallContact = { time: now, normal: nearest.normal, ...approach };
    return nearest.normal;
}

// Jump recharge zones: a trigger_multiple (filtered to prop_physics like the
// other triggers) with OnStartTouch -> RunScriptInput "jump_recharge_enter"
// and OnEndTouch -> "jump_recharge_leave". While the melon is inside, its
// wall-jump charges (WALL_JUMP_CHARGES) are full at once and kept full — the
// first wall jump after leaving starts from a full set. Pure rule, no
// cs_script import; applied by movement/driving/drive.js
// (test/zones/jump-recharge.test.mjs).

/**
 * The wall-jump charge after this tick's refill (RechargeWallJump): full
 * inside a jump recharge zone, unchanged outside one.
 * @param {number} charge @param {boolean} inZone
 */
function ChargeInRechargeZone(charge, inZone) {
    return inZone ? WALL_JUMP_CHARGES : charge;
}

// Per-tick melon driving (UpdateKart): the order everything happens in each
// tick — break/lock handling, contact measurement, impact and wall-bounce
// detection, steering, friction, jump, speed cap. The individual parts live
// in the sibling files; this one wires them together.

/** @param {number} slot @param {import("../../core/kart-registry.js").Kart} kart @param {number} dt */
function UpdateKart(slot, kart, dt) {
    const { pawn, melon } = kart;
    // Before every early return below: the charge refills standing still,
    // race-locked or broken too.
    RechargeWallJumpCharge(kart, dt);
    kart.wallJumpCharge = ChargeInRechargeZone(GetWallJumpCharges(kart), InJumpRechargeZone(kart));

    // Locked during the pre-race countdown, and again once a kart has
    // finished its heat (parked so it stops re-triggering checkpoints).
    // Vertical velocity is left alone so gravity still settles it normally —
    // only driving input is suppressed.
    if (kart.locked) {
        const vel = melon.GetAbsVelocity();
        melon.Move({ velocity: { x: 0, y: 0, z: vel.z } });
        kart.lastVelocity = undefined;
        kart.settled = false;
        kart.speedCap = MAX_SPEED;
        kart.momentum = undefined; // standing still — the momentum run is over
        kart.attackBoosting = false;
        kart.pendingBounce = undefined; // parked/finished — a bounce's leftover damage no longer matters
        kart.padFlight = undefined;
        return;
    }

    // Free look (dev/free-look.js): the player is flying their pawn around,
    // the melon waits where it was, motion off — no driving, no impacts.
    if (kart.freeLook) {
        kart.lastVelocity = undefined;
        kart.settled = false;
        kart.attackBoosting = false;
        return;
    }

    // Broken and waiting out BREAK_RESPAWN_DELAY (see BreakMelon) — unlike
    // `locked` above, freeze completely (gravity included). It's already
    // hidden at the crash site, and should just hold still until the delayed
    // respawn teleports it away rather than keep tumbling invisibly (which
    // would also spuriously re-trigger the impact check below).
    if (kart.breaking) {
        melon.Move({ velocity: { x: 0, y: 0, z: 0 } });
        kart.lastVelocity = undefined;
        kart.settled = false;
        kart.momentum = undefined;
        kart.attackBoosting = false;
        kart.pendingBounce = undefined;
        // Pull the chase camera back from the crash site so the burst is
        // actually visible; restored by ScheduleRespawnAfterBreak.
        ApplyBreakCameraZoom(kart, Instance.GetGameTime() - (kart.breakTime ?? Instance.GetGameTime()));
        return;
    }

    const now = Instance.GetGameTime();
    // A jump pad launch's damage protection ends a moment after landing.
    UpdatePadFlight(kart, now);
    // Heal zones (heal_enter/heal_leave) — before this tick's damage, so a
    // hit inside a zone still breaks the melon if it's big enough.
    ApplyHealing(kart, dt);
    // A wall bounce's jump-timing window has closed — its quality is final,
    // so charge (or waive) its damage now.
    if (kart.pendingBounce && now - kart.pendingBounce.time > WALL_BOUNCE_PERFECT_JUMP_WINDOW) {
        if (SettleWallBounceDamage(slot, kart)) {
            return; // broke
        }
    }
    const origin = melon.GetAbsOrigin();
    const currentVelocity = melon.GetAbsVelocity();
    // Ground contact from physics (see IsSupported): the vertical velocity we
    // commanded last tick vs. what it is now. No command to compare against
    // (first tick after a teleport/respawn, or coming out of rest): a melon
    // that was lying still is on something, anything else counts as not.
    const verticalAccel = kart.lastVelocity ? VerticalAccel(kart.lastVelocity.z, currentVelocity.z, dt) : undefined;
    const supported = verticalAccel !== undefined ? IsSupported(verticalAccel) : kart.settled;
    const grounded = UpdateGrounded(kart, origin, now, supported, verticalAccel);
    const wallNormalNow = UpdateWallContact(kart, origin, now, currentVelocity, dt, grounded);
    // Wall bounce / wall jump tuning for where the melon is (lift zone or not).
    const wallRules = CurrentWallRules(kart);
    DrawCollisionDebug(slot, kart, grounded, wallNormalNow, wallRules.wallJumpWindow);
    /** @type {{ x: number, y: number } | undefined} */
    let bounceVelocity = undefined;
    let bounceAngleFactor = 0;
    // In water (water_enter/water_leave) the water's drag and buoyancy keep
    // pulling the velocity away from what we commanded — that's no impact
    // and no wall, so neither damage nor a bounce comes from it.
    if (kart.lastVelocity && !InWater(kart)) {
        const impactDelta = {
            x: currentVelocity.x - kart.lastVelocity.x,
            y: currentVelocity.y - kart.lastVelocity.y,
            z: currentVelocity.z - kart.lastVelocity.z,
        };
        const impactSpeed = Math.hypot(impactDelta.x, impactDelta.y, impactDelta.z);
        // (A landing needs no special case here any more: the floor stopping
        // the fall is exactly the support IsSupported measures above.)
        // Right after a bounce the same wall contact often keeps shoving the
        // melon for another tick or two — that's still the bounce (already
        // charged via pendingBounce), not a new crash to take damage from.
        const inBounceCooldown = now < (kart.nextBounceTime ?? 0);
        const wallNormal =
            WALL_BOUNCE_ENABLED && impactSpeed > WALL_BOUNCE_MIN_IMPACT && !inBounceCooldown
                ? DetectWallNormal(kart, impactDelta)
                : null;
        const bounce = wallNormal ? ComputeWallBounce(kart, wallNormal, now) : null;
        if (bounce) {
            // Only reachable with WALL_BOUNCE_COOLDOWN tuned below the jump
            // window — settle the previous bounce's damage before starting a
            // new one.
            if (kart.pendingBounce && SettleWallBounceDamage(slot, kart)) {
                return;
            }
            // In a lift zone, never so slow that the melon can't reach the
            // opposite wall and bounce again (wallRules.minBounceSpeed) —
            // free: speedGain below stays what the bounce itself earned.
            bounceVelocity = WithMinSpeed(bounce.velocity, wallRules.minBounceSpeed);
            bounceAngleFactor = bounce.angleFactor;
            // The melon leaves the wall right away after bouncing, so the
            // probes won't see it next tick — this is its wall contact.
            kart.lastWallContact = { time: now, normal: { x: wallNormal.x, y: wallNormal.y } };
            kart.nextBounceTime = now + WALL_BOUNCE_COOLDOWN;
            kart.lastBounceTime = now;
            // Read by UpdateBounceHud for the angle/timing feedback panel.
            kart.lastBounceInfo = { angle: bounce.angle, angleFactor: bounce.angleFactor, jumpFactor: bounce.jumpFactor };
            kart.speedCap = Math.max(kart.speedCap ?? MomentumMaxSpeed(kart.momentum), Math.hypot(bounceVelocity.x, bounceVelocity.y));
            // Damage waits until the jump-timing window has closed (see the
            // top of the non-locked path, and the late-jump case below) —
            // a jump just *after* the hit can still improve its quality.
            kart.pendingBounce = {
                time: now,
                impactSpeed,
                impactDir: impactDelta,
                angle: bounce.angle,
                angleFactor: bounce.angleFactor,
                jumpFactor: bounce.jumpFactor,
                speedGain: bounce.speedGain,
            };
            // ...unless it's lethal already: a late jump could only add
            // damage, so break right here at the wall instead of mid-air
            // once the window has closed (the bounce velocity is never applied).
            if (WallBounceBreaksAtImpact(kart) && SettleWallBounceDamage(slot, kart)) {
                return;
            }
        } else if (!inBounceCooldown && impactSpeed > IMPACT_DAMAGE_THRESHOLD) {
            ApplyImpactDamage(slot, kart, impactDelta);
            if (kart.health <= 0) {
                // impactDelta is the sudden change physics forced onto the
                // velocity we commanded — i.e. roughly the direction the
                // wall shoved the melon back in, not wherever it happened to
                // be tumbling toward. That's what the break particles should
                // point along, not the melon's own (essentially random while
                // rolling) orientation.
                BreakMelon(slot, kart, impactDelta, impactSpeed);
                return; // now broken/frozen this tick — nothing else to update
            }
        }
    }

    const forwardInput =
        (pawn.IsInputPressed(CSInputs.FORWARD) ? 1 : 0) - (pawn.IsInputPressed(CSInputs.BACK) ? 1 : 0);
    const strafeInput =
        (pawn.IsInputPressed(CSInputs.RIGHT) ? 1 : 0) - (pawn.IsInputPressed(CSInputs.LEFT) ? 1 : 0);
    const jumpPressed = pawn.WasInputJustPressed(CSInputs.JUMP);
    // Attack boost (ATTACK_BOOST_*): holding attack pushes along the look
    // direction and lifts the speed cap, paid for with health every tick —
    // no floor: boost until it's gone and the melon breaks.
    const attackHeld = pawn.IsInputPressed(CSInputs.ATTACK);
    const boost = AttackBoost(kart.health, attackHeld, dt);
    kart.health = boost.health;
    kart.attackBoosting = boost.boosting; // shows the boost trail, see fx/boost-trail/boost-trail.js
    if (attackHeld) {
        LogAttackHeld(slot, kart, currentVelocity, boost.boosting);
    }
    if (boost.boosting && kart.health <= 0) {
        Debug(`slot ${slot}: boosted until the health ran out`);
        const speed = Math.hypot(currentVelocity.x, currentVelocity.y, currentVelocity.z);
        BreakMelon(slot, kart, speed > 0 ? currentVelocity : { x: 1, y: 0, z: 0 }, Math.max(speed, 1));
        return;
    }

    if (
        !boost.boosting &&
        // A head-on wall hit can leave vphysics' own velocity at ~0 this
        // tick — that's the bounce about to be applied, not a melon at rest.
        !bounceVelocity &&
        forwardInput === 0 &&
        strafeInput === 0 &&
        !jumpPressed &&
        Math.hypot(currentVelocity.x, currentVelocity.y) < MELON_REST_SPEED &&
        Math.abs(currentVelocity.z) < MELON_REST_SPEED
    ) {
        // Fully settled: no input, not falling/jumping, negligible velocity
        // in every axis. Stop commanding it entirely and hand off to
        // vphysics completely — see MELON_REST_SPEED. lastVelocity is
        // cleared for the same reason the locked/breaking branches above
        // clear it: whatever vphysics does to it next (slide, tip, settle)
        // is real physics, not an "impact" to react to.
        if (!kart.settled) {
            // The tick it *first* comes to rest — see SETTLE_NUDGE_ANGULAR_SPEED
            // for why a one-off random spin nudge belongs here rather than
            // just leaving it alone.
            // Spin axis in the horizontal (x/y) plane, i.e. a tip over in a
            // random direction — z is the vertical axis in Source, so any z
            // component would just spin the melon in place on its resting
            // point, which can't break a knife-edge balance.
            const nudgeAngle = Math.random() * Math.PI * 2;
            melon.Move({
                angularVelocity: {
                    x: Math.cos(nudgeAngle) * SETTLE_NUDGE_ANGULAR_SPEED,
                    y: Math.sin(nudgeAngle) * SETTLE_NUDGE_ANGULAR_SPEED,
                    z: 0,
                },
            });
            kart.settled = true;
        }
        kart.lastVelocity = undefined;
        kart.momentum = undefined;
        return;
    }
    kart.settled = false;

    // Direction comes from the player's look direction (mouse), not a
    // separate turn control — this is what makes it "free-look" driving.
    // In a side-view zone (2D jump & run) it's the screen axis instead.
    const sideView = SideViewDriving(kart, origin, currentVelocity, forwardInput, strafeInput);
    const rad = (pawn.GetEyeAngles().yaw * Math.PI) / 180;
    const forwardDir = sideView ? sideView.forwardDir : { x: Math.cos(rad), y: Math.sin(rad) };
    const rightDir = { x: Math.sin(rad), y: -Math.cos(rad) };
    const driveForward = sideView ? sideView.forwardInput : forwardInput;
    const driveStrafe = sideView ? 0 : strafeInput;

    // After a wall bounce, steering/friction apply on top of the reflected
    // velocity rather than whatever vphysics left behind — so the player can
    // still steer out of the bounce the same tick.
    let vx = bounceVelocity ? bounceVelocity.x : currentVelocity.x;
    let vy = bounceVelocity ? bounceVelocity.y : currentVelocity.y;
    // Attack also makes the engine shove the melon (knife swing) — no speed
    // from that, see ATTACK_PUSH_GUARD_SECONDS.
    if (attackHeld) {
        kart.attackGuardUntil = now + ATTACK_PUSH_GUARD_SECONDS;
    }
    // Coming out of rest there's no command to compare against (settled
    // melons aren't commanded) — then it was standing still, and a swing
    // must not get it rolling either.
    if (!bounceVelocity && now <= (kart.attackGuardUntil ?? -Infinity)) {
        const guarded = WithoutEnginePush({ x: vx, y: vy, z: 0 }, kart.lastVelocity ?? { x: 0, y: 0, z: 0 });
        vx = guarded.x;
        vy = guarded.y;
    }

    // Steering grip (STEER_GRIP_*): holding forward turns the velocity itself
    // towards the look direction — on the ground and (at STEER_AIR_GRIP_RATE)
    // in the air. Not on a bounce tick — the reflected velocity is the
    // bounce's result and stays as computed.
    if (driveForward > 0 && !bounceVelocity) {
        const gripRate = grounded ? STEER_GRIP_RATE : STEER_AIR_GRIP_RATE;
        const steered = SteerTowards({ x: vx, y: vy }, forwardDir, gripRate * dt, STEER_GRIP_MAX_ANGLE);
        vx = steered.x;
        vy = steered.y;
    }

    if (driveForward !== 0 || driveStrafe !== 0) {
        const forwardAccel = driveForward > 0 ? FORWARD_ACCEL : REVERSE_ACCEL;
        let ax = forwardDir.x * driveForward * forwardAccel + rightDir.x * driveStrafe * STRAFE_ACCEL;
        let ay = forwardDir.y * driveForward * forwardAccel + rightDir.y * driveStrafe * STRAFE_ACCEL;
        vx += ax * dt;
        vy += ay * dt;
    } else if (!boost.boosting) {
        const speed = Math.hypot(vx, vy);
        if (speed > 0) {
            const scale = Math.max(0, speed - COAST_FRICTION * dt) / speed;
            vx *= scale;
            vy *= scale;
        }
    }

    if (boost.boosting) {
        vx += forwardDir.x * ATTACK_BOOST_ACCEL * dt;
        vy += forwardDir.y * ATTACK_BOOST_ACCEL * dt;
        kart.speedCap = Math.max(kart.speedCap ?? MomentumMaxSpeed(kart.momentum), ATTACK_BOOST_MAX_SPEED);
    }

    // Jump press (ground jump / wall jump / wall-bounce timing) — see
    // ApplyJump in jump.js.
    // A wall bounce also kicks it upward (WALL_BOUNCE_UP_SPEED, stronger in a
    // lift zone, and PERFECT_BOUNCE_UP_MULTIPLIER stronger for a PERFECT hit).
    const vzBase = bounceVelocity
        ? BounceUpVelocity(currentVelocity.z, wallRules.bounceUpSpeed, bounceAngleFactor)
        : currentVelocity.z;
    const v = { x: vx, y: vy, z: vzBase };
    ApplyJump(slot, kart, now, grounded, jumpPressed, v, wallRules);
    // On a jump pad, a (just) pressed jump launches instead — see JUMP_PAD_*.
    // A press that launched did something, so it's no mashing press (see
    // WallTimingPress).
    if (TryPadLaunch(slot, kart, now, jumpPressed, v, forwardDir) && kart.lastIdleJumpPressTime === now) {
        kart.lastIdleJumpPressTime = undefined;
    }
    vx = v.x;
    vy = v.y;
    const vz = v.z;
    // Side view: nothing moves the melon towards or away from the camera.
    if (sideView) {
        const kept = KeepOnPlane({ x: vx, y: vy }, sideView.view, sideView.depthError);
        vx = kept.x;
        vy = kept.y;
    }

    // Normally the melon's momentum top speed (MAX_SPEED plus whatever
    // repeatedly reaching it has earned, see MOMENTUM_*), but a wall bounce
    // or the attack boost can lift it (see BOOST_DECAY): decays back down
    // every tick, and never stays above the melon's actual speed so a lost
    // boost can't be re-earned just by accelerating again.
    const momentumMax = MomentumMaxSpeed(kart.momentum);
    const speedCap = kart.speedCap ?? momentumMax;
    let horizSpeed = Math.hypot(vx, vy);
    if (horizSpeed > speedCap) {
        const scale = speedCap / horizSpeed;
        vx *= scale;
        vy *= scale;
        horizSpeed = speedCap;
    }
    // Boosts don't count towards momentum (neither the attack boost nor a
    // cap a bounce/boost has lifted above the momentum top speed).
    const boosted = boost.boosting || speedCap > momentumMax + 1e-6;
    kart.momentum = UpdateMomentum(kart.momentum, horizSpeed, now, boosted);
    kart.speedCap = Math.max(MomentumMaxSpeed(kart.momentum), Math.min(speedCap - BOOST_DECAY * dt, horizSpeed));

    melon.Move({ velocity: { x: vx, y: vy, z: vz } });
    // What we commanded this tick — compared against the actual velocity
    // physics settles on by next tick to detect collisions (see the top of
    // this function). The one before it and where this tick started are kept
    // too, for measuring a wall hit's true incoming direction — see
    // DetectWallNormal/ComputeWallBounce.
    kart.prevLastVelocity = kart.lastVelocity;
    kart.prevOrigin = origin;
    kart.lastVelocity = { x: vx, y: vy, z: vz };
}

/**
 * Driving in a side-view zone (zones/side-view/): the screen axis instead of
 * the look direction, A/D left/right on screen, W the way the melon faces
 * (see SideViewInput), and how far it's off the plane it entered on.
 * undefined outside one. Entering a (new) zone starts on the plane the melon
 * is on, facing the way it moves.
 * @param {import("../../core/kart-registry.js").Kart} kart
 * @param {{ x: number, y: number, z: number }} origin @param {{ x: number, y: number, z: number }} velocity
 * @param {number} forwardInput @param {number} strafeInput
 */
function SideViewDriving(kart, origin, velocity, forwardInput, strafeInput) {
    const zone = CurrentSideView(kart);
    if (!zone) {
        return undefined; // kart.sideViewDrive stays: the camera turns the view along its facing on the way out
    }
    const { view, right } = SideViewAxes(zone.yaw);
    if (kart.sideViewDrive?.zone !== zone) {
        kart.sideViewDrive = { zone, plane: PlaneDepth(origin, view), facing: InitialFacing(velocity, right) };
    }
    const input = SideViewInput(forwardInput, strafeInput, kart.sideViewDrive.facing);
    kart.sideViewDrive.facing = input.facing;
    const dir = input.axis !== 0 ? Math.sign(input.axis) : input.facing;
    return {
        forwardDir: { x: right.x * dir, y: right.y * dir },
        forwardInput: Math.abs(input.axis),
        view,
        depthError: kart.sideViewDrive.plane - PlaneDepth(origin, view),
    };
}

// Everything that moves a kart's melon each tick, one folder per mechanic:
// driving/ (UpdateKart — the per-tick order — and steering), contact/ (floor
// and wall probes), jump/ (ground + wall jump), wall-bounce/, attack-boost/,
// momentum/. Other parts of melon_drive import from here.

// Kill triggers: the melon_break input.

function RegisterBreakInputs() {
    // Kill trigger: any trigger_multiple (filtered to prop_physics) whose
    // OnStartTouch calls RunScriptInput "melon_break" breaks the touching melon
    // on the spot — same break as running out of health (effects at the crash
    // site, respawn at the last checkpoint after BREAK_RESPAWN_DELAY).
    Instance.OnScriptInput("melon_break", ({ activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart) {
            Debug("melon_break: activator wasn't a tracked melon, ignoring");
            return;
        }
        if (kart.breaking || kart.locked) {
            return; // already broken, or parked by the race flow (countdown, finished)
        }
        const slot = kart.pawn.GetPlayerController()?.GetPlayerSlot() ?? -1;
        const velocity = kart.melon.GetAbsVelocity();
        const speed = Math.hypot(velocity.x, velocity.y, velocity.z);
        kart.health = 0;
        Debug(`melon_break: slot ${slot} broken by trigger`);
        BreakMelon(slot, kart, speed > 0 ? velocity : { x: 1, y: 0, z: 0 }, Math.max(speed, 1));
    });
}

// The melon's health: damage/ (impacts, flat landings), breaking/ (health 0
// or a kill trigger: break effects, respawn) and heal/ (heal zones, full
// health on respawn). Other parts of melon_drive import from here.

// When the boost trail is on (see fx/boost-trail/constants.js). Pure rule, no
// engine import — tested in test/fx/boost-trail.test.mjs.

/**
 * Whether the trail should show this tick. Starts above MAX_SPEED +
 * BOOST_TRAIL_START_MARGIN, then keeps going down to MAX_SPEED +
 * BOOST_TRAIL_STOP_MARGIN (hysteresis, so it doesn't flicker). Always while
 * the attack boost is on (like Rocket League's boost: pressing it shows the
 * trail at once, whatever the speed). Not for speed a PERFECT wall bounce
 * gave — that one shows only its perfect-hit spark. Never while `blocked`
 * (the melon is broken or race-locked).
 * @param {boolean} showing whether it's on right now
 * @param {number} horizSpeed the melon's horizontal speed, units/sec
 * @param {boolean} blocked
 * @param {boolean} [attackBoosting] the attack boost is on this tick
 * @param {boolean} [perfectBounceBoost] the speed above MAX_SPEED is from a PERFECT bounce
 * @param {number} [normalMax] the melon's own top speed the margins count from — above MAX_SPEED with momentum (movement/momentum/logic.js)
 */
function ShouldShowBoostTrail(showing, horizSpeed, blocked, attackBoosting = false, perfectBounceBoost = false, normalMax = MAX_SPEED) {
    if (blocked) {
        return false;
    }
    if (attackBoosting) {
        return true;
    }
    if (perfectBounceBoost) {
        return false;
    }
    const margin = showing ? BOOST_TRAIL_STOP_MARGIN : BOOST_TRAIL_START_MARGIN;
    return horizSpeed > normalMax + margin;
}

// The boost trail: particle_boost_trail_template's particle effect riding along on a
// melon while ShouldShowBoostTrail (fx/boost-trail/logic.js) says so. Unlike
// the other effects in fx/particles.js it isn't played for a fixed lifetime —
// it runs as long as the boost does, then is stopped so the particles
// already out fade instead of vanishing. Tested in test/fx/boost-trail.test.mjs.

/**
 * Starts or stops the kart's trail to match its speed and attack boost. Called every tick
 * for a kart whose melon is valid (core/think.js).
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function UpdateBoostTrail(kart) {
    if (kart.boostTrail && kart.boostTrail.melon !== kart.melon) {
        StopBoostTrail(kart); // a new melon entity — the old trail rode on the old one
    }
    const velocity = kart.melon.GetAbsVelocity();
    const horizSpeed = Math.hypot(velocity.x, velocity.y);
    // Measured against the melon's own top speed: speed earned by momentum
    // (MOMENTUM_*) isn't a boost and shows no trail.
    const normalMax = MomentumMaxSpeed(kart.momentum);
    // A PERFECT bounce's speed shows no trail — until that boost is used up
    // (back to normal speed) or the attack boost takes over.
    if (kart.attackBoosting || horizSpeed <= normalMax + BOOST_TRAIL_STOP_MARGIN) {
        kart.perfectBounceBoost = false;
    }
    const show = ShouldShowBoostTrail(kart.boostTrail !== undefined, horizSpeed, kart.breaking || kart.locked, kart.attackBoosting, kart.perfectBounceBoost, normalMax);
    if (show && !kart.boostTrail) {
        StartBoostTrail(kart);
    } else if (!show && kart.boostTrail) {
        StopBoostTrail(kart);
    }
}

/** @param {import("../../core/kart-registry.js").Kart} kart */
function StartBoostTrail(kart) {
    const position = kart.melon.GetAbsOrigin();
    // Kept even when nothing spawned (no template in the map): marks the
    // trail as on, so the lookup isn't retried every tick of this boost.
    const entities = SpawnFromTemplate(BOOST_TRAIL_TEMPLATE_NAME, position);
    PlaceAll(entities, position);
    for (const entity of entities) {
        entity.SetParent(kart.melon);
    }
    StartParticles(entities);
    kart.boostTrail = { melon: kart.melon, entities };
}

/**
 * Stops the kart's trail, if it has one: no new particles, the ones out fade
 * over BOOST_TRAIL_FADE_SECONDS, then its entities are removed.
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function StopBoostTrail(kart) {
    if (!kart.boostTrail) {
        return;
    }
    StopParticles(kart.boostTrail.entities);
    RemoveAfter(kart.boostTrail.entities, BOOST_TRAIL_FADE_SECONDS);
    kart.boostTrail = undefined;
}

let lastHeartbeatTime = 0;
// Real elapsed time since the last Think, used for the movement math below —
// see the SetNextThink call at index.js's Think wiring for why this isn't a
// fixed interval.
let lastThinkTime = Instance.GetGameTime();

function Think() {
    const now = Instance.GetGameTime();
    const dt = now - lastThinkTime;
    lastThinkTime = now;

    const heartbeat = DEBUG && now - lastHeartbeatTime >= HEARTBEAT_INTERVAL;
    if (heartbeat) {
        lastHeartbeatTime = now;
        Debug(`Think: ${karts.size} kart(s) tracked`);
    }

    try {
        EnsurePlayerKarts();
    } catch (err) {
        Debug(`Think: EnsurePlayerKarts threw: ${err}`);
    }

    for (const [slot, kart] of karts) {
        if (!kart.pawn.IsValid()) {
            Debug(`Think: slot ${slot} pawn no longer valid, dropping kart`);
            DropKart(slot, kart);
            continue;
        }
        if (!kart.melon.IsValid()) {
            // The melon (a prop_physics_multiplayer) can be destroyed for
            // real by the engine's own physics damage on a hard enough
            // impact — separate from (and sometimes faster than) our own
            // scripted BreakMelon/health system. HandleMelonLost runs it
            // through the same particle + delay + checkpoint-respawn
            // sequence as a script-detected break instead of leaving it
            // gone for good. This is the *only* place a lost melon comes
            // back — SetUpPlayerKart (OnPlayerReset) deliberately never
            // replaces one, so the two can't spawn it in different places.
            HandleMelonLost(slot, kart);
            HidePrediction(kart);
            StopBoostTrail(kart);
            // Still lets USE work as an unstuck button while waiting on the
            // respawn above — it only touches kart.userMenuOpen/the pawn,
            // never the (currently missing) melon.
            UpdateUserMenu(slot, kart);
            continue;
        }
        HoldPawn(kart);
        kart.lastKnownPosition = kart.melon.GetAbsOrigin();
        kart.lastKnownAngles = kart.melon.GetAbsAngles();
        // One kart's update throwing for any other reason must not take down
        // every other player's kart with it — and, critically, must not skip
        // the SetNextThink call below, which would silently freeze the
        // *entire* gamemode (no more movement, HUD, or user-menu input for
        // anyone) until the next map/script reload.
        try {
            UpdateUserMenu(slot, kart); // checked before UpdateKart's locked/breaking early-returns — USE works as an unstuck button
            UpdateKart(slot, kart, dt);
            UpdateLiftCamera(kart, dt);
            UpdateZoneCamera(kart, dt);
            UpdateSideViewCamera(kart, dt);
            UpdateFollowCamera(kart, dt);
            UpdatePrediction(kart, dt);
            UpdateBoostTrail(kart);
            UpdateSpeedHud(slot, kart);
            UpdateBounceHud(slot, kart);
            UpdateJumpHud(slot, kart);
            UpdateHealthHud(slot, kart);
            UpdateCheckpointHud(slot, kart);
            if (kart.inHub) {
                ApplyHubModalState(slot, phase);
            }
            if (heartbeat) {
                const vel = kart.melon.GetAbsVelocity();
                Debug(
                    `Think: slot ${slot} velocity=(${vel.x.toFixed(0)}, ${vel.y.toFixed(0)}, ${vel.z.toFixed(0)}) ` +
                    `melonPos=${JSON.stringify(kart.melon.GetAbsOrigin())} eyeYaw=${kart.pawn.GetEyeAngles().yaw.toFixed(0)} ` +
                    `input(F/B/L/R/Jump)=${kart.pawn.IsInputPressed(CSInputs.FORWARD)}/${kart.pawn.IsInputPressed(CSInputs.BACK)}/` +
                    `${kart.pawn.IsInputPressed(CSInputs.LEFT)}/${kart.pawn.IsInputPressed(CSInputs.RIGHT)}/` +
                    `${kart.pawn.IsInputPressed(CSInputs.JUMP)}`
                );
            }
        } catch (err) {
            Debug(`Think: slot ${slot} update threw, dropping kart to keep the gamemode alive for everyone else: ${err}`);
            DropKart(slot, kart);
            ScheduleKartRebuild(slot, kart.pawn);
        }
    }
    EnsureModerator();
    // Same reasoning as the per-kart try/catch above: a race-flow transition
    // throwing (e.g. teleporting a kart whose melon just got destroyed) must
    // never skip the SetNextThink below and freeze the gamemode for everyone.
    try {
        UpdateRaceFlow(now);
    } catch (err) {
        Debug(`Think: UpdateRaceFlow threw: ${err}`);
    }
    // Re-think as soon as possible (every engine tick) rather than on a fixed
    // interval — WasInputJustPressed only reports a button edge for the
    // specific tick it happened on, so polling any slower than the engine's
    // own tick rate means some jump presses land on a tick we never check and
    // are silently lost. Same pattern as cs_script_demo's input.js.
    Instance.SetNextThink(Instance.GetGameTime());
}

/**
 * Gives a player whose kart got dropped by Think's error handler a fresh one
 * — otherwise they'd sit melon-less until the next OnPlayerReset, which on
 * this map practically never comes (see gamemode/index.js). Delayed, not
 * immediate, so an error that keeps recurring rebuilds at most once a second
 * instead of spawning (and dropping) a melon every tick.
 * @param {number} slot @param {any} pawn
 */
function ScheduleKartRebuild(slot, pawn) {
    Instance.Delay(1).then(() => {
        if (karts.has(slot) || !pawn.IsValid()) {
            return; // already rebuilt elsewhere (e.g. OnPlayerReset), or player gone
        }
        try {
            // The hub, not the intro: this player was already playing.
            if (SetUpPlayerKart(pawn, GetHubSpawnPoint())) {
                Debug(`ScheduleKartRebuild: slot ${slot} got a fresh kart`);
            }
        } catch (err) {
            Debug(`ScheduleKartRebuild: slot ${slot} rebuild threw: ${err}`);
        }
    });
}

// Player lifecycle (reset, disconnect), the paint triggers (melon_paint) and
// the respawn triggers (melon_respawn).

function RegisterKartInputs() {
    // A reset keeps an existing kart where it is and just re-attaches it to the
    // pawn. A player without one gets it from EnsurePlayerKarts (core/think.js):
    // the logo first, then a melon in the tutorial (intro_spawn).
    Instance.OnPlayerReset(({ player }) => {
        Debug(`OnPlayerReset: slot=${player.GetPlayerController()?.GetPlayerSlot()}`);
        SetUpPlayerKart(player, undefined);
    });

    Instance.OnPlayerDisconnect(({ playerSlot }) => {
        ForgetIntroLogo(playerSlot);
        const kart = karts.get(playerSlot);
        if (kart) {
            DropKart(playerSlot, kart);
        }
        ResetHudForPlayer(playerSlot);
        // Promotes the next-oldest remaining player (Map preserves insertion
        // order) so there's always a moderator whenever anyone's still on the
        // map — see EnsureModerator's comment for why this can't just wait for
        // the next Think tick to notice.
        EnsureModerator();
    });

    // See PAINT_TRIGGER_NAME_PATTERN for the Hammer-side naming
    // convention — the color comes from the trigger's own name, not this
    // input's parameter, so any number of differently-colored triggers can
    // share this one handler.
    Instance.OnScriptInput("melon_paint", ({ caller, activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart || !caller) {
            Debug("melon_paint: activator wasn't a tracked melon, ignoring");
            return;
        }
        const match = PAINT_TRIGGER_NAME_PATTERN.exec(caller.GetEntityName());
        if (!match) {
            Debug(`melon_paint: trigger "${caller.GetEntityName()}" doesn't match paint_trigger_<r>_<g>_<b>, ignoring`);
            return;
        }
        const [, r, g, b] = match.map(Number);
        SetKartPaintColor(kart, { r, g, b, a: 255 });
        Debug(`melon_paint: slot ${kart.pawn.GetPlayerController()?.GetPlayerSlot()} painted (${r}, ${g}, ${b})`);
    });

    // Respawn trigger: any trigger_multiple (filtered to prop_physics) whose
    // OnStartTouch calls RunScriptInput "melon_respawn" puts the touching melon
    // straight back at its respawn point (last checkpoint, else start/hub/
    // tutorial spawn) — for drops off an open track. Unlike melon_break: no
    // break, no effects, no delay; same as the user menu's respawn button.
    Instance.OnScriptInput("melon_respawn", ({ activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart) {
            Debug("melon_respawn: activator wasn't a tracked melon, ignoring");
            return;
        }
        if (kart.breaking || kart.locked) {
            return; // respawns on its own already, or parked by the race flow (countdown, finished)
        }
        Debug(`melon_respawn: slot ${kart.pawn.GetPlayerController()?.GetPlayerSlot()} sent back to its respawn point`);
        RespawnKartAtCheckpoint(kart);
    });
}

// A player's kart: spawning the melon and freezing the pawn (spawn.js), the
// spawn entities (spawn-points.js), moving the melon on purpose
// (teleport.js), its look — paint and glow (look.js) — and the player
// lifecycle / paint trigger inputs (inputs.js). The kart record itself and
// the registry of all karts are in core/kart-registry.js.

// Water zones (WATER_* in zones/water/constants.js). Pure rules, no cs_script
// import; zones/water/water.js applies them (test/zones/water.test.mjs).

/**
 * What's left of a velocity (or spin) when the melon lands in water: every
 * axis scaled by WATER_ENTRY_SPEED_KEEP.
 * @param {{ x: number, y: number, z: number }} v
 */
function WaterEntryVelocity(v) {
    return { x: v.x * WATER_ENTRY_SPEED_KEEP, y: v.y * WATER_ENTRY_SPEED_KEEP, z: v.z * WATER_ENTRY_SPEED_KEEP };
}

// Engine side of water zones (WATER_* in constants.js): stopping a melon that
// lands in water. Which water zones the melon is in is tracked in
// ../registry.js (InWater); UpdateKart skips impact and wall-bounce detection
// while it's inside.

/**
 * The melon just entered a water zone: it loses its momentum at once — speed
 * and spin (see WATER_ENTRY_SPEED_KEEP), a boosted speed cap and the
 * momentum run. The per-tick tracking is cleared, so the stop isn't read as
 * an impact (damage) or a wall hit. A broken melon is frozen anyway.
 * @param {import("../../core/kart-registry.js").Kart} kart
 */
function StopInWater(kart) {
    if (kart.breaking) {
        return;
    }
    kart.melon.Move({
        velocity: WaterEntryVelocity(kart.melon.GetAbsVelocity()),
        angularVelocity: WaterEntryVelocity(kart.melon.GetAbsAngularVelocity()),
    });
    kart.lastVelocity = undefined;
    kart.prevLastVelocity = undefined;
    kart.prevOrigin = undefined;
    kart.settled = false;
    kart.speedCap = undefined;
    kart.momentum = undefined;
    kart.lastWallContact = undefined;
}

// The generic teleporter input, melon_teleport.

function RegisterTeleportInput() {
    // Generic teleporter — see TELEPORT_TRIGGER_NAME_PATTERN for the Hammer
    // convention: the destination comes from the touched trigger's own name
    // (teleport_to_<destination>), so every teleporter shares this handler.
    // Msg, not Debug, for wiring mistakes: a teleporter that silently does
    // nothing is hard to spot otherwise.
    Instance.OnScriptInput("melon_teleport", ({ caller, activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart || !caller) {
            Debug("melon_teleport: activator wasn't a tracked melon, ignoring");
            return;
        }
        if (kart.breaking || kart.locked) {
            return; // broken (about to respawn) or parked by the race flow — leave it where it is
        }
        const triggerName = caller.GetEntityName();
        const parsed = ParseTeleportTrigger(triggerName);
        if (!parsed) {
            Instance.Msg(`[melon_drive] melon_teleport: trigger "${triggerName}" isn't named teleport_[stop_|keep_][checkpoint_]to_<destination>, ignoring`);
            return;
        }
        const destinationName = parsed.destination;
        const destination = Instance.FindEntityByName(destinationName);
        if (!destination) {
            Instance.Msg(`[melon_drive] melon_teleport: trigger "${triggerName}" points at "${destinationName}", but no entity has that name`);
            return;
        }
        const yaw = destination.GetAbsAngles().yaw;
        // Lifted like the race-flow teleports: a destination placed on (or
        // sunk into) the floor would otherwise embed the melon in it.
        const position = Lifted(destination.GetAbsOrigin(), TELEPORT_UP_OFFSET);
        const angles = LevelAngles(yaw);
        TeleportKartTo(kart, position, angles, TeleportExitVelocity(kart.melon.GetAbsVelocity(), yaw, parsed.keepSpeed));
        if (parsed.setsRespawn) {
            // Only the respawn point — track progress stays untouched, so this
            // can't skip a race checkpoint.
            kart.checkpointPosition = position;
            kart.checkpointAngles = angles;
        }
        Debug(`melon_teleport: slot ${kart.pawn.GetPlayerController()?.GetPlayerSlot()} -> "${destinationName}"${parsed.setsRespawn ? " (new respawn point)" : ""}`);
    });
}

// Script inputs of the zone triggers — heal, lift, camera, side-view, water and jump recharge zones, jump pads,
// plus the teleporters (teleport/inputs.js). The zones all work
// the same way: OnStartTouch -> "<kind>_enter", OnEndTouch -> "<kind>_leave",
// and the touched trigger's own name may carry its value (heal_zone_<rate>,
// lift_zone_<speed>, camera_zone_<distance>_<height>). What the zones do is in
// registry.js and the systems reading it (healing, wall rules, cameras).

/**
 * @param {string} enterInput @param {string} leaveInput
 * @param {import("./registry.js").ZoneKind} kind
 * @param {(triggerName: string) => any} valueFromName @param {string} unit for the debug log
 * @param {(kart: import("../core/kart-registry.js").Kart) => void} [onEnter] e.g. an effect on entering
 */
function RegisterZone(enterInput, leaveInput, kind, valueFromName, unit, onEnter) {
    Instance.OnScriptInput(enterInput, ({ caller, activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart || !caller) {
            Debug(`${enterInput}: activator wasn't a tracked melon, ignoring`);
            return;
        }
        const value = valueFromName(caller.GetEntityName());
        EnterZone(kart, kind, caller, value);
        onEnter?.(kart);
        Debug(`${enterInput}: slot ${kart.pawn.GetPlayerController()?.GetPlayerSlot()} in "${caller.GetEntityName()}" (${typeof value === "object" ? JSON.stringify(value) : value} ${unit})`);
    });
    Instance.OnScriptInput(leaveInput, ({ caller, activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (kart && caller) {
            LeaveZone(kart, kind, caller);
        }
    });
}

function RegisterZoneInputs() {
    // Heal zones (incl. heal_zone_full) — everything else about healing is in health/heal/.
    RegisterZone("heal_enter", "heal_leave", "healZones", HealZoneRate, "health/s", PlayHealEffect);
    // Lift zones — see lift/constants.js. Read by CurrentWallRules (every wall
    // bounce and wall jump) and the lift camera.
    RegisterZone("lift_enter", "lift_leave", "liftZones", LiftZoneUpSpeed, "u/s up per bounce");
    // Camera zones — see CAMERA_ZONE_* in camera-zone/constants.js. Read by the zone camera (camera/zone-zoom/).
    RegisterZone("camera_enter", "camera_leave", "cameraZones", CameraZoneFromName, "extra back/up");
    // Side-view zones — see side-view/constants.js. Read by UpdateKart (2D driving) and the side camera (camera/side-view/).
    RegisterZone("side_view_enter", "side_view_leave", "sideViews", SideViewFromName, "yaw/distance/height");
    // Jump pads — see jump-pad/constants.js. Read by jump-pad/jump-pad.js (launch, no damage).
    RegisterZone("jump_pad_enter", "jump_pad_leave", "jumpPads", JumpPadFromName, "up/forward u/s");
    // Water zones (a trigger around a func_water) — see water/constants.js:
    // landing in one stops the melon, and UpdateKart reads no impacts inside.
    RegisterZone("water_enter", "water_leave", "waterZones", () => 1, "(water)", StopInWater);
    // Jump recharge zones — see jump-recharge/logic.js. Read by UpdateKart:
    // the wall-jump charges are kept full inside.
    RegisterZone("jump_recharge_enter", "jump_recharge_leave", "jumpRecharges", () => 1, "(jump recharge)");
    RegisterTeleportInput();
}

// Map triggers that change what a melon does while it's inside: lift/,
// jump-pad/, camera-zone/, side-view/, water/, jump-recharge/ (heal zones are in health/heal/), plus the
// teleporters (teleport/). registry.js tracks which zones a melon is in;
// inputs.js registers every *_enter/*_leave and melon_teleport input.

// The hub's script inputs: hub_enter/hub_leave (the start modal) and
// hub_teleport (send a melon to the hub).

function RegisterHeatInputs() {
    // Hub: place a trigger_multiple named "hub_start_trigger" in the hub area,
    // filtered to prop_physics like the checkpoints, with OnStartTouch/OnEndTouch
    // calling RunScriptInput "hub_enter"/"hub_leave" on this point_script. While a
    // kart is inside it, that player sees the "Jetzt starten" modal (or a
    // "race in progress" message if a heat is already running) — see
    // GAMEPLAY.md's "Hub -> race -> next-track flow".
    Instance.OnScriptInput("hub_enter", ({ caller, activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart) {
            Debug("hub_enter: activator wasn't a tracked melon, ignoring");
            return;
        }
        // Only the hub's own start area may open the start modal. A trigger
        // elsewhere wired to hub_enter by mistake (the intro's pass-through to
        // the hub was — that should be hub_teleport) showed "start race" to
        // players just driving through, and without a matching hub_leave it
        // never closed again. test/map/map-io.test.mjs catches this in the .vmap.
        // trim(): Hammer happily keeps a stray trailing space in a name (the map's
        // hub trigger had one), which would otherwise reject the real trigger.
        const callerName = caller?.GetEntityName().trim();
        if (callerName !== HUB_TRIGGER_NAME) {
            Instance.Msg(`[melon_drive] hub_enter fired by "${callerName ?? "?"}", not "${HUB_TRIGGER_NAME}" — ignoring. To send melons to the hub, use RunScriptInput hub_teleport instead.`);
            return;
        }
        kart.inHub = true;
        const slot = kart.pawn.GetPlayerController()?.GetPlayerSlot();
        if (slot !== undefined) {
            ShowHubModal(slot, kart, phase);
        }
    });

    Instance.OnScriptInput("hub_leave", ({ activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart) {
            return;
        }
        kart.inHub = false;
        const slot = kart.pawn.GetPlayerController()?.GetPlayerSlot();
        if (slot !== undefined) {
            HideHubModal(slot, kart);
        }
    });

    // Hub teleporter: any trigger_multiple (filtered to prop_physics) whose
    // OnStartTouch calls RunScriptInput "hub_teleport" on this point_script sends
    // the touching melon back to the hub — same single-kart path as the user
    // menu's hub button, so a racer who rolls over it also leaves the heat.
    Instance.OnScriptInput("hub_teleport", ({ activator }) => {
        const kart = activator && FindKartByMelon(activator);
        if (!kart) {
            Debug("hub_teleport: activator wasn't a tracked melon, ignoring");
            return;
        }
        Debug(`hub_teleport: slot ${kart.pawn.GetPlayerController()?.GetPlayerSlot()} returning to hub (racing=${kart.racing}, phase=${phase})`);
        ReturnAllToHub([kart]);
    });
}

// Racing: the tracks read from trigger names (track-config.js), checkpoint and
// lap progress (checkpoints/), the time trial clock and best times
// (time-trial/), and the hub -> countdown -> racing -> break flow (heat/).

function RegisterRaceInputs() {
    RegisterCheckpointAndFinishInputs();
    RegisterHeatInputs();
}

// Developer aids only: the user menu's collision debug view (collision-debug.js),
// its free look (free-look.js) and the attack button log (attack-debug.js, with DEBUG on).

// Movers (MOVER_* in world/mover/constants.js). Pure rules, no cs_script
// import; world/mover/mover.js applies them (test/world/mover.test.mjs).

/**
 * A mover's config from its entity name, or undefined if the name doesn't
 * make it one.
 * @param {string} name
 * @returns {{ wait: number } | undefined} wait: seconds it stands at each end
 */
function ParseMoverName(name) {
    const match = MOVER_NAME_PATTERN.exec(name);
    if (!match) {
        return undefined;
    }
    return { wait: match[1] === undefined ? MOVER_DEFAULT_WAIT : Number(match[1]) };
}

// Starting the map's movers and keeping them going back and forth (see
// world/mover/constants.js). Each mover's output connections are kept here,
// by entity, so one is never set up twice and a hot reload can swap them
// for its new callbacks.

/** @typedef {import("cs_script/point_script").Entity} Entity */

/** mover entity -> its OnFullyOpen/OnFullyClosed connection ids. @type {Map<Entity, (number | undefined)[]>} */
const movers = new Map();

/** @param {Entity} mover @param {number} wait */
function Connect(mover, wait) {
    const turn = (/** @type {string} */ input) => () => {
        Instance.EntFireAtTarget({ target: mover, input, delay: wait });
    };
    movers.set(mover, [
        Instance.ConnectOutput(mover, "OnFullyOpen", turn("Close")),
        Instance.ConnectOutput(mover, "OnFullyClosed", turn("Open")),
    ]);
}

/** Drops a mover's connections (and the entry). @param {Entity} mover */
function Disconnect(mover) {
    for (const id of movers.get(mover) ?? []) {
        if (id !== undefined) {
            Instance.DisconnectOutput(id);
        }
    }
    movers.delete(mover);
}

/**
 * Sets up and starts every mover that isn't going yet: on activation, and
 * after a round restart (which may have respawned them). One already
 * running is left alone — an Open would turn it round mid-way.
 */
function StartMovers() {
    for (const mover of [...movers.keys()]) {
        if (!mover.IsValid()) {
            Disconnect(mover);
        }
    }
    for (const mover of Instance.FindEntitiesByClass(MOVER_CLASS)) {
        const config = ParseMoverName(mover.GetEntityName());
        if (!config || movers.has(mover)) {
            continue;
        }
        Connect(mover, config.wait);
        Instance.EntFireAtTarget({ target: mover, input: "Open" });
        Debug(`StartMovers: ${mover.GetEntityName()} started, wait ${config.wait}s`);
    }
}

/**
 * After a hot reload: the movers carried over from before keep moving, but
 * their connections point at the old script's callbacks — swap them for
 * new ones (no Open, they're already on their way).
 * @param {Map<Entity, (number | undefined)[]> | undefined} previous
 */
function RestoreMovers(previous) {
    // A copy: `previous` may be `movers` itself, which this loop changes.
    for (const [mover, ids] of [...(previous ?? [])]) {
        movers.set(mover, ids);
        Disconnect(mover);
        const config = mover.IsValid() ? ParseMoverName(mover.GetEntityName()) : undefined;
        if (config) {
            Connect(mover, config.wait);
        }
    }
}

/** Starts the movers when the script activates and after every round restart. */
function RegisterMoverInputs() {
    Instance.OnActivate(StartMovers);
    Instance.OnRoundStart(StartMovers);
}

// Map entities the script keeps running on their own, not tied to a kart:
// mover/ (func_movelinears going back and forth).

Instance.SetThink(Think);
Instance.SetNextThink(Instance.GetGameTime());

// Tools-mode hot reload re-runs this whole file top-to-bottom, which would
// otherwise reset `karts` to an empty Map while the previously spawned
// melons are still alive in the world — the next respawn would then spawn
// a *second* melon on top of the orphaned one and the two would violently
// shove each other apart. Carry the existing tracking across the reload.
// Race-flow phase/activeTrackId/phaseEndTime are carried the same way, so
// reloading mid-heat during dev iteration doesn't strand locked racers in a
// phase that's forgotten it's supposed to unlock/advance them.
Instance.OnScriptReload({
    before: () => ({ karts, phase, activeTrackId, phaseEndTime, moderatorSlot, movers }),
    after: (memory) => {
        if (memory?.karts) {
            for (const [slot, kart] of memory.karts) {
                karts.set(slot, kart);
            }
            RestoreRaceFlowSnapshot(memory);
            SetModeratorSlot(memory.moderatorSlot);
            RestoreMovers(memory.movers);
            Debug(`OnScriptReload: restored ${karts.size} kart(s), phase=${phase}, activeTrackId=${activeTrackId}, moderatorSlot=${moderatorSlot}`);
        }
    },
});

RegisterKartInputs(); // OnPlayerReset/OnPlayerDisconnect, melon_paint
RegisterRaceInputs(); // start_/checkpoint_/finish_<trackId>, hub_enter/hub_leave/hub_teleport
RegisterZoneInputs(); // heal/lift/camera/jump pad *_enter/*_leave, melon_teleport
RegisterBreakInputs(); // melon_break
RegisterHudInputs(); // OnCustomHudClicked
RegisterAttackDebug();
RegisterMoverInputs(); // OnActivate/OnRoundStart: start the func_movelinear movers
